window.DATASET_INFO = {"dune": {"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}, "varespec": {"text": "varespec / varechem：24 样方 × 44 种，泥炭地", "url": "https://rdrr.io/cran/vegan/man/varespec.html"}, "mite": {"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}, "BCI": {"text": "BCI / BCI.env：50 样方 × 225 种，巴拿马森林", "url": "https://rdrr.io/cran/vegan/man/BCI.html"}, "lynx": {"text": "lynx：加拿大猞猁皮毛收购量，1821—1934", "url": "https://stat.ethz.ch/R-manual/R-devel/library/datasets/html/lynx.html"}, "pyrifos": {"text": "pyrifos：农药试验浮游动物时间序列", "url": "https://rdrr.io/cran/vegan/man/pyrifos.html"}};
window.CONTENT = {"chapters": [{"title": "第 1 章　基础统计与数据准备", "intro": "", "entries": [{"id": "1.1", "title": "1.1 描述统计与数据画像", "lit": [{"text": "Zuur, Ieno & Elphick (2010). A protocol for data exploration to avoid common statistical problems. *Methods in Ecology and Evolution* 1: 3–14.", "url": "https://search.crossref.org/?q=A%20protocol%20for%20data%20exploration%20to%20avoid%20common%20statistical%20problems"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(vegan); data(dune.env)\nsummary(dune.env)\napply(dune.env[, c(\"A1\",\"Moisture\",\"Manure\")], 2, sd)\ncor(dune.env[, c(\"A1\",\"Moisture\",\"Manure\")])", "resultKind": "实算", "resultText": "得到各变量范围、缺失、异常值与相关矩阵；土壤厚度 A1 与水分 Moisture 常呈正相关。", "interpret": "这一步决定后面用什么模型：连续变量看偏态与离群，分类变量看每类样本量，变量两两相关 > 0.7 就要考虑共线。顶刊论文的补充材料几乎都有这张表。", "fig": "fig_corr.svg", "figCaption": "图：dune.env 三个连续变量的相关矩阵。颜色深浅与数值同时表示相关强度，正相关为绿、负相关为红。", "packages": ["vegan"], "report": "在方法部分写明：数据来源与样本量、变量变换、检验类型（含是否使用 Welch 校正）、效应量与 95% 置信区间、多重比较校正方式。", "pitfalls": ["把重复测量当作独立样本", "只报 p 值不报效应量", "方差不齐仍用 Student t", "事后比较未校正"], "assumptions": ["观测相互独立（重复测量需用配对或混合模型）", "分布与方差假设：t/F 检验要求近似正态、方差齐；不满足时改用 Welch 或秩检验", "样本能代表总体：方便抽样得到的 p 值没有推断意义"], "steps": ["画分布图，检查偏态、离群、缺失与共线", "选择检验：两组/多组、配对与否、方差是否齐", "报告效应量与 95% CI，必要时做多重比较校正"], "figNotes": ["先看对角线外的强相关：|r| > 0.7 就要处理共线", "正负号决定两个变量是同向还是反向变化"], "what": "用均值、离散度、分布形状与相关结构，概括一批数据的整体特征。", "why": "建模前必须先知道数据长什么样：有没有偏态、离群、缺失、共线。选错方法往往不是统计问题，而是没做这一步。", "dataProfile": {"name": "dune + dune.env", "shape": "20 行 × 3 个连续变量 + 2 个分类变量；无缺失。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "3 个连续变量量纲不同、2 个分类变量水平数不一致，先看分布与相关，才能决定后面是否标准化、用哪种模型。"}, {"id": "1.2", "title": "1.2 两样本 t 检验（Welch）", "lit": [{"text": "Student (1908). The probable error of a mean. *Biometrika* 6: 1–25", "url": "https://search.crossref.org/?q=The%20probable%20error%20of%20a%20mean"}, {"text": "Welch (1947). The generalization of \"Student's\" problem. *Biometrika* 34: 28–35.", "url": "https://search.crossref.org/?q=The%20generalization%20of%20%22Student%27s%22%20problem"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(vegan); data(dune); data(dune.env)\nH <- diversity(dune, \"shannon\")\nt.test(H ~ Management, data = dune.env, subset = Management %in% c(\"SF\",\"NM\"))", "resultKind": "实算", "resultText": "SF 均值 2.039，NM 均值 1.997；差值 0.042（95% CI −0.237 至 0.322）；t = 0.297，df = 6.10，p = 0.776。", "interpret": "差异不显著，且置信区间跨越 0 且很宽——说明样本量太小（SF 6 个、NM 6 个），不能区分\"无差异\"与\"功效不足\"。正确写法是报告均值差与 CI，而不是只说 p > 0.05；若要主张\"无差异\"，应做等效性检验（TOST）。", "fig": "fig_ttest.svg", "figCaption": "图：两组 Shannon 多样性的箱线图与原始观测点。中位线接近、箱体高度相似，但置信区间很宽——这正是 p = 0.78 的图形来源。", "packages": ["vegan"], "report": "在方法部分写明：数据来源与样本量、变量变换、检验类型（含是否使用 Welch 校正）、效应量与 95% 置信区间、多重比较校正方式。", "pitfalls": ["把重复测量当作独立样本", "只报 p 值不报效应量", "方差不齐仍用 Student t", "事后比较未校正"], "assumptions": ["观测相互独立（重复测量需用配对或混合模型）", "分布与方差假设：t/F 检验要求近似正态、方差齐；不满足时改用 Welch 或秩检验", "样本能代表总体：方便抽样得到的 p 值没有推断意义"], "steps": ["画分布图，检查偏态、离群、缺失与共线", "选择检验：两组/多组、配对与否、方差是否齐", "报告效应量与 95% CI，必要时做多重比较校正"], "figNotes": ["看中位数差与箱体重叠程度：重叠大、样本少时 p 值不可能小", "看点的散布：两组内部变异都很大，说明效应被噪声淹没", "报告时应给均值差与 95% CI，而不是只说“不显著”"], "what": "比较两组均值是否有差异，并用标准误判断差异是否可能只是抽样波动。", "why": "两组、连续、近似正态时最直接。默认用 Welch 版：它不要求方差齐，几乎不损失功效，比 Student t 更稳。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "Shannon 是连续变量，Management 恰好是两组比较；样本只有 6+6，Welch 不要求方差齐，比 Student t 更稳。"}, {"id": "1.3", "title": "1.3 单因素方差分析", "lit": [{"text": "Fisher (1925). *Statistical Methods for Research Workers*. Oliver & Boyd.", "url": "https://search.crossref.org/?q=%2AStatistical%20Methods%20for%20Research%20Workers%2A"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "fit <- aov(A1 ~ Management, data = dune.env)\nsummary(fit)\nTukeyHSD(fit)", "resultKind": "实算", "resultText": "F(3, 16) = 1.252，p = 0.324，η² = 0.190。", "interpret": "四种管理方式下土层厚度无显著差异，但 η² = 0.19 属中等效应——不显著更可能反映样本量小（每组仅 3—6 个）。这类结果应报告效应量与组均值，并说明功效限制。", "fig": "fig_anova.svg", "figCaption": "图：四种管理方式下 A1 的分布。组间中位数差异不大，组内变异很大，对应 F = 1.25、p = 0.32。", "packages": [], "report": "在方法部分写明：数据来源与样本量、变量变换、检验类型（含是否使用 Welch 校正）、效应量与 95% 置信区间、多重比较校正方式。", "pitfalls": ["把重复测量当作独立样本", "只报 p 值不报效应量", "方差不齐仍用 Student t", "事后比较未校正"], "assumptions": ["观测相互独立（重复测量需用配对或混合模型）", "分布与方差假设：t/F 检验要求近似正态、方差齐；不满足时改用 Welch 或秩检验", "样本能代表总体：方便抽样得到的 p 值没有推断意义"], "steps": ["画分布图，检查偏态、离群、缺失与共线", "选择检验：两组/多组、配对与否、方差是否齐", "报告效应量与 95% CI，必要时做多重比较校正"], "figNotes": ["看四组的中位数是否接近：这里差异很小", "看组内跨度：组内变异远大于组间，F 值自然小", "η²=0.19 属中等效应，不显著更可能是样本量问题"], "what": "把总变异分解为组间与组内，用 F 检验判断多组均值是否全等。", "why": "处理有 3 个以上水平时，两两 t 检验会让 I 类错误迅速膨胀；ANOVA 先做一次整体检验，再决定是否事后比较。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "A1 连续、Management 四个水平，符合单因素方差分析的结构；但组样本量 3—6 不等，必须用不平衡设计的平方和。"}, {"id": "1.4", "title": "1.4 非参数检验（Mann-Whitney / Kruskal-Wallis）", "lit": [{"text": "Mann & Whitney (1947). On a test of whether one of two random variables is stochastically larger than the other. *Annals of Mathematical Statistics*", "url": "https://search.crossref.org/?q=On%20a%20test%20of%20whether%20one%20of%20two%20random%20variables%20is%20stochastically%20larger%20than%20the%20other"}, {"text": "Kruskal & Wallis (1952). Use of ranks in one-criterion variance analysis. *JASA*.", "url": "https://search.crossref.org/?q=Use%20of%20ranks%20in%20one-criterion%20variance%20analysis"}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "library(vegan); data(mite); data(mite.env)\nrich <- rowSums(mite > 0)\nwilcox.test(rich ~ Shrub, data = mite.env)\nkruskal.test(rich ~ Topo, data = mite.env)", "resultKind": "实算", "resultText": "灌木少组中位数 16 种、灌木多组 18 种；Mann-Whitney U = 238.5，z = −1.63，p = 0.103。按地形分组做 Kruskal-Wallis：H = 10.26，df = 1，p < 0.01。", "interpret": "秩检验只比较分布位置，不要求正态，但对\"分布形状不同\"敏感——若两组方差差异大，显著可能反映离散度而非中位数。报告时应给各组中位数与四分位距。", "fig": "fig_mwu.svg", "figCaption": "图：两组丰富度的累积分布。中位数接近、曲线交叉，对应 Mann-Whitney U = 238.5、p = 0.103。", "packages": ["vegan"], "report": "在方法部分写明：数据来源与样本量、变量变换、检验类型（含是否使用 Welch 校正）、效应量与 95% 置信区间、多重比较校正方式。", "pitfalls": ["把重复测量当作独立样本", "只报 p 值不报效应量", "方差不齐仍用 Student t", "事后比较未校正"], "assumptions": ["观测相互独立（重复测量需用配对或混合模型）", "分布与方差假设：t/F 检验要求近似正态、方差齐；不满足时改用 Welch 或秩检验", "样本能代表总体：方便抽样得到的 p 值没有推断意义"], "steps": ["画分布图，检查偏态、离群、缺失与共线", "选择检验：两组/多组、配对与否、方差是否齐", "报告效应量与 95% CI，必要时做多重比较校正"], "figNotes": ["曲线整体右移表示该组数值更大", "两条中位数线交叉，说明差异不稳定"], "what": "用秩代替原始数值，比较两组或多组的分布位置。", "why": "数据偏态、有序分类、样本很小或有离群点时，t/F 的正态与方差假设不成立，秩方法更可靠；代价是功效略低、只比较位置。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "70 个样方的物种数，按灌木盖度分为 34 / 36 两组。", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "丰富度右偏、样本 70、两组方差不齐，秩检验比 t 检验更符合这份数据的分布。"}, {"id": "1.5", "title": "1.5 列联表卡方检验", "lit": [{"text": "Pearson (1900). On the criterion that a given system of deviations… *Philosophical Magazine* 50: 157–175.", "url": "https://search.crossref.org/?q=Pearson%20%281900%29.%20On%20the%20criterion%20that%20a%20given%20system%20of%20deviations%E2%80%A6%20%2APhilosophic"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "tab <- table(dune.env$Management, dune.env$Use)\nchisq.test(tab)\nfisher.test(tab, simulate.p.value = TRUE)", "resultKind": "实算", "resultText": "χ² = 8.89，df = 6，p = 0.180，Cramér's V = 0.471。", "interpret": "管理方式与土地利用类型无显著关联，但 V = 0.47 表示中等强度关联——同样是样本量限制。注意：期望频数 < 5 的格子超过 20% 时，应改用 Fisher 精确检验或模拟 p 值。", "fig": "fig_chisq.svg", "figCaption": "图：Management × Use 的列联表条形图。各类组合的样本数都不大，是卡方检验功效不足的直接原因。", "packages": [], "report": "在方法部分写明：数据来源与样本量、变量变换、检验类型（含是否使用 Welch 校正）、效应量与 95% 置信区间、多重比较校正方式。", "pitfalls": ["把重复测量当作独立样本", "只报 p 值不报效应量", "方差不齐仍用 Student t", "事后比较未校正"], "assumptions": ["观测相互独立（重复测量需用配对或混合模型）", "分布与方差假设：t/F 检验要求近似正态、方差齐；不满足时改用 Welch 或秩检验", "样本能代表总体：方便抽样得到的 p 值没有推断意义"], "steps": ["画分布图，检查偏态、离群、缺失与共线", "选择检验：两组/多组、配对与否、方差是否齐", "报告效应量与 95% CI，必要时做多重比较校正"], "figNotes": ["看每个格子的样本数：多数格子只有 2—5 个样方", "期望频数过小会让卡方近似失效", "结论应表述为“无证据支持关联”，而非“两者独立”"], "what": "比较观测频数与期望频数的偏离，检验两个分类变量是否独立。", "why": "分类数据（生境类型 × 是否出现）没有均值可比，只能比频数。样本小或期望频数低时改用 Fisher 精确检验。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "Management 与 Use 都是分类变量，只能构成列联表；20 个样方使部分格子频数很低，需注意卡方近似是否成立。"}, {"id": "1.6", "title": "1.6 相关分析（Pearson / Spearman）", "lit": [{"text": "Pearson (1896). Mathematical contributions to the theory of evolution. *Philosophical Transactions of the Royal Society A*", "url": "https://search.crossref.org/?q=Mathematical%20contributions%20to%20the%20theory%20of%20evolution"}, {"text": "Spearman (1904). The proof and measurement of association between two things. *American Journal of Psychology*.", "url": "https://search.crossref.org/?q=The%20proof%20and%20measurement%20of%20association%20between%20two%20things"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "data(varechem)\ncor.test(varechem$N, varechem$pH, method = \"pearson\")\ncor.test(varechem$N, varechem$pH, method = \"spearman\")", "resultKind": "实算", "resultText": "Pearson r = −0.042（n = 24，p ≈ 0.85）；Spearman ρ = −0.072。", "interpret": "相关只描述线性/单调关联；r 对离群值与取值范围极敏感。生态学中更常用 Spearman（秩相关），因为环境变量常偏态。报告要写 r、n、p 与散点图。", "fig": "fig_corr_scatter.svg", "figCaption": "图：钙与氮的散点与拟合线。相关系数很弱，说明二者在本数据集中几乎不相关。", "packages": [], "report": "在方法部分写明：数据来源与样本量、变量变换、检验类型（含是否使用 Welch 校正）、效应量与 95% 置信区间、多重比较校正方式。", "pitfalls": ["把重复测量当作独立样本", "只报 p 值不报效应量", "方差不齐仍用 Student t", "事后比较未校正"], "assumptions": ["观测相互独立（重复测量需用配对或混合模型）", "分布与方差假设：t/F 检验要求近似正态、方差齐；不满足时改用 Welch 或秩检验", "样本能代表总体：方便抽样得到的 p 值没有推断意义"], "steps": ["画分布图，检查偏态、离群、缺失与共线", "选择检验：两组/多组、配对与否、方差是否齐", "报告效应量与 95% CI，必要时做多重比较校正"], "figNotes": ["看散点是否成线性、有没有离群点", "r 只描述线性关联，非线性关系会被低估"], "what": "度量两个变量线性（Pearson）或单调（Spearman）关联的强度与方向。", "why": "探索性分析的第一步，用于快速筛变量、发现共线。但它不说明因果，也捕捉不到非线性和交互。", "dataProfile": {"name": "模拟数据", "shape": "24 个样方的 Ca 与 N 两个连续变量。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "Ca 与 N 都是连续变量、样本 24，适合先看相关；若关系非线性，相关会低估，需回到散点图。"}, {"id": "1.7", "title": "1.7 简单线性回归", "lit": [{"text": "Galton (1886). Regression towards mediocrity in hereditary stature. *Journal of the Anthropological Institute* 15: 246–263.", "url": "https://search.crossref.org/?q=Regression%20towards%20mediocrity%20in%20hereditary%20stature"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "m <- lm(N ~ pH, data = varechem)\nsummary(m); confint(m); plot(m)", "resultKind": "实算", "resultText": "斜率 = −1.089（SE 5.50），截距 25.58；R² = 0.002，F 检验 p = 0.845。", "interpret": "pH 几乎不解释氮含量（R² ≈ 0）。此时不要硬解释斜率；应检查非线性、离群点与变量变换。若换成 N ~ 有机质或 N ~ Ca，R² 会明显提高——说明变量选择比模型形式更关键。", "fig": "fig_lm.svg", "figCaption": "图：N 与 pH 的散点与拟合线。斜率接近水平，R² = 0.002，说明 pH 几乎不解释氮含量。", "packages": [], "report": "在方法部分写明：数据来源与样本量、变量变换、检验类型（含是否使用 Welch 校正）、效应量与 95% 置信区间、多重比较校正方式。", "pitfalls": ["把重复测量当作独立样本", "只报 p 值不报效应量", "方差不齐仍用 Student t", "事后比较未校正"], "assumptions": ["观测相互独立（重复测量需用配对或混合模型）", "分布与方差假设：t/F 检验要求近似正态、方差齐；不满足时改用 Welch 或秩检验", "样本能代表总体：方便抽样得到的 p 值没有推断意义"], "steps": ["画分布图，检查偏态、离群、缺失与共线", "选择检验：两组/多组、配对与否、方差是否齐", "报告效应量与 95% CI，必要时做多重比较校正"], "figNotes": ["看散点是否呈任何趋势：这里几乎是水平云", "看拟合线斜率与 R²：R²=0.002 表示几乎无解释力", "不要因为 p 不显著就断言“pH 不重要”，需检查范围与非线性"], "what": "用一条直线描述 Y 随 X 的平均变化，并给出斜率及其不确定性。", "why": "比相关多一个可解释的斜率：X 每增加一个单位，Y 平均变化多少。需要方向、大小与置信区间时用它。", "dataProfile": {"name": "模拟数据", "shape": "按方法假设生成的结构化数据", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "两个连续变量、无分组、样本 24，线性回归是最小假设的起点；斜率可解释为“pH 每增加 1 单位 N 的平均变化”。"}, {"id": "1.8", "title": "1.8 多重比较与效应量", "lit": [{"text": "Tukey (1949). Comparing individual means in the analysis of variance. *Biometrics*", "url": "https://search.crossref.org/?q=Comparing%20individual%20means%20in%20the%20analysis%20of%20variance"}, {"text": "Benjamini & Hochberg (1995). Controlling the false discovery rate. *JRSS B* 57: 289–300.", "url": "https://search.crossref.org/?q=Controlling%20the%20false%20discovery%20rate"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(emmeans)\nemm <- emmeans(fit, ~ Management)\npairs(emm, adjust = \"tukey\")\neff_size(emm, sigma = sigma(fit), edf = df.residual(fit))\np.adjust(c(0.01, 0.02, 0.04, 0.20), method = \"BH\")", "resultKind": "实算", "resultText": "输出 6 组两两比较的差值、CI 与校正 p。", "interpret": "Tukey 控制族错误率，适合\"所有两两比较\"；Dunnett 适合\"都与对照比\"；FDR 适合\"大量物种/变量筛选\"。报告必须说明用了哪种校正，以及校正前后的 p。", "fig": "fig_padjust.svg", "figCaption": "图：同一批 p 值在 Bonferroni 与 BH-FDR 校正后的变化。FDR 保留更多“发现”，但假阳性也更多。", "packages": ["emmeans"], "report": "在方法部分写明：数据来源与样本量、变量变换、检验类型（含是否使用 Welch 校正）、效应量与 95% 置信区间、多重比较校正方式。", "pitfalls": ["把重复测量当作独立样本", "只报 p 值不报效应量", "方差不齐仍用 Student t", "事后比较未校正"], "assumptions": ["观测相互独立（重复测量需用配对或混合模型）", "分布与方差假设：t/F 检验要求近似正态、方差齐；不满足时改用 Welch 或秩检验", "样本能代表总体：方便抽样得到的 p 值没有推断意义"], "steps": ["画分布图，检查偏态、离群、缺失与共线", "选择检验：两组/多组、配对与否、方差是否齐", "报告效应量与 95% CI，必要时做多重比较校正"], "figNotes": ["原始 p 与校正 p 的差距随比较次数增加", "FDR 比 Bonferroni 保留更多发现，但假阳性也更多"], "what": "在多次检验中控制整体错误率（FWER）或假发现率（FDR）。", "why": "比较次数一多，纯靠偶然也会出现“显著”。不校正等于自欺；但一律 Bonferroni 又会把真实效应全杀掉，所以按场景选方法。", "dataProfile": {"name": "模拟数据", "shape": "8 个物种在 SF 与 NM 两组间的 8 个置换 p 值。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "8 个物种同时做组间比较，若不校正，8 次检验中至少一次假阳性的概率接近 1/3。"}, {"id": "1.9", "title": "1.9 功效分析与样本量", "lit": [{"text": "Cohen (1988). *Statistical Power Analysis for the Behavioral Sciences*", "url": "https://search.crossref.org/?q=Cohen%20%281988%29.%20%2AStatistical%20Power%20Analysis%20for%20the%20Behavioral%20Sciences%2A"}, {"text": "Green & MacLeod (2016). SIMR: an R package for power analysis of generalized linear mixed models. *Methods in Ecology and Evolution* 7: 493–498.", "url": "https://search.crossref.org/?q=SIMR%3A%20an%20R%20package%20for%20power%20analysis%20of%20generalized%20linear%20mixed%20models"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(pwr)\npwr.t.test(d = 0.3/0.35, sig.level = 0.05, power = 0.8)", "resultKind": "实算", "resultText": "每组约需 22 个样本。", "interpret": "功效分析应在实验前做。事后用观测效应量算\"已获得功效\"是循环论证。混合模型用 `simr::powerSim` 模拟；多物种数据用置换检验的功效模拟。", "fig": "fig_power.svg", "figCaption": "图：两样本 t 检验的功效随样本量的变化（效应量 d = 0.5）。曲线在每组约 64 个样本时达到 0.8，说明中等效应需要相当大的样本。", "packages": ["pwr"], "report": "在方法部分写明：数据来源与样本量、变量变换、检验类型（含是否使用 Welch 校正）、效应量与 95% 置信区间、多重比较校正方式。", "pitfalls": ["把重复测量当作独立样本", "只报 p 值不报效应量", "方差不齐仍用 Student t", "事后比较未校正"], "assumptions": ["观测相互独立（重复测量需用配对或混合模型）", "分布与方差假设：t/F 检验要求近似正态、方差齐；不满足时改用 Welch 或秩检验", "样本能代表总体：方便抽样得到的 p 值没有推断意义"], "steps": ["画分布图，检查偏态、离群、缺失与共线", "选择检验：两组/多组、配对与否、方差是否齐", "报告效应量与 95% CI，必要时做多重比较校正"], "figNotes": ["曲线越陡，说明增加样本量带来的功效提升越快", "0.8 是常用目标；d = 0.5 时每组约需 64 个样本", "效应量越小，曲线越平缓，所需样本呈平方增长"], "what": "在给定效应量、变异与显著性水平下，计算能检出效应所需的样本量。", "why": "这是设计阶段的工具，决定研究值不值得做。事后用观测效应量算“已获得功效”是循环论证，不能作为证据。", "dataProfile": {"name": "模拟数据", "shape": "按方法假设生成的结构化数据", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "dune 的组间差异约 0.3、SD 约 0.35，用这两个数反推所需样本量，正好解释为什么 20 个样方常常不够。"}, {"id": "1.10", "title": "1.10 数据变换与标准化", "lit": [{"text": "Legendre & Gallagher (2001). Ecologically meaningful transformations for ordination of species data. *Oecologia* 129: 271–280", "url": "https://search.crossref.org/?q=Ecologically%20meaningful%20transformations%20for%20ordination%20of%20species%20data"}, {"text": "Aitchison (1986). *The Statistical Analysis of Compositional Data*.", "url": "https://search.crossref.org/?q=Aitchison%20%281986%29.%20%2AThe%20Statistical%20Analysis%20of%20Compositional%20Data%2A."}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}, {"text": "varespec / varechem：24 样方 × 44 种，泥炭地", "url": "https://rdrr.io/cran/vegan/man/varespec.html"}], "code": "library(vegan)\nd_hel <- decostand(dune, \"hellinger\")   # 群落：Hellinger\nd_wis <- wisconsin(dune)                # 双重标准化\nd_pa  <- decostand(dune, \"pa\")          # 二元\n# 组成数据（相对丰度）：\n# library(compositions); clr(comm + 0.5)", "resultKind": "实算", "resultText": "Hellinger 后方差更稳定、优势种影响下降。", "interpret": "变换是\"科学假设\"的一部分：Hellinger 强调相对组成，Wisconsin 同时压缩样方与物种，CLR 处理\"和为 1\"的约束。变换必须在看结果前确定，否则等于变相 p-hacking。", "fig": "fig_transform.svg", "figCaption": "图：物种方差在变换前后的关系。Hellinger 变换压低了高方差物种，使结果不再由少数优势种主导。", "packages": ["vegan"], "report": "在方法部分写明：数据来源与样本量、变量变换、检验类型（含是否使用 Welch 校正）、效应量与 95% 置信区间、多重比较校正方式。", "pitfalls": ["把重复测量当作独立样本", "只报 p 值不报效应量", "方差不齐仍用 Student t", "事后比较未校正"], "assumptions": ["观测相互独立（重复测量需用配对或混合模型）", "分布与方差假设：t/F 检验要求近似正态、方差齐；不满足时改用 Welch 或秩检验", "样本能代表总体：方便抽样得到的 p 值没有推断意义"], "steps": ["画分布图，检查偏态、离群、缺失与共线", "选择检验：两组/多组、配对与否、方差是否齐", "报告效应量与 95% CI，必要时做多重比较校正"], "figNotes": ["Hellinger 变换后方差被压缩，点落在 1:1 线下方", "压缩过强会丢掉真实的种间差异"], "what": "用单调函数改变数据尺度，使方差稳定、分布接近正态，或压缩优势项的影响。", "why": "GLM、排序、距离方法都隐含尺度假设。变换是让假设成立最便宜的手段，但必须在看结果之前确定，否则就是变相 p-hacking。", "dataProfile": {"name": "dune + dune.env", "shape": "30 个物种在 20 个样方中的多度；变换前后各算一次方差。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "dune 多度右偏、优势种方差极大；Hellinger 变换后方差被压缩，才适合做 PCA/RDA 这类基于欧氏距离的方法。"}]}, {"title": "第 2 章　多样性度量", "intro": "", "entries": [{"id": "2.1", "title": "2.1 物种丰富度", "lit": [{"text": "Whittaker (1972). Evolution and measurement of species diversity. *Taxon* 21: 213–251.", "url": "https://search.crossref.org/?q=Evolution%20and%20measurement%20of%20species%20diversity"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(vegan); data(dune)\nS <- specnumber(dune)\nsummary(S)", "resultKind": "实算", "resultText": "平均 9.85 种，范围 5—14 种；最少的是样方 1（5 种），最多的是样方 5（14 种）。", "interpret": "丰富度是最直观但最依赖样本量的指标。比较不同研究前必须统一抽样努力，否则\"物种更多的样方\"可能只是\"采得更狠\"。", "fig": "fig_richness.svg", "figCaption": "图：20 个样方的物种丰富度。样方 1 最低（5 种），样方 5 最高（14 种）。", "packages": ["vegan"], "report": "报告多样性指数时给出指数名称、q 值（Hill 数）、抽样是否标准化（稀疏化/覆盖率），以及置信区间。", "pitfalls": ["直接比较不同样本量的物种数", "把 H′ 当作物种数", "忽略未鉴定种", "只报一个 q 值"], "assumptions": ["抽样努力可比：否则物种数差异可能只是采样量差异", "分类分辨率一致：不同研究的“种”定义必须对齐", "未鉴定种与稀有种的处理方式要预先说明"], "steps": ["先把抽样努力标准化（稀疏化或覆盖率）", "计算 α/β 多样性及置信区间", "比较多样性时同时报告丰富度与均匀度，避免单一指数"], "figNotes": ["柱高即物种数，但必须结合抽样努力解释", "不同研究的柱高不能直接比较"], "what": "群落中出现的物种数目。", "why": "最直观的多样性度量，但强烈依赖样本量：采得越多、看到越多。单独报告丰富度而不说明抽样努力，几乎没有比较价值。", "dataProfile": {"name": "dune + dune.env", "shape": "20 × 30 多度矩阵，逐行求和得到丰富度。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "20 个样方、67% 为零的稀疏矩阵，逐行数非零即得丰富度；但它与样方总量高度相关，必须和抽样努力一起看。"}, {"id": "2.2", "title": "2.2 稀疏化（rarefaction）", "lit": [{"text": "Sanders (1968). Marine benthic diversity: a comparative study. *American Naturalist* 102: 243–282", "url": "https://search.crossref.org/?q=Marine%20benthic%20diversity%3A%20a%20comparative%20study"}, {"text": "Hurlbert (1971). The nonconcept of species diversity. *Ecology* 52: 577–586.", "url": "https://search.crossref.org/?q=The%20nonconcept%20of%20species%20diversity"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "rarecurve(dune, sample = 10, label = FALSE)\nrarefy(dune, sample = 10)", "resultKind": "实算", "resultText": "统一到 10 个个体时，各样方期望物种数为 4.33、6.76、6.53、7.15、7.54……（前 5 个样方）；明显低于原始丰富度，说明多数样方的调查强度不足。", "interpret": "稀疏化把样本量压到共同水平再比较，是多样性比较的\"最低门槛\"。但它只做\"减法\"，会浪费大数据集的信息；现代做法用 iNEXT 同时做稀疏化与外推，并报告覆盖率。", "fig": "fig_rare.svg", "figCaption": "图：两个样方的稀疏化曲线。样方 5 的曲线始终在上方，说明其多样性更高；曲线趋于平缓表示抽样接近充分。", "packages": [], "report": "报告多样性指数时给出指数名称、q 值（Hill 数）、抽样是否标准化（稀疏化/覆盖率），以及置信区间。", "pitfalls": ["直接比较不同样本量的物种数", "把 H′ 当作物种数", "忽略未鉴定种", "只报一个 q 值"], "assumptions": ["抽样努力可比：否则物种数差异可能只是采样量差异", "分类分辨率一致：不同研究的“种”定义必须对齐", "未鉴定种与稀有种的处理方式要预先说明"], "steps": ["先把抽样努力标准化（稀疏化或覆盖率）", "计算 α/β 多样性及置信区间", "比较多样性时同时报告丰富度与均匀度，避免单一指数"], "figNotes": ["曲线越陡说明抽样越不充分；趋于平缓表示接近饱和", "两条曲线的相对位置才是可比信息，终点高度不可直接比", "报告时应给覆盖率（>0.95 表示较充分）"], "what": "把不同样本量统一到同一水平，再比较期望物种数。", "why": "直接比物种数会被抽样量污染。稀疏化做了“减法”，让比较公平；代价是丢掉大数据集的信息。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "各样方个体总数差异很大（18—60），直接比物种数不公平；稀疏化把所有样方压到同一水平再比。"}, {"id": "2.3", "title": "2.3 Chao1 物种数估计", "lit": [{"text": "Chao (1984). Nonparametric estimation of the number of classes in a population. *Scandinavian Journal of Statistics* 11: 265–270.", "url": "https://search.crossref.org/?q=Nonparametric%20estimation%20of%20the%20number%20of%20classes%20in%20a%20population"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}, {"text": "BCI / BCI.env：50 样方 × 225 种，巴拿马森林", "url": "https://rdrr.io/cran/vegan/man/BCI.html"}], "code": "library(vegan)\nestimateR(dune)[\"S.chao1\", ]\n# BCI：逐样方估计\napply(BCI, 1, function(x) estimateR(x)[\"S.chao1\"])", "resultKind": "实算", "resultText": "dune 各样方 Chao1 均值 9.85，与观测丰富度几乎相同（该数据集中仅出现一次的物种很少，校正项接近 0）；BCI 各样方观测丰富度均值 90.8，而 Chao1 均值 125.5，高出约 38%，说明大量稀有种未被记录。", "interpret": "Chao1 用\"仅出现 1 次/2 次\"的物种数校正未观测种。它给出的是\"下限估计\"，且方差很大；在抽样极不充分时（如 BCI 每样方仅记录部分个体），估计值会远高于观测值，此时应报告置信区间而非单点。", "fig": "fig_chao.svg", "figCaption": "图：BCI 各样方的观测丰富度与 Chao1 估计。点普遍高于 1:1 线，说明仍有稀有种未被记录。", "packages": ["vegan"], "report": "报告多样性指数时给出指数名称、q 值（Hill 数）、抽样是否标准化（稀疏化/覆盖率），以及置信区间。", "pitfalls": ["直接比较不同样本量的物种数", "把 H′ 当作物种数", "忽略未鉴定种", "只报一个 q 值"], "assumptions": ["抽样努力可比：否则物种数差异可能只是采样量差异", "分类分辨率一致：不同研究的“种”定义必须对齐", "未鉴定种与稀有种的处理方式要预先说明"], "steps": ["先把抽样努力标准化（稀疏化或覆盖率）", "计算 α/β 多样性及置信区间", "比较多样性时同时报告丰富度与均匀度，避免单一指数"], "figNotes": ["点高于 1:1 线，说明仍有未记录的稀有种", "抽样越不充分，偏离越大"], "what": "用只出现 1 次、2 次的稀有种信息，估计还有多少种没被记录到。", "why": "观测到的物种数只是下限。Chao1 给出更接近真实的下限估计，并提醒你抽样是否充分。", "dataProfile": {"name": "dune + dune.env", "shape": "50 个样方 × 225 种；逐样方计算观测数与 Chao1。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "BCI 的 225 个物种里大量只出现 1—2 次，正是 Chao1 依赖的稀有种信息；没有这些稀有种，校正项就接近 0。"}, {"id": "2.4", "title": "2.4 Shannon-Wiener 指数", "lit": [{"text": "Shannon (1948). A mathematical theory of communication. *Bell System Technical Journal* 27: 379–423", "url": "https://search.crossref.org/?q=A%20mathematical%20theory%20of%20communication"}, {"text": "Spellerberg & Fedor (2003). A tribute to Claude Shannon. *Global Ecology and Biogeography* 12: 177–179.", "url": "https://search.crossref.org/?q=A%20tribute%20to%20Claude%20Shannon"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "H <- diversity(dune, index = \"shannon\")\nround(H, 3); mean(H)", "resultKind": "实算", "resultText": "均值 2.163；范围 1.440（样方 1）—2.544（样方 5）。", "interpret": "H′ 同时受丰富度与均匀度影响，且对样本量敏感。它可以比较，但不能直接解释为\"物种数\"。现代做法是转换为 Hill 数（exp(H′)），使其具有\"有效物种数\"的量纲。", "fig": "fig_shannon.svg", "figCaption": "图：20 个样方的 Shannon 多样性。样方 1 明显偏低（仅 5 种），与稀疏化结果一致。", "packages": [], "report": "报告多样性指数时给出指数名称、q 值（Hill 数）、抽样是否标准化（稀疏化/覆盖率），以及置信区间。", "pitfalls": ["直接比较不同样本量的物种数", "把 H′ 当作物种数", "忽略未鉴定种", "只报一个 q 值"], "assumptions": ["抽样努力可比：否则物种数差异可能只是采样量差异", "分类分辨率一致：不同研究的“种”定义必须对齐", "未鉴定种与稀有种的处理方式要预先说明"], "steps": ["先把抽样努力标准化（稀疏化或覆盖率）", "计算 α/β 多样性及置信区间", "比较多样性时同时报告丰富度与均匀度，避免单一指数"], "figNotes": ["看样方间差异：样方 1 明显低，与它只有 5 种一致", "H′ 同时受丰富度与均匀度影响，不能单独解释", "比较时应统一抽样努力，或改用 Hill 数"], "what": "把物种多度分布的信息熵作为多样性度量。", "why": "同时反映丰富度与均匀度，是文献中最通用的指数。但它对样本量敏感，且不同底数不可直接比较。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "多度矩阵满足“比例”定义，Shannon 可直接算；但它对样本量敏感，所以要和稀疏化一起报告。"}, {"id": "2.5", "title": "2.5 Simpson 指数", "lit": [{"text": "Simpson (1949). Measurement of diversity. *Nature* 163: 688.", "url": "https://search.crossref.org/?q=Measurement%20of%20diversity"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "D <- diversity(dune, index = \"simpson\")   # 1 - sum(p^2)\ninvD <- diversity(dune, index = \"invsimpson\")", "resultKind": "实算", "resultText": "1−D 均值 0.870（前 5 个样方：0.735、0.890、0.879、0.901、0.914）；1/D 均值 8.30（前 5 个：3.77、9.09、8.25……）。", "interpret": "Simpson 对优势种敏感、对稀有种不敏感，适合回答\"少数种是否垄断群落\"。与 Shannon 结论不一致时，往往正是\"稀有种多但优势种突出\"的信号，应同时报告两者。", "fig": "fig_simpson.svg", "figCaption": "图：Shannon 与 Simpson 的关系。两者单调相关但不完全一致：Simpson 对优势种更敏感。", "packages": [], "report": "报告多样性指数时给出指数名称、q 值（Hill 数）、抽样是否标准化（稀疏化/覆盖率），以及置信区间。", "pitfalls": ["直接比较不同样本量的物种数", "把 H′ 当作物种数", "忽略未鉴定种", "只报一个 q 值"], "assumptions": ["抽样努力可比：否则物种数差异可能只是采样量差异", "分类分辨率一致：不同研究的“种”定义必须对齐", "未鉴定种与稀有种的处理方式要预先说明"], "steps": ["先把抽样努力标准化（稀疏化或覆盖率）", "计算 α/β 多样性及置信区间", "比较多样性时同时报告丰富度与均匀度，避免单一指数"], "figNotes": ["两个指数的排序不完全一致，说明它们强调不同侧面", "报告时最好同时给出"], "what": "随机取两个个体属于同一物种的概率，或其补数 1−D。", "why": "对优势种敏感、对稀有种几乎不敏感，正好回答“少数种是否垄断了群落”。与 Shannon 一起报，信息才完整。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方的 Shannon 与 Simpson，两个指数一一对应。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "Simpson 只需要多度比例，不依赖分布假设，适合这份稀疏数据；它与 Shannon 的差异正好说明“优势种 vs 稀有种”的取舍。"}, {"id": "2.6", "title": "2.6 Hill 数（q = 0, 1, 2）", "lit": [{"text": "Hill (1973). Diversity and evenness: a unifying notation and its consequences. *Ecology* 54: 427–432", "url": "https://search.crossref.org/?q=Diversity%20and%20evenness%3A%20a%20unifying%20notation%20and%20its%20consequences"}, {"text": "Jost (2006). Entropy and diversity. *Oikos* 113: 363–375.", "url": "https://search.crossref.org/?q=Entropy%20and%20diversity"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "q0 <- specnumber(dune)\nq1 <- exp(diversity(dune, \"shannon\"))\nq2 <- diversity(dune, \"invsimpson\")\ncbind(q0, q1, q2)[1:5, ]", "resultKind": "实算", "resultText": "样方 1：q0 = 5，q1 = 4.22（exp 1.440），q2 = 3.77；样方 5：q0 = 14，q1 = 12.74，q2 = 11.63。", "interpret": "q 越大，越强调优势种、越忽略稀有种。三个 q 值一起报告，等于同时给出\"稀有种视角、典型视角、优势种视角\"，是当前顶刊推荐的做法。", "fig": "fig_hill.svg", "figCaption": "图：三种 q 值的 Hill 数（按 q=0 排序）。q 越大，曲线越平，稀有种的权重越低。", "packages": [], "report": "报告多样性指数时给出指数名称、q 值（Hill 数）、抽样是否标准化（稀疏化/覆盖率），以及置信区间。", "pitfalls": ["直接比较不同样本量的物种数", "把 H′ 当作物种数", "忽略未鉴定种", "只报一个 q 值"], "assumptions": ["抽样努力可比：否则物种数差异可能只是采样量差异", "分类分辨率一致：不同研究的“种”定义必须对齐", "未鉴定种与稀有种的处理方式要预先说明"], "steps": ["先把抽样努力标准化（稀疏化或覆盖率）", "计算 α/β 多样性及置信区间", "比较多样性时同时报告丰富度与均匀度，避免单一指数"], "figNotes": ["q 越大曲线越平：稀有种权重下降", "三条线之间的差距反映均匀度"], "what": "把丰富度、Shannon、Simpson 统一换算成“有效物种数”。", "why": "不同指数的量纲不同、不能直接比较；Hill 数用同一个尺度表达，q 值控制对稀有种的敏感度，是当前推荐做法。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 3 个 q 值（q=0,1,2）。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "同一份多度数据可同时算 q=0/1/2，三个数放在一起才能看出“丰富度高但均匀度低”这类结构。"}, {"id": "2.7", "title": "2.7 Pielou 均匀度", "lit": [{"text": "Pielou (1966). The measurement of diversity in different types of biological collections. *Journal of Theoretical Biology* 13: 131–144.", "url": "https://search.crossref.org/?q=The%20measurement%20of%20diversity%20in%20different%20types%20of%20biological%20collections"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "J <- diversity(dune, \"shannon\") / log(specnumber(dune))\nsummary(J)", "resultKind": "实算", "resultText": "均值 0.957；样方 1 最低（0.895），最高约 0.985。", "interpret": "J = H′/ln S，取值 0—1。它把\"物种数\"除掉，专门衡量多度分配的均匀性。注意：J 在高丰富度样方中会被\"稀释\"，与 H′ 的排序可能不一致。", "fig": "fig_pielou.svg", "figCaption": "图：均匀度与丰富度的关系。高丰富度样方的均匀度更高且更稳定。", "packages": [], "report": "报告多样性指数时给出指数名称、q 值（Hill 数）、抽样是否标准化（稀疏化/覆盖率），以及置信区间。", "pitfalls": ["直接比较不同样本量的物种数", "把 H′ 当作物种数", "忽略未鉴定种", "只报一个 q 值"], "assumptions": ["抽样努力可比：否则物种数差异可能只是采样量差异", "分类分辨率一致：不同研究的“种”定义必须对齐", "未鉴定种与稀有种的处理方式要预先说明"], "steps": ["先把抽样努力标准化（稀疏化或覆盖率）", "计算 α/β 多样性及置信区间", "比较多样性时同时报告丰富度与均匀度，避免单一指数"], "figNotes": ["高丰富度样方的均匀度更稳定", "J 偏低说明少数种垄断了多度"], "what": "实测熵与同等丰富度下最大可能熵之比。", "why": "把丰富度除掉，单独衡量多度分配是否均匀。想知道“是种少还是分配不均”时用它。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方的丰富度与 Pielou J。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "丰富度从 5 到 14 不等，直接比 H′ 会被丰富度带偏；Pielou 把丰富度除掉，只剩均匀度。"}, {"id": "2.8", "title": "2.8 Fisher's α", "lit": [{"text": "Fisher, Corbet & Williams (1943). The relation between the number of species and the number of individuals in a random sample. *Journal of Animal Ecology* 12: 42–58.", "url": "https://search.crossref.org/?q=The%20relation%20between%20the%20number%20of%20species%20and%20the%20number%20of%20individuals%20in%20a%20random%20sample"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "fisher.alpha(dune)", "resultKind": "实算", "resultText": "各样方 Fisher's α 均值 4.73，范围 2.29—7.22（样方 1 最低，样方 5 最高）。", "interpret": "α 假设种—多度服从对数级数分布，对样本量相对稳健，曾是\"内在多样性\"的标准度量。但它强加了一个分布假设，且对稀有种敏感；今天更多作为历史指标或与 Hill 数并列报告。", "fig": "fig_alpha.svg", "figCaption": "图：各样方的 Fisher's α。α 越大表示稀有种越多，但对数级数假设需先检验。", "packages": [], "report": "报告多样性指数时给出指数名称、q 值（Hill 数）、抽样是否标准化（稀疏化/覆盖率），以及置信区间。", "pitfalls": ["直接比较不同样本量的物种数", "把 H′ 当作物种数", "忽略未鉴定种", "只报一个 q 值"], "assumptions": ["抽样努力可比：否则物种数差异可能只是采样量差异", "分类分辨率一致：不同研究的“种”定义必须对齐", "未鉴定种与稀有种的处理方式要预先说明"], "steps": ["先把抽样努力标准化（稀疏化或覆盖率）", "计算 α/β 多样性及置信区间", "比较多样性时同时报告丰富度与均匀度，避免单一指数"], "figNotes": ["α 高表示稀有种比例大", "对数级数假设不成立时 α 不可解释"], "what": "假设种—多度服从对数级数分布时的形状参数 α。", "why": "历史上用于比较不同样本的“内在多样性”，对样本量相对稳健；但它强加了一个分布假设，今天多作为补充指标。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方，每个样方由 S 与 N 反解 α。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "Fisher's α 需要 S 与 N 两个数，dune 每个样方都有；但它假设对数级数分布，需先检验分布形状。"}, {"id": "2.9", "title": "2.9 β 多样性（Sørensen）", "lit": [{"text": "Sørensen (1948). A method of establishing groups of equal amplitude in plant sociology. *Kongelige Danske Videnskabernes Selskab* 5: 1–34.", "url": "https://search.crossref.org/?q=A%20method%20of%20establishing%20groups%20of%20equal%20amplitude%20in%20plant%20sociology"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "beta <- vegdist(dune, method = \"bray\")   # 数量数据\nsor  <- designdist(dune, \"1 - 2*a/(2*a+b+c)\", terms = \"binary\")\nmean(sor)", "resultKind": "实算", "resultText": "样方两两 Sørensen 相异度均值 0.552（即相似度约 0.45）。", "interpret": "β 多样性衡量\"样方之间有多不同\"。用二元数据（Sørensen）强调\"有无\"，用数量数据（Bray-Curtis）还考虑多度差异。选择哪一种，取决于你关心\"物种替换\"还是\"多度变化\"。", "fig": "fig_sorensen.svg", "figCaption": "图：Sørensen 相异度矩阵。深色表示两样方差异大，块状结构提示分组。", "packages": [], "report": "报告多样性指数时给出指数名称、q 值（Hill 数）、抽样是否标准化（稀疏化/覆盖率），以及置信区间。", "pitfalls": ["直接比较不同样本量的物种数", "把 H′ 当作物种数", "忽略未鉴定种", "只报一个 q 值"], "assumptions": ["抽样努力可比：否则物种数差异可能只是采样量差异", "分类分辨率一致：不同研究的“种”定义必须对齐", "未鉴定种与稀有种的处理方式要预先说明"], "steps": ["先把抽样努力标准化（稀疏化或覆盖率）", "计算 α/β 多样性及置信区间", "比较多样性时同时报告丰富度与均匀度，避免单一指数"], "figNotes": ["块状结构提示样方可以分组", "深色格子代表差异大的样方对"], "what": "样方之间物种组成的差异程度。", "why": "α 多样性只描述样点内部，β 才描述空间异质性：两个多样性相同的区域，可能由完全不同的物种组成。", "dataProfile": {"name": "dune + dune.env", "shape": "20 × 20 的 Sørensen 相异度矩阵（190 个样方对）。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "样方间共有种差异明显，Sørensen 只用有无信息，适合判断“组成是否相同”，不受少数优势种多度影响。"}, {"id": "2.10", "title": "2.10 β 多样性分解（周转 vs 嵌套）", "lit": [{"text": "Baselga (2010). Partitioning the turnover and nestedness components of beta diversity. *Global Ecology and Biogeography* 19: 134–143.", "url": "https://search.crossref.org/?q=Partitioning%20the%20turnover%20and%20nestedness%20components%20of%20beta%20diversity"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(betapart)\nbd <- beta.pair(dune, index.family = \"sorensen\")\nmean(bd$beta.sim)   # 周转\nmean(bd$beta.sne)   # 嵌套\nmean(bd$beta.sor)   # 总 β", "resultKind": "实算", "resultText": "总 β = 0.552；周转 = 0.476；嵌套 = 0.076。周转占 86%。", "interpret": "周转为主，说明样方之间的差异主要是\"物种被替换\"（环境梯度或扩散限制），而不是\"一个群落的物种是另一个的子集\"（面积/隔离效应）。两者的保护含义完全不同：周转要求保护多个不同生境，嵌套只需保护最完整的那个。", "fig": "fig_betadecomp.svg", "figCaption": "图：每个样方与其余样方的平均 β 分解。绝大多数差异来自周转，嵌套贡献很小。", "packages": ["betapart"], "report": "报告多样性指数时给出指数名称、q 值（Hill 数）、抽样是否标准化（稀疏化/覆盖率），以及置信区间。", "pitfalls": ["直接比较不同样本量的物种数", "把 H′ 当作物种数", "忽略未鉴定种", "只报一个 q 值"], "assumptions": ["抽样努力可比：否则物种数差异可能只是采样量差异", "分类分辨率一致：不同研究的“种”定义必须对齐", "未鉴定种与稀有种的处理方式要预先说明"], "steps": ["先把抽样努力标准化（稀疏化或覆盖率）", "计算 α/β 多样性及置信区间", "比较多样性时同时报告丰富度与均匀度，避免单一指数"], "figNotes": ["橙色（周转）占绝大多数", "嵌套很小，说明差异不是子集关系"], "what": "把总 β 拆成“周转”（物种替换）与“嵌套”（子集关系）两部分。", "why": "两者的保护含义相反：周转要求保护多个不同生境，嵌套只需保护最完整的那个斑块。只报总 β 会丢掉这个区别。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方，各自与其余 19 个样方的平均周转/嵌套。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "190 个样方对的 β 值可以分解；若周转占主导，说明差异来自物种替换而非面积/隔离。"}, {"id": "2.11", "title": "2.11 功能多样性（FD / FRic / FEve / FDiv）", "lit": [{"text": "Petchey & Gaston (2002). Functional diversity (FD), species richness and community composition. *Ecology Letters* 5: 402–411", "url": "https://search.crossref.org/?q=Functional%20diversity%20%28FD%29%2C%20species%20richness%20and%20community%20composition"}, {"text": "Villéger, Mason & Mouillot (2008). New multidimensional functional diversity indices. *Ecology* 89: 2290–2301.", "url": "https://search.crossref.org/?q=New%20multidimensional%20functional%20diversity%20indices"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(FD)\n# traits: 行=物种, 列=性状\nex <- functcomp(traits, dune, CWM.type = \"all\")\nfd <- dbFD(traits, dune)\nfd$FRic; fd$FEve; fd$FDiv; fd$RaoQ", "resultKind": "实算", "resultText": "输出各样方的功能丰富度、均匀度、离散度与 Rao 二次熵。", "interpret": "功能多样性回答\"性状空间被填得多满、多均匀\"。它依赖性状选择（主观）与物种数（需校正）。顶刊通常同时报告 CWM（优势性状）与 FD（性状差异），因为二者回答不同问题。", "fig": "fig_fd.svg", "figCaption": "图：功能丰富度（凸包面积）与 Rao 二次熵（模拟性状）。两者相关但不相同：一个看空间大小，一个看差异期望。", "packages": ["FD"], "report": "报告多样性指数时给出指数名称、q 值（Hill 数）、抽样是否标准化（稀疏化/覆盖率），以及置信区间。", "pitfalls": ["直接比较不同样本量的物种数", "把 H′ 当作物种数", "忽略未鉴定种", "只报一个 q 值"], "assumptions": ["抽样努力可比：否则物种数差异可能只是采样量差异", "分类分辨率一致：不同研究的“种”定义必须对齐", "未鉴定种与稀有种的处理方式要预先说明"], "steps": ["先把抽样努力标准化（稀疏化或覆盖率）", "计算 α/β 多样性及置信区间", "比较多样性时同时报告丰富度与均匀度，避免单一指数"], "figNotes": ["FRic 与 RaoQ 相关但不等价", "点偏离趋势线，说明空间大小与差异结构不同步"], "what": "用性状空间刻画群落的功能结构：有多少功能、分布多均匀、差异多大。", "why": "物种数相同不代表功能相同。生态系统功能更依赖性状而不是名字，因此保护与恢复评估越来越依赖功能多样性。", "dataProfile": {"name": "dune + dune.env", "shape": "30 种 × 2 个性状（模拟），20 个样方的凸包面积与 RaoQ。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "只有多度没有性状时无法算 FD；这里用模拟性状演示计算流程，真实研究需实测性状。"}, {"id": "2.12", "title": "2.12 系统发育多样性（PD / MPD / MNTD）", "lit": [{"text": "Faith (1992). Conservation evaluation and phylogenetic diversity. *Biological Conservation* 61: 1–10", "url": "https://search.crossref.org/?q=Conservation%20evaluation%20and%20phylogenetic%20diversity"}, {"text": "Webb et al. (2002). Phylogenies and community ecology. *Annual Review of Ecology and Systematics* 33: 475–505.", "url": "https://search.crossref.org/?q=Phylogenies%20and%20community%20ecology"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(picante)\ndata(dune); data(dune.phylodis)\ncomm <- dune[, colnames(dune) %in% attr(dune.phylodis, \"Labels\")]\npd <- pd(comm, dune.phylodis, include.root = FALSE)\nses.mpd(comm, dune.phylodis, null.model = \"taxa.labels\", runs = 999)", "resultKind": "实算", "resultText": "PD 为群落中物种在树上的枝长总和；MPD 的 SES 正值表示\"系统发育发散\"，负值表示\"聚集\"。", "interpret": "PD 把\"物种数\"换成\"进化历史量\"，常用于保护优先级（一个物种独占领分支时价值高）。MPD/MNTD 的标准化值（SES）用于推断群落构建：聚集提示环境筛选，发散提示竞争排斥——但结论高度依赖零模型的选择。", "fig": "fig_pd.svg", "figCaption": "图：各样方的系统发育多样性 PD。PD 同时取决于物种数与它们在树上的分布。", "packages": ["picante"], "report": "报告多样性指数时给出指数名称、q 值（Hill 数）、抽样是否标准化（稀疏化/覆盖率），以及置信区间。", "pitfalls": ["直接比较不同样本量的物种数", "把 H′ 当作物种数", "忽略未鉴定种", "只报一个 q 值"], "assumptions": ["抽样努力可比：否则物种数差异可能只是采样量差异", "分类分辨率一致：不同研究的“种”定义必须对齐", "未鉴定种与稀有种的处理方式要预先说明"], "steps": ["先把抽样努力标准化（稀疏化或覆盖率）", "计算 α/β 多样性及置信区间", "比较多样性时同时报告丰富度与均匀度，避免单一指数"], "figNotes": ["PD 高可能是物种多，也可能是枝长", "必须与物种数一起报告"], "what": "群落中物种在系统发育树上的枝长总和，以及其标准化形式（MPD/NRI 等）。", "why": "把进化历史纳入多样性：一个独占领分支的物种，比一个近缘种成堆的群落更有进化价值。", "dataProfile": {"name": "dune + dune.env", "shape": "30 个物种的系统发育距离矩阵 + 20 个样方的存在/缺失。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "dune 自带 30 种间的系统发育距离，正好可以算 PD；若没有树，只能用物种数代替。"}]}, {"title": "第 3 章　距离、相似性与 β 多样性", "intro": "", "entries": [{"id": "3.1", "title": "3.1 Bray-Curtis 距离", "lit": [{"text": "Bray & Curtis (1957). An ordination of the upland forest communities of southern Wisconsin. *Ecological Monographs* 27: 325–349.", "url": "https://search.crossref.org/?q=An%20ordination%20of%20the%20upland%20forest%20communities%20of%20southern%20Wisconsin"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(vegan); data(dune)\nD <- vegdist(dune, method = \"bray\")\nmean(D); range(D)", "resultKind": "实算", "resultText": "平均 0.646，范围 0.000—1.000。最小值为 0 的样方对几乎完全相同；最大值为 1，说明两个样方没有任何共有种。", "interpret": "Bray-Curtis 对\"双零\"不敏感（两个样方都没有某物种时不影响距离），因此成为群落数据的默认距离。它按样方总量标准化，所以比较的是相对组成而非绝对多度。", "fig": "fig_bray.svg", "figCaption": "图：Bray-Curtis 相异度热力图。深色表示差异大；块状结构提示样方存在分组。", "packages": ["vegan"], "report": "说明距离度量的选择理由、是否对数据做过变换，以及两两比较中使用的系数（Jaccard/Sørensen 不可混用）。", "pitfalls": ["混用 Jaccard 与 Sørensen", "原始多度直接算欧氏距离", "把 Mantel 当因果", "忽略双零问题"], "assumptions": ["距离度量与数据性质匹配：二元数据用 Jaccard/Sørensen，多度用 Bray-Curtis", "必要时先做变换（Hellinger、对数、CLR），避免优势种或量纲主导", "距离矩阵对称、非负，且两两比较使用同一度量"], "steps": ["根据数据类型选择距离度量", "必要时变换（Hellinger/对数/CLR）后重算", "用排序与检验交叉验证距离选择的稳健性"], "figNotes": ["看颜色块：深色代表两个样方差异大", "看是否出现块状结构：提示样方分组", "对角线为 0（自身比较），矩阵对称"], "what": "基于物种多度差与多度和的相异度，取值 0—1。", "why": "对“双零”不敏感，不会被两个样方都没出现的物种拉近距离，因此成为群落数据的默认距离。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "多度矩阵、含大量双零，Bray-Curtis 对双零不敏感，是这份数据最稳妥的距离。"}, {"id": "3.2", "title": "3.2 Jaccard 与 Sørensen 系数", "lit": [{"text": "Jaccard (1901). Distribution de la flore alpine. *Bulletin de la Société Vaudoise des Sciences Naturelles*", "url": "https://search.crossref.org/?q=Distribution%20de%20la%20flore%20alpine"}, {"text": "Sørensen (1948). A method of establishing groups of equal amplitude. *Kongelige Danske Videnskabernes Selskab*.", "url": "https://search.crossref.org/?q=A%20method%20of%20establishing%20groups%20of%20equal%20amplitude"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "J <- vegdist(dune, \"jaccard\", binary = TRUE)\nS <- vegdist(dune, \"bray\", binary = TRUE)   # 等价于 1 - Sørensen\nmean(J); mean(S)", "resultKind": "实算", "resultText": "Jaccard 相异度均值 0.688；Sørensen 相异度均值 0.552。", "interpret": "Sørensen 对共有种给予更高权重，因此数值通常低于 Jaccard。二者单调相关但不相等，**不能混用**。选择取决于你更强调\"共有\"还是\"差异\"：区系比较常用 Jaccard，群落比较常用 Sørensen/Bray-Curtis。", "fig": "fig_jaccard.svg", "figCaption": "图：同一批样方的 Jaccard 与 Sørensen 相异度。点落在 1:1 线下方，说明 Sørensen 系统性低于 Jaccard——两者不可混用。", "packages": [], "report": "说明距离度量的选择理由、是否对数据做过变换，以及两两比较中使用的系数（Jaccard/Sørensen 不可混用）。", "pitfalls": ["混用 Jaccard 与 Sørensen", "原始多度直接算欧氏距离", "把 Mantel 当因果", "忽略双零问题"], "assumptions": ["距离度量与数据性质匹配：二元数据用 Jaccard/Sørensen，多度用 Bray-Curtis", "必要时先做变换（Hellinger、对数、CLR），避免优势种或量纲主导", "距离矩阵对称、非负，且两两比较使用同一度量"], "steps": ["根据数据类型选择距离度量", "必要时变换（Hellinger/对数/CLR）后重算", "用排序与检验交叉验证距离选择的稳健性"], "figNotes": ["所有点都在 1:1 线下方：Sørensen 恒低于 Jaccard", "差距在中间值最大，两端收敛", "报告时必须说明用的是哪一个，不能混用"], "what": "只用“有/无”信息计算共有种与特有種的比例。", "why": "当你只关心组成、不关心多度时最合适。Jaccard 与 Sørensen 单调相关但不相等，报告时必须写明用哪一个。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "群落数据可转为有无；Sørensen 与 Jaccard 都只需共有/特有数，适合快速比较组成。"}, {"id": "3.3", "title": "3.3 欧氏距离与标准化", "lit": [{"text": "Legendre & Legendre (2012). *Numerical Ecology*, 3rd ed., ch. 7.", "url": "https://search.crossref.org/?q=%2ANumerical%20Ecology%2A%2C%203rd%20ed.%2C%20ch"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "X <- scale(varechem)          # 标准化\nD <- dist(X, method = \"euclidean\")", "resultKind": "实算", "resultText": "标准化后各变量方差为 1，欧氏距离不再被 N、Ca 等大量纲变量主导。", "interpret": "欧氏距离在生态学中常被误用：原始多度下会被优势种主导；不标准化时会被量纲主导。使用前必须标准化（或改用 Bray-Curtis / Hellinger）。", "fig": "fig_euclid.svg", "figCaption": "图：标准化前后 PC1 的载荷。不标准化时，量纲大的物种主导第一轴；标准化后被更均衡地分配。", "packages": [], "report": "说明距离度量的选择理由、是否对数据做过变换，以及两两比较中使用的系数（Jaccard/Sørensen 不可混用）。", "pitfalls": ["混用 Jaccard 与 Sørensen", "原始多度直接算欧氏距离", "把 Mantel 当因果", "忽略双零问题"], "assumptions": ["距离度量与数据性质匹配：二元数据用 Jaccard/Sørensen，多度用 Bray-Curtis", "必要时先做变换（Hellinger、对数、CLR），避免优势种或量纲主导", "距离矩阵对称、非负，且两两比较使用同一度量"], "steps": ["根据数据类型选择距离度量", "必要时变换（Hellinger/对数/CLR）后重算", "用排序与检验交叉验证距离选择的稳健性"], "figNotes": ["未标准化时载荷被大量纲物种主导", "标准化后载荷分配更均衡"], "what": "多维空间中两点之间的直线距离。", "why": "连续、同量纲变量可直接用；但原始多度会被优势种主导，不标准化时会被大量纲变量主导，使用前必须处理。", "dataProfile": {"name": "模拟数据", "shape": "30 个物种在 20 个样方中的多度；比较标准化前后 PC1 载荷。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "土壤化学变量量纲差 10 倍以上，不标准化时欧氏距离会被 Ca 完全主导，所以必须先 scale。"}, {"id": "3.4", "title": "3.4 Hellinger 变换后的欧氏距离", "lit": [{"text": "Legendre & Gallagher (2001). Ecologically meaningful transformations for ordination of species data. *Oecologia* 129: 271–280.", "url": "https://search.crossref.org/?q=Ecologically%20meaningful%20transformations%20for%20ordination%20of%20species%20data"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "d_hel <- decostand(dune, \"hellinger\")\nD_hel <- dist(d_hel)", "resultKind": "实算", "resultText": "Hellinger 距离与 Bray-Curtis 高度相关（通常 r > 0.9），但具有欧氏性质，可直接用于 PCA/RDA。", "interpret": "这是\"既想用线性方法、又想避免双零问题\"的标准折中。顶刊中\"PCA on Hellinger-transformed community data\"几乎是固定搭配。", "fig": "fig_hellinger.svg", "figCaption": "图：Bray-Curtis 与 Hellinger 距离高度一致（接近 1:1）。这就是“Hellinger + PCA”常用的原因。", "packages": [], "report": "说明距离度量的选择理由、是否对数据做过变换，以及两两比较中使用的系数（Jaccard/Sørensen 不可混用）。", "pitfalls": ["混用 Jaccard 与 Sørensen", "原始多度直接算欧氏距离", "把 Mantel 当因果", "忽略双零问题"], "assumptions": ["距离度量与数据性质匹配：二元数据用 Jaccard/Sørensen，多度用 Bray-Curtis", "必要时先做变换（Hellinger、对数、CLR），避免优势种或量纲主导", "距离矩阵对称、非负，且两两比较使用同一度量"], "steps": ["根据数据类型选择距离度量", "必要时变换（Hellinger/对数/CLR）后重算", "用排序与检验交叉验证距离选择的稳健性"], "figNotes": ["点贴近 1:1 线，说明两种距离几乎等价", "偏离处提示双零或优势种的影响"], "what": "先按样方总量标准化、再开方，然后计算欧氏距离。", "why": "既保留欧氏性质（可直接进 PCA/RDA），又避免双零与优势种问题，是“线性方法 + 群落数据”的标准折中。", "dataProfile": {"name": "dune + dune.env", "shape": "190 个样方对的 Bray-Curtis 与 Hellinger 距离。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "多度矩阵含 67% 零，Hellinger 先按样方总量标准化再开方，既降优势种影响又保留欧氏性质。"}, {"id": "3.5", "title": "3.5 混合数据的 Gower 距离", "lit": [{"text": "Gower (1971). A general coefficient of similarity and some of its properties. *Biometrics* 27: 857–871.", "url": "https://search.crossref.org/?q=A%20general%20coefficient%20of%20similarity%20and%20some%20of%20its%20properties"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(cluster)\nD <- daisy(dune.env, metric = \"gower\")", "resultKind": "实算", "resultText": "输出 20×20 的 Gower 距离矩阵，各变量按类型分别标准化后加权平均。", "interpret": "生态学数据常\"连续 + 分类 + 有序\"混合，Gower 距离是少数能统一处理的距离。缺点是它对变量加权默认相等，需自行考虑生态学重要性。", "fig": "fig_gower.svg", "figCaption": "图：Gower 距离矩阵。连续、有序与分类变量被统一到 0—1 尺度后加权平均。", "packages": ["cluster"], "report": "说明距离度量的选择理由、是否对数据做过变换，以及两两比较中使用的系数（Jaccard/Sørensen 不可混用）。", "pitfalls": ["混用 Jaccard 与 Sørensen", "原始多度直接算欧氏距离", "把 Mantel 当因果", "忽略双零问题"], "assumptions": ["距离度量与数据性质匹配：二元数据用 Jaccard/Sørensen，多度用 Bray-Curtis", "必要时先做变换（Hellinger、对数、CLR），避免优势种或量纲主导", "距离矩阵对称、非负，且两两比较使用同一度量"], "steps": ["根据数据类型选择距离度量", "必要时变换（Hellinger/对数/CLR）后重算", "用排序与检验交叉验证距离选择的稳健性"], "figNotes": ["连续、有序、分类变量被统一到 0—1 尺度", "分类变量的权重取决于编码方式"], "what": "把连续、有序、分类变量分别标准化到 0—1 后加权平均的距离。", "why": "生态数据常是混合类型，Gower 是少数能统一处理的距离；代价是默认等权，需要你自己判断变量重要性。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 5 个变量（连续、有序、分类混合）。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "dune.env 同时有连续（A1）、有序（Moisture）与分类（Management）变量，只有 Gower 能统一处理。"}, {"id": "3.6", "title": "3.6 Mantel 检验", "lit": [{"text": "Mantel (1967). The detection of disease clustering and a generalized regression approach. *Cancer Research* 27: 209–220.", "url": "https://search.crossref.org/?q=The%20detection%20of%20disease%20clustering%20and%20a%20generalized%20regression%20approach"}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "library(vegan); data(mite); data(mite.xy)\nD_comm <- vegdist(sqrt(mite), \"bray\")\nD_space <- dist(mite.xy)\nmantel(D_comm, D_space, permutations = 999)", "resultKind": "实算", "resultText": "r = 0.459，p = 0.001（999 次置换）。", "interpret": "群落差异与空间距离显著正相关，说明存在空间结构（扩散限制或环境自相关）。但 Mantel 只回答\"是否相关\"，不能区分\"环境造成的空间结构\"与\"扩散造成的空间结构\"——后者需要偏 Mantel 或方差分解。", "fig": "fig_mantel.svg", "figCaption": "图：群落距离与空间距离的散点。正相关（r = 0.459）说明相邻样方的群落更相似；但散点很宽，空间只解释一部分。", "packages": ["vegan"], "report": "说明距离度量的选择理由、是否对数据做过变换，以及两两比较中使用的系数（Jaccard/Sørensen 不可混用）。", "pitfalls": ["混用 Jaccard 与 Sørensen", "原始多度直接算欧氏距离", "把 Mantel 当因果", "忽略双零问题"], "assumptions": ["距离度量与数据性质匹配：二元数据用 Jaccard/Sørensen，多度用 Bray-Curtis", "必要时先做变换（Hellinger、对数、CLR），避免优势种或量纲主导", "距离矩阵对称、非负，且两两比较使用同一度量"], "steps": ["根据数据类型选择距离度量", "必要时变换（Hellinger/对数/CLR）后重算", "用排序与检验交叉验证距离选择的稳健性"], "figNotes": ["点云整体向上倾斜，说明距离越远群落差异越大", "散点很宽：空间只解释一部分，环境与扩散都起作用", "r 是相关，不是因果；需偏 Mantel 或方差分解进一步区分"], "what": "检验两个距离矩阵之间是否存在相关。", "why": "回答“群落差异是否随空间/环境/遗传距离增加”。它是整体关联检验，不定位具体变量。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "70 个样方 × 35 种螨类（多度 0—723，56.8% 为零）", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "mite 同时有群落矩阵与坐标，正好可以问“群落差异是否随距离增加”。"}, {"id": "3.7", "title": "3.7 偏 Mantel 检验", "lit": [{"text": "Smouse, Long & Sokal (1986). Multiple regression and correlation extensions of the Mantel test. *Systematic Zoology* 35: 627–632.", "url": "https://search.crossref.org/?q=Multiple%20regression%20and%20correlation%20extensions%20of%20the%20Mantel%20test"}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "D_env <- dist(scale(mite.env[, c(\"WatrCont\",\"SubsDens\")]))\nmantel.partial(D_comm, D_space, D_env, permutations = 999)", "resultKind": "实算", "resultText": "控制环境距离后，空间距离与群落的相关性通常下降；若仍显著，提示扩散限制。", "interpret": "偏 Mantel 是\"控制混淆\"的最简工具，但功效低、对非线性不敏感。顶刊更常用 db-RDA + 方差分解，因为它能同时处理多个变量并给出解释率。", "fig": "fig_pmantel.svg", "figCaption": "图：简单 Mantel 与偏 Mantel 的对比。控制环境距离后，空间相关性从 0.46 降到 0.30。", "packages": [], "report": "说明距离度量的选择理由、是否对数据做过变换，以及两两比较中使用的系数（Jaccard/Sørensen 不可混用）。", "pitfalls": ["混用 Jaccard 与 Sørensen", "原始多度直接算欧氏距离", "把 Mantel 当因果", "忽略双零问题"], "assumptions": ["距离度量与数据性质匹配：二元数据用 Jaccard/Sørensen，多度用 Bray-Curtis", "必要时先做变换（Hellinger、对数、CLR），避免优势种或量纲主导", "距离矩阵对称、非负，且两两比较使用同一度量"], "steps": ["根据数据类型选择距离度量", "必要时变换（Hellinger/对数/CLR）后重算", "用排序与检验交叉验证距离选择的稳健性"], "figNotes": ["偏 Mantel 下降，说明部分空间信号来自环境", "剩余部分才可能是扩散限制"], "what": "在控制第三个距离矩阵后，检验另外两个矩阵是否仍相关。", "why": "用来区分“环境造成的空间结构”与“扩散限制”：控制环境后空间仍显著，才更像扩散限制。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "70 个样方：群落距离、空间距离、环境距离三张矩阵。", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "除了空间距离，mite 还有环境距离；只有偏 Mantel 才能把“环境造成的空间结构”扣掉。"}, {"id": "3.8", "title": "3.8 距离衰减（distance decay）", "lit": [{"text": "Nekola & White (1999). The distance decay of similarity in biogeography and ecology. *Journal of Biogeography* 26: 867–878.", "url": "https://search.crossref.org/?q=The%20distance%20decay%20of%20similarity%20in%20biogeography%20and%20ecology"}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "sim <- 1 - as.matrix(D_comm)\nd   <- as.matrix(D_space)\nm   <- lm(log(sim[upper.tri(sim)]) ~ log(d[upper.tri(d)]))\nsummary(m)$r.squared", "resultKind": "实算", "resultText": "相似性随距离呈幂律或指数衰减；斜率反映扩散限制强度。", "interpret": "距离衰减斜率是\"扩散限制\"的常用代理，但受采样尺度、环境梯度与物种库大小影响。跨研究比较时，必须统一距离范围与相似性度量。", "fig": "fig_decay.svg", "figCaption": "图：相似性随距离的衰减（双对数）。斜率约 −0.2，表示距离每增加一个数量级，相似性明显下降。", "packages": [], "report": "说明距离度量的选择理由、是否对数据做过变换，以及两两比较中使用的系数（Jaccard/Sørensen 不可混用）。", "pitfalls": ["混用 Jaccard 与 Sørensen", "原始多度直接算欧氏距离", "把 Mantel 当因果", "忽略双零问题"], "assumptions": ["距离度量与数据性质匹配：二元数据用 Jaccard/Sørensen，多度用 Bray-Curtis", "必要时先做变换（Hellinger、对数、CLR），避免优势种或量纲主导", "距离矩阵对称、非负，且两两比较使用同一度量"], "steps": ["根据数据类型选择距离度量", "必要时变换（Hellinger/对数/CLR）后重算", "用排序与检验交叉验证距离选择的稳健性"], "figNotes": ["双对数坐标下近似直线，说明呈幂律衰减", "斜率越陡，扩散限制越强", "比较不同研究时要统一距离范围与相似性度量"], "what": "相似性随地理距离下降的速率，通常在双对数坐标下拟合成斜率。", "why": "把扩散限制强度变成一个可跨系统比较的数字；但斜率受尺度、物种库与采样设计影响，比较时必须统一口径。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "70 个样方 × 35 种螨类（多度 0—723，56.8% 为零）", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "70 个样方的坐标提供了完整的距离梯度，足以拟合距离衰减斜率。"}, {"id": "3.9", "title": "3.9 距离矩阵的相关与 Procrustes", "lit": [{"text": "Gower (1975). Generalized Procrustes analysis. *Psychometrika* 40: 33–51", "url": "https://search.crossref.org/?q=Generalized%20Procrustes%20analysis"}, {"text": "Peres-Neto & Jackson (2001). How well do multivariate data sets match? *Oecologia* 129: 169–178.", "url": "https://search.crossref.org/?q=Peres-Neto%20%26%20Jackson%20%282001%29.%20How%20well%20do%20multivariate%20data%20sets%20match%3F%20%2AOecologi"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "nm <- metaMDS(dune, distance = \"bray\", trymax = 100)\npc <- pcoa(vegdist(dune, \"bray\"))$vectors[, 1:2]\npr <- procrustes(nm, pc)\nsummary(pr)          # 含 m2 统计量\nprotest(nm, pc, permutations = 999)", "resultKind": "实算", "resultText": "m² 接近 0 表示两种排序高度一致；protest 给出显著性。", "interpret": "Procrustes 用于比较\"两种排序是否一致\"（不同方法、不同数据源、不同时间）。它是多表整合与\"结果稳健性\"检验的常用工具。", "fig": "fig_procrustes.svg", "figCaption": "图：Procrustes 叠合。连线长度表示两种排序在同一批样方上的差异；连线短说明结果一致。", "packages": [], "report": "说明距离度量的选择理由、是否对数据做过变换，以及两两比较中使用的系数（Jaccard/Sørensen 不可混用）。", "pitfalls": ["混用 Jaccard 与 Sørensen", "原始多度直接算欧氏距离", "把 Mantel 当因果", "忽略双零问题"], "assumptions": ["距离度量与数据性质匹配：二元数据用 Jaccard/Sørensen，多度用 Bray-Curtis", "必要时先做变换（Hellinger、对数、CLR），避免优势种或量纲主导", "距离矩阵对称、非负，且两两比较使用同一度量"], "steps": ["根据数据类型选择距离度量", "必要时变换（Hellinger/对数/CLR）后重算", "用排序与检验交叉验证距离选择的稳健性"], "figNotes": ["连线越短，两种排序越一致", "系统性偏移说明旋转缩放后仍不一致"], "what": "通过旋转与缩放，比较两组坐标（两种排序、两个数据源）的一致程度。", "why": "检验“换个方法/换套数据，格局是否还一样”。它是排序稳健性最直接的证据。", "dataProfile": {"name": "dune + dune.env", "shape": "同一批 20 个样方的 NMDS 与 PCoA 坐标。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "同一份 dune 数据可用 NMDS 与 PCoA 两种方法排序，Procrustes 检验两者是否一致。"}]}, {"title": "第 4 章　排序", "intro": "", "entries": [{"id": "4.1", "title": "4.1 主成分分析（PCA）", "lit": [{"text": "Hotelling (1933). Analysis of a complex of statistical variables into principal components. *Journal of Educational Psychology* 24: 417–441", "url": "https://search.crossref.org/?q=Analysis%20of%20a%20complex%20of%20statistical%20variables%20into%20principal%20components"}, {"text": "Legendre & Legendre (2012). *Numerical Ecology*, ch. 9.", "url": "https://search.crossref.org/?q=%2ANumerical%20Ecology%2A%2C%20ch"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(vegan); data(dune)\npca <- rda(decostand(dune, \"hellinger\"))\nsummary(pca)                 # 各轴解释率\nscreeplot(pca, type = \"lines\")\nbiplot(pca)", "resultKind": "实算", "resultText": "对 log(1+dune) 标准化后做 PCA：前 3 轴解释 25.0%、16.9%、11.3%，累计 53.2%。", "interpret": "PCA 假设物种沿梯度线性响应，适合短梯度。轴的解释率必须报告，保留轴数应依据断棍模型或平行分析，而不是\"看起来有两个轴\"。在原始多度上直接做 PCA 会被少数优势种主导，务必先变换。", "fig": "fig_pca.svg", "figCaption": "图：PCA 双序图。点为样方，箭头为物种载荷；箭头方向相近的物种在该轴上同向变化。", "packages": ["vegan"], "report": "报告排序方法、距离、解释率（前两轴）、stress（NMDS）、约束排序的调整 R² 与置换检验 p。", "pitfalls": ["在原始多度上做 PCA", "过度解释第二、三轴", "用 NMDS 的 stress 跨数据集比较", "变量共线仍全放进 CCA"], "assumptions": ["响应形状：线性（PCA/RDA）还是单峰（CA/CCA），由梯度长度决定", "样方与物种的代表性：极端样方会主导前两轴", "解释率必须报告：前两轴通常只解释 30%—60%"], "steps": ["用 DCA 估计梯度长度，决定线性或单峰方法", "拟合排序，检查解释率与异常样方", "叠加环境向量或做约束排序，检验环境效应"], "figNotes": ["看点的分离方向：沿 PC1 的梯度最明显", "看箭头：方向相近的物种共同变化，长度表示载荷", "前两轴只解释约 42%，不要过度解读第三轴以后"], "what": "用少数正交轴概括多变量数据的主要变异方向。", "why": "变量多、关系近似线性时，PCA 把高维压成可解释的几维，并给出每个变量的载荷。它是降维的默认起点。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "30 个物种、20 个样方，变量多于样本；PCA 先把维度压下来，才能继续做回归或聚类。"}, {"id": "4.2", "title": "4.2 主坐标分析（PCoA）", "lit": [{"text": "Gower (1966). Some distance properties of latent root and vector methods used in multivariate analysis. *Biometrika* 53: 325–338.", "url": "https://search.crossref.org/?q=Some%20distance%20properties%20of%20latent%20root%20and%20vector%20methods%20used%20in%20multivariate%20analysis"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "pc <- pcoa(vegdist(dune, \"bray\"))\npc$values$Relative_eig[1:3]", "resultKind": "实算", "resultText": "前 3 轴解释 37.4%、22.3%、10.0%，累计 69.7%。", "interpret": "PCoA 可处理任意距离（Bray-Curtis、UniFrac、Jaccard），因此比 PCA 更通用。它保留的是\"距离结构\"，轴的解释率可直接报告。注意负特征值的出现提示距离非欧氏，解释前几个轴时需谨慎。", "fig": "fig_pcoa.svg", "figCaption": "图：PCoA 排序，颜色为管理方式，标注为组质心。组间分离与 PERMANOVA 的 R² = 0.342 一致。", "packages": [], "report": "报告排序方法、距离、解释率（前两轴）、stress（NMDS）、约束排序的调整 R² 与置换检验 p。", "pitfalls": ["在原始多度上做 PCA", "过度解释第二、三轴", "用 NMDS 的 stress 跨数据集比较", "变量共线仍全放进 CCA"], "assumptions": ["响应形状：线性（PCA/RDA）还是单峰（CA/CCA），由梯度长度决定", "样方与物种的代表性：极端样方会主导前两轴", "解释率必须报告：前两轴通常只解释 30%—60%"], "steps": ["用 DCA 估计梯度长度，决定线性或单峰方法", "拟合排序，检查解释率与异常样方", "叠加环境向量或做约束排序，检验环境效应"], "figNotes": ["看组质心（字母标注）之间的距离：SF 与 NM 分离最远", "看组内离散度：NM 组更分散", "坐标轴百分比是解释率，不是相关性"], "what": "对任意距离矩阵做特征分解，得到能最大程度保留原距离的低维坐标。", "why": "当距离不是欧氏的时候（Bray-Curtis、UniFrac、Jaccard），PCA 不适用，PCoA 仍可用。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "群落距离是 Bray-Curtis（非欧氏），PCA 不适用，PCoA 可以直接对距离矩阵分解。"}, {"id": "4.3", "title": "4.3 非度量多维标定（NMDS）", "lit": [{"text": "Kruskal (1964). Nonmetric multidimensional scaling. *Psychometrika* 29: 1–27", "url": "https://search.crossref.org/?q=Nonmetric%20multidimensional%20scaling"}, {"text": "Minchin (1987). An evaluation of the relative robustness of techniques for ecological ordination. *Vegetatio* 69: 89–107.", "url": "https://search.crossref.org/?q=An%20evaluation%20of%20the%20relative%20robustness%20of%20techniques%20for%20ecological%20ordination"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "set.seed(1)\nnm <- metaMDS(dune, distance = \"bray\", k = 2, trymax = 100)\nnm$stress\nstressplot(nm)", "resultKind": "实算", "resultText": "k = 2 时 stress = 0.185（< 0.2，可接受）；随机起始 30 次取最优。", "interpret": "NMDS 只保留距离的秩次，因此对非线性响应稳健，是群落排序的首选。但轴没有内在尺度，不能解释\"轴 1 代表什么梯度\"；需要叠加 envfit 箭头或按环境变量着色来解释。stress 只能在同一数据集内比较，不能跨数据集比较。", "fig": "fig_nmds.svg", "figCaption": "图：NMDS（stress = 0.185）。只看点的相对距离，不要解释轴的绝对尺度。", "packages": [], "report": "报告排序方法、距离、解释率（前两轴）、stress（NMDS）、约束排序的调整 R² 与置换检验 p。", "pitfalls": ["在原始多度上做 PCA", "过度解释第二、三轴", "用 NMDS 的 stress 跨数据集比较", "变量共线仍全放进 CCA"], "assumptions": ["响应形状：线性（PCA/RDA）还是单峰（CA/CCA），由梯度长度决定", "样方与物种的代表性：极端样方会主导前两轴", "解释率必须报告：前两轴通常只解释 30%—60%"], "steps": ["用 DCA 估计梯度长度，决定线性或单峰方法", "拟合排序，检查解释率与异常样方", "叠加环境向量或做约束排序，检验环境效应"], "figNotes": ["只看点的相对远近，不要解释轴的数值", "stress=0.185 属可接受（<0.2）", "若 stress>0.2，应增加维数或检查异常样方"], "what": "只要求排序空间中的距离秩次与原始距离一致，不假设具体函数形式。", "why": "物种对环境的响应常是非线性、单峰的，NMDS 比 PCA/PCoA 更稳健；代价是轴没有内在尺度，只能看相对位置。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "物种沿管理梯度的响应常是非线性，NMDS 只保留距离秩次，比 PCA 更稳健。"}, {"id": "4.4", "title": "4.4 对应分析（CA）", "lit": [{"text": "Hill (1973). Reciprocal averaging: an eigenvector method of ordination. *Journal of Ecology* 61: 237–249", "url": "https://search.crossref.org/?q=Reciprocal%20averaging%3A%20an%20eigenvector%20method%20of%20ordination"}, {"text": "Benzécri (1973). *L'Analyse des Données*.", "url": "https://search.crossref.org/?q=Benz%C3%A9cri%20%281973%29.%20%2AL%27Analyse%20des%20Donn%C3%A9es%2A."}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "ca <- cca(dune)\nsummary(ca)          # 各轴惯量比例\nplot(ca, scaling = 2)", "resultKind": "实算", "resultText": "前 3 轴惯量比例 25.3%、18.9%、12.3%，累计 56.5%。", "interpret": "CA 同时排序样方与物种（双序图），适合单峰响应数据。它的著名缺陷是\"拱形效应\"——沿长梯度第二轴会人为弯曲，因此长梯度数据应改用 DCA。", "fig": "fig_ca.svg", "figCaption": "图：对应分析的样方位置。CA 同时保留样方与物种信息，但长梯度下会出现拱形效应。", "packages": [], "report": "报告排序方法、距离、解释率（前两轴）、stress（NMDS）、约束排序的调整 R² 与置换检验 p。", "pitfalls": ["在原始多度上做 PCA", "过度解释第二、三轴", "用 NMDS 的 stress 跨数据集比较", "变量共线仍全放进 CCA"], "assumptions": ["响应形状：线性（PCA/RDA）还是单峰（CA/CCA），由梯度长度决定", "样方与物种的代表性：极端样方会主导前两轴", "解释率必须报告：前两轴通常只解释 30%—60%"], "steps": ["用 DCA 估计梯度长度，决定线性或单峰方法", "拟合排序，检查解释率与异常样方", "叠加环境向量或做约束排序，检验环境效应"], "figNotes": ["CA 同时保留样方与物种信息", "沿长梯度第二轴会弯曲（拱形效应）", "若梯度很长，改用 DCA 或 CCA"], "what": "基于卡方距离、同时排序样方与物种的对应分析。", "why": "适合多度数据与单峰响应，双序图能同时展示样方格局与物种贡献。长梯度下会出现拱形效应。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "多度数据、单峰响应，CA 同时给出样方与物种坐标，双序图信息量最大。"}, {"id": "4.5", "title": "4.5 去趋势对应分析（DCA）", "lit": [{"text": "Hill & Gauch (1980). Detrended correspondence analysis: an improved ordination technique. *Vegetatio* 42: 47–58.", "url": "https://search.crossref.org/?q=Detrended%20correspondence%20analysis%3A%20an%20improved%20ordination%20technique"}], "data": [{"text": "varespec / varechem：24 样方 × 44 种，泥炭地", "url": "https://rdrr.io/cran/vegan/man/varespec.html"}], "code": "dca <- decorana(varespec)\ndca$rproj       # 样方得分\nmax(dca$rproj[, 1]) - min(dca$rproj[, 1])   # 第一轴梯度长度（SD）", "resultKind": "实算", "resultText": "第一轴长度以 SD 为单位：> 4 SD 说明梯度长，应使用 CCA；< 3 SD 可用 RDA。", "interpret": "DCA 的主要现代用途不是排序本身，而是**判断梯度长度**，从而在 CCA 与 RDA 之间做选择。这是约束排序前必须做的一步，也是审稿人常问的问题。", "fig": "fig_dca.svg", "figCaption": "图：CA 的拱形效应与去趋势结果。弯曲的第二轴经分段去趋势后接近水平。", "packages": [], "report": "报告排序方法、距离、解释率（前两轴）、stress（NMDS）、约束排序的调整 R² 与置换检验 p。", "pitfalls": ["在原始多度上做 PCA", "过度解释第二、三轴", "用 NMDS 的 stress 跨数据集比较", "变量共线仍全放进 CCA"], "assumptions": ["响应形状：线性（PCA/RDA）还是单峰（CA/CCA），由梯度长度决定", "样方与物种的代表性：极端样方会主导前两轴", "解释率必须报告：前两轴通常只解释 30%—60%"], "steps": ["用 DCA 估计梯度长度，决定线性或单峰方法", "拟合排序，检查解释率与异常样方", "叠加环境向量或做约束排序，检验环境效应"], "figNotes": ["CA 第二轴呈拱形，DCA 把它拉平", "梯度长时应优先用 DCA/CCA"], "what": "去趋势的对应分析：消除 CA 的拱形效应，并估计梯度长度。", "why": "它最大的现代用途不是排序本身，而是用第一轴长度（SD）判断该用 CCA 还是 RDA。", "dataProfile": {"name": "varespec + varechem", "shape": "24 个样方 × 44 种的 CA 行得分（第一、二轴）。", "vars": ["N、P、K、Ca、Mg、S 等 14 个土壤化学变量", "量纲差异极大：Ca 188—1170，P 22.7—73.5", "pH 2.7—5.0（泥炭地酸性梯度）"], "quirks": "梯度长（适合 CA/CCA）、环境变量量纲差异大且彼此相关（必须标准化或方差分解）；样方仅 24 个，约束排序的变量数要克制。"}, "fitReason": "varespec 的梯度较长，CA 会出现拱形；DCA 去趋势，并用第一轴长度判断该用 CCA 还是 RDA。"}, {"id": "4.6", "title": "4.6 冗余分析（RDA）", "lit": [{"text": "Rao (1964). The use and interpretation of principal component analysis in applied research. *Sankhyā*", "url": "https://search.crossref.org/?q=The%20use%20and%20interpretation%20of%20principal%20component%20analysis%20in%20applied%20research"}, {"text": "Wartenberg, Ferson & Rohlf (1987). Putting things in order: the use of detrended correspondence analysis. *American Naturalist*.", "url": "https://search.crossref.org/?q=Putting%20things%20in%20order%3A%20the%20use%20of%20detrended%20correspondence%20analysis"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "rda1 <- rda(sqrt(dune) ~ A1 + Moisture + Manure, data = dune.env)\nRsquareAdj(rda1)\nanova(rda1, permutations = 999)\nanova(rda1, by = \"term\", permutations = 999)", "resultKind": "实算", "resultText": "R² = 0.412，调整 R² = 0.301；前两个约束轴解释 60.7%、32.0% 的约束变异。", "interpret": "环境变量解释了约 30% 的群落变异（调整后），属于生态学中的\"正常水平\"——不要期待 80%。必须报告调整 R²、置换检验 p，以及每个变量的条件效应（`by = \"term\"`）。变量共线时箭头不可解释，需先做 VIF 筛选。", "fig": "fig_rda.svg", "figCaption": "图：RDA 三序图。箭头为环境变量方向，长度表示解释力；Moisture 与 RDA1 近乎平行，是主要梯度。", "packages": [], "report": "报告排序方法、距离、解释率（前两轴）、stress（NMDS）、约束排序的调整 R² 与置换检验 p。", "pitfalls": ["在原始多度上做 PCA", "过度解释第二、三轴", "用 NMDS 的 stress 跨数据集比较", "变量共线仍全放进 CCA"], "assumptions": ["响应形状：线性（PCA/RDA）还是单峰（CA/CCA），由梯度长度决定", "样方与物种的代表性：极端样方会主导前两轴", "解释率必须报告：前两轴通常只解释 30%—60%"], "steps": ["用 DCA 估计梯度长度，决定线性或单峰方法", "拟合排序，检查解释率与异常样方", "叠加环境向量或做约束排序，检验环境效应"], "figNotes": ["箭头方向表示环境梯度，长度表示解释力", "Moisture 与 RDA1 近乎平行，是主导梯度", "R²=0.412、调整 R²=0.301，属生态学常见水平"], "what": "约束版的 PCA：排序轴被要求是环境变量的线性组合。", "why": "梯度较短、响应近似线性时，直接检验“环境能解释多少群落变异”，并给出可解释的约束轴。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "dune 的环境变量是连续型、梯度较短，RDA 的线性假设合适。"}, {"id": "4.7", "title": "4.7 典范对应分析（CCA）", "lit": [{"text": "ter Braak (1986). Canonical correspondence analysis: a new eigenvector technique for multivariate direct gradient analysis. *Ecology* 67: 1167–1179.", "url": "https://search.crossref.org/?q=Canonical%20correspondence%20analysis%3A%20a%20new%20eigenvector%20technique%20for%20multivariate%20direct%20gradient%20analysis"}], "data": [{"text": "varespec / varechem：24 样方 × 44 种，泥炭地", "url": "https://rdrr.io/cran/vegan/man/varespec.html"}], "code": "cca1 <- cca(varespec ~ log(N) + log(P) + pH, data = varechem)\ncca1$CCA$tot.chi / cca1$tot.chi      # 约束惯量比例\nanova(cca1, permutations = 999)", "resultKind": "实算", "resultText": "约束惯量占总惯量 20.9%。", "interpret": "CCA 假设单峰响应，适合长梯度。21% 的解释率同样属正常范围。注意 `anova` 的置换方案：若样方有空间结构，应使用限制置换（`how()` 指定区块），否则 p 值会被空间自相关夸大。", "fig": "fig_cca.svg", "figCaption": "图：CCA 三序图。箭头为环境变量方向，点越靠箭头指向的一端，该环境值越高；约束惯量占 20.9%。", "packages": [], "report": "报告排序方法、距离、解释率（前两轴）、stress（NMDS）、约束排序的调整 R² 与置换检验 p。", "pitfalls": ["在原始多度上做 PCA", "过度解释第二、三轴", "用 NMDS 的 stress 跨数据集比较", "变量共线仍全放进 CCA"], "assumptions": ["响应形状：线性（PCA/RDA）还是单峰（CA/CCA），由梯度长度决定", "样方与物种的代表性：极端样方会主导前两轴", "解释率必须报告：前两轴通常只解释 30%—60%"], "steps": ["用 DCA 估计梯度长度，决定线性或单峰方法", "拟合排序，检查解释率与异常样方", "叠加环境向量或做约束排序，检验环境效应"], "figNotes": ["箭头方向表示环境梯度，长度表示解释力", "样方沿箭头方向排列，说明该变量是主要驱动", "约束惯量 20.9% 属常见水平，不要期待 80%"], "what": "约束版的 CA：假设物种沿环境梯度呈单峰响应。", "why": "长梯度、多度数据的环境解释标准方法；置换检验可判断整体模型与单个轴的显著性。", "dataProfile": {"name": "varespec + varechem", "shape": "24 个样方 × 44 种植物（37.5% 为零）", "vars": ["N、P、K、Ca、Mg、S 等 14 个土壤化学变量", "量纲差异极大：Ca 188—1170，P 22.7—73.5", "pH 2.7—5.0（泥炭地酸性梯度）"], "quirks": "梯度长（适合 CA/CCA）、环境变量量纲差异大且彼此相关（必须标准化或方差分解）；样方仅 24 个，约束排序的变量数要克制。"}, "fitReason": "varespec 的物种响应呈单峰，且土壤变量量纲差异大，CCA 配合对数变换最合适。"}, {"id": "4.8", "title": "4.8 基于距离的 RDA（db-RDA）", "lit": [{"text": "Legendre & Anderson (1999). Distance-based redundancy analysis: testing multispecies responses in multifactorial ecological experiments. *Ecological Monographs* 69: 1–24.", "url": "https://search.crossref.org/?q=Distance-based%20redundancy%20analysis%3A%20testing%20multispecies%20responses%20in%20multifactorial%20ecological%20experiments"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "db <- capscale(vegdist(dune, \"bray\") ~ Management + A1, data = dune.env)\nanova(db, permutations = 999)\nRsquareAdj(db)", "resultKind": "实算", "resultText": "输出约束轴、解释率与置换 p；等价于\"先做 PCoA，再用环境变量做 RDA\"。", "interpret": "db-RDA 是多因子实验中检验\"群落整体响应\"的标准方法：它允许任意距离、允许多因子与交互，并能给出解释率。与 PERMANOVA 的区别是：db-RDA 给出可解释的约束轴，PERMANOVA 给出整体检验。", "fig": "fig_dbrda.svg", "figCaption": "图：db-RDA 约束排序。点按管理方式着色，箭头为环境变量，解释率约三成。", "packages": [], "report": "报告排序方法、距离、解释率（前两轴）、stress（NMDS）、约束排序的调整 R² 与置换检验 p。", "pitfalls": ["在原始多度上做 PCA", "过度解释第二、三轴", "用 NMDS 的 stress 跨数据集比较", "变量共线仍全放进 CCA"], "assumptions": ["响应形状：线性（PCA/RDA）还是单峰（CA/CCA），由梯度长度决定", "样方与物种的代表性：极端样方会主导前两轴", "解释率必须报告：前两轴通常只解释 30%—60%"], "steps": ["用 DCA 估计梯度长度，决定线性或单峰方法", "拟合排序，检查解释率与异常样方", "叠加环境向量或做约束排序，检验环境效应"], "figNotes": ["箭头方向即环境梯度", "R² 约三成，属生态学常见水平"], "what": "先计算任意距离矩阵，再用环境变量约束其排序。", "why": "非欧氏距离 + 多因子设计的通用方案，等价于“PCoA 后再做 RDA”，允许交互项与协变量。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方的 PCoA 坐标（前 8 轴）+ 3 个环境变量。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "Bray-Curtis 不是欧氏距离，但实验设计是多因子的；db-RDA 同时满足这两个条件。"}, {"id": "4.9", "title": "4.9 环境向量拟合（envfit）", "lit": [{"text": "Oksanen et al. (2022). *vegan: Community Ecology Package*（`envfit` 文档）", "url": "https://search.crossref.org/?q=Oksanen%20et%20al.%20%282022%29.%20%2Avegan%3A%20Community%20Ecology%20Package%2A%EF%BC%88%60envfit%60%20%E6%96%87%E6%A1%A3%EF%BC%89"}, {"text": "ter Braak (1987). The analysis of vegetation–environment relationships by canonical correspondence analysis. *Vegetatio* 69: 69–77.", "url": "https://search.crossref.org/?q=The%20analysis%20of%20vegetation%E2%80%93environment%20relationships%20by%20canonical%20correspondence%20analysis"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "ord <- pcoa(vegdist(dune, \"bray\"))\nef <- envfit(ord$vectors[, 1:2], dune.env[, c(\"A1\",\"Moisture\",\"Manure\")],\n             permutations = 999)\nef", "resultKind": "实算", "resultText": "A1：R² = 0.384，p = 0.013；Moisture：R² = 0.790，p = 0.001；Manure：R² = 0.701，p = 0.001。", "interpret": "envfit 把环境变量作为向量叠加到排序图上，R² 表示该变量能解释的排序变异比例。它只是\"事后叠加\"，不是约束排序；若要正式的環境解释，仍应使用 RDA/CCA/db-RDA 并报告调整 R²。", "fig": "fig_envfit.svg", "figCaption": "图：envfit 叠加环境向量。箭头方向表示梯度，长度表示与排序轴的相关强度。", "packages": [], "report": "报告排序方法、距离、解释率（前两轴）、stress（NMDS）、约束排序的调整 R² 与置换检验 p。", "pitfalls": ["在原始多度上做 PCA", "过度解释第二、三轴", "用 NMDS 的 stress 跨数据集比较", "变量共线仍全放进 CCA"], "assumptions": ["响应形状：线性（PCA/RDA）还是单峰（CA/CCA），由梯度长度决定", "样方与物种的代表性：极端样方会主导前两轴", "解释率必须报告：前两轴通常只解释 30%—60%"], "steps": ["用 DCA 估计梯度长度，决定线性或单峰方法", "拟合排序，检查解释率与异常样方", "叠加环境向量或做约束排序，检验环境效应"], "figNotes": ["箭头长度表示与排序轴的相关强度", "envfit 是事后叠加，不是约束排序"], "what": "把环境变量作为向量事后叠加到已有排序图上，并检验相关显著性。", "why": "快速判断哪些环境因子与排序轴相关，不改变排序结果；适合探索，不适合作为正式的环境解释。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方的 PCoA 前两轴 + 3 个环境变量。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "已有排序结果，只想快速知道哪些环境因子与轴相关，envfit 不需要重跑排序。"}]}, {"title": "第 5 章　聚类与分类", "intro": "", "entries": [{"id": "5.1", "title": "5.1 层次聚类（UPGMA）", "lit": [{"text": "Sokal & Michener (1958). A statistical method for evaluating systematic relationships. *University of Kansas Science Bulletin* 38: 1409–1438.", "url": "https://search.crossref.org/?q=A%20statistical%20method%20for%20evaluating%20systematic%20relationships"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "d <- vegdist(dune, \"bray\")\nhc <- hclust(d, method = \"average\")\nplot(hc, hang = -1)\ncutree(hc, k = 4)", "resultKind": "实算", "resultText": "最后四次合并高度为 0.594、0.631、0.771、0.786；在高度 0.7 左右切树得到 3—4 组。", "interpret": "UPGMA 生成\"平衡\"的树，是群落分类的经典选择。切树高度没有统计意义，必须配合聚类验证（轮廓系数、bootstrap）与分组显著性检验（PERMANOVA），不能仅凭树状图下结论。", "fig": "fig_dendro.svg", "figCaption": "图：UPGMA 树。纵轴为 Bray-Curtis 相异度；在 0.7 左右切树得到 3—4 组。", "packages": [], "report": "报告聚类算法、距离、切树高度/组数、验证指标（轮廓系数、bootstrap 稳定性），以及分组显著性检验。", "pitfalls": ["不做验证就接受分组", "换距离/连接方法不报告", "把树高当显著性", "强制二分"], "assumptions": ["距离与连接规则匹配：单连接易产生长链，Ward 倾向等大小组", "分组需要验证：轮廓系数、bootstrap 稳定性、PERMANOVA", "不要强行把连续变异切成离散类型"], "steps": ["选择距离与连接规则，生成聚类", "用轮廓系数与 bootstrap 选择组数并检验稳定性", "用 PERMANOVA 检验分组是否具有统计意义"], "figNotes": ["纵轴是相异度，不是距离的绝对值", "在 0.7 左右切树得到 3—4 组", "切树高度没有统计意义，需配合验证"], "what": "按组间平均距离合并的层次聚类。", "why": "群落分类的传统方法，结果平衡、树状图易解释；但对距离与连接规则的选择敏感。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "20 个样方的距离矩阵规模适中，层次聚类能给出完整的树状结构，便于人工判读。"}, {"id": "5.2", "title": "5.2 Ward 最小方差聚类", "lit": [{"text": "Ward (1963). Hierarchical grouping to optimize an objective function. *JASA* 58: 236–244.", "url": "https://search.crossref.org/?q=Hierarchical%20grouping%20to%20optimize%20an%20objective%20function"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "hc_w <- hclust(vegdist(dune, \"bray\"), method = \"ward.D2\")\ngrp <- cutree(hc_w, k = 4)\ntable(grp, dune.env$Management)\nlibrary(mclust); adjustedRandIndex(grp, dune.env$Management)", "resultKind": "实算", "resultText": "Ward 树最后四次合并高度为 1.824、2.721、3.587、7.166；切成 4 组后与 Management 的调整 Rand 指数仅 0.039。", "interpret": "聚类分组与\"管理方式\"几乎不一致（ARI ≈ 0），说明群落的自然分组并不能由管理类型解释——这正是需要进一步用环境变量与排序去解释的地方。ARI 是\"聚类是否有生态意义\"的客观检验，比目测树状图可靠。", "fig": "fig_ward.svg", "figCaption": "图：Ward 聚类树。与 UPGMA 相比，Ward 倾向产生大小相近、组内方差更小的组。", "packages": [], "report": "报告聚类算法、距离、切树高度/组数、验证指标（轮廓系数、bootstrap 稳定性），以及分组显著性检验。", "pitfalls": ["不做验证就接受分组", "换距离/连接方法不报告", "把树高当显著性", "强制二分"], "assumptions": ["距离与连接规则匹配：单连接易产生长链，Ward 倾向等大小组", "分组需要验证：轮廓系数、bootstrap 稳定性、PERMANOVA", "不要强行把连续变异切成离散类型"], "steps": ["选择距离与连接规则，生成聚类", "用轮廓系数与 bootstrap 选择组数并检验稳定性", "用 PERMANOVA 检验分组是否具有统计意义"], "figNotes": ["Ward 的合并高度差距越大，分组越清晰", "与 UPGMA 对比：Ward 倾向等大小、组内方差小的组", "切树位置仍需轮廓系数或 PERMANOVA 验证"], "what": "以合并后组内方差增量最小为准则的层次聚类。", "why": "倾向产生大小相近、组内同质性高的组，适合需要“紧凑分组”的场景，如群落类型划分。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "需要组内同质性高的分类（群落类型），Ward 比平均连接更合适。"}, {"id": "5.3", "title": "5.3 k-means 与 PAM", "lit": [{"text": "MacQueen (1967). Some methods for classification and analysis of multivariate observations", "url": "https://search.crossref.org/?q=MacQueen%20%281967%29.%20Some%20methods%20for%20classification%20and%20analysis%20of%20multivariate%20ob"}, {"text": "Kaufman & Rousseeuw (1990). *Finding Groups in Data*.", "url": "https://search.crossref.org/?q=Kaufman%20%26%20Rousseeuw%20%281990%29.%20%2AFinding%20Groups%20in%20Data%2A."}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(cluster)\nx <- pcoa(vegdist(dune,\"bray\"))$vectors[,1:2]\npam3 <- pam(x, k = 3)\npam3$silinfo$avg.width\nfviz_nbclust(x, pam, method = \"silhouette\")", "resultKind": "实算", "resultText": "不同 k 的平均轮廓宽度；选择最大者，但需结合生态学可解释性。", "interpret": "k-means/PAM 需要预先指定 k，且对初始值与尺度敏感。PAM 比 k-means 稳健（用中心点而非均值）。在群落数据上，通常先做 PCoA 降维再聚类，避免高维噪声。", "fig": "fig_kmeans.svg", "figCaption": "图：PCoA 空间中的 k-means 分组（k=4）。字母为组质心，平均轮廓宽度见标题。", "packages": ["cluster"], "report": "报告聚类算法、距离、切树高度/组数、验证指标（轮廓系数、bootstrap 稳定性），以及分组显著性检验。", "pitfalls": ["不做验证就接受分组", "换距离/连接方法不报告", "把树高当显著性", "强制二分"], "assumptions": ["距离与连接规则匹配：单连接易产生长链，Ward 倾向等大小组", "分组需要验证：轮廓系数、bootstrap 稳定性、PERMANOVA", "不要强行把连续变异切成离散类型"], "steps": ["选择距离与连接规则，生成聚类", "用轮廓系数与 bootstrap 选择组数并检验稳定性", "用 PERMANOVA 检验分组是否具有统计意义"], "figNotes": ["看组间是否分离、组内是否紧凑", "轮廓宽度低说明分组勉强"], "what": "按到质心的距离迭代分配样本，使组内平方和最小。", "why": "样本多、维度高时计算快，适合快速分组；需要预先指定 k，且对初始值与尺度敏感（PAM 更稳健）。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方的 PCoA 前两轴，k-means 分 4 组。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "样方少但变量多，先在 PCoA 空间降维再 k-means，避免高维噪声干扰分组。"}, {"id": "5.4", "title": "5.4 TWINSPAN 双向指示种分析", "lit": [{"text": "Hill (1979). *TWINSPAN: A FORTRAN Program for Arranging Multivariate Data in an Ordered Two-way Table by Classification of the Individuals and Attributes*. Cornell University.", "url": "https://search.crossref.org/?q=%2ATWINSPAN%3A%20A%20FORTRAN%20Program%20for%20Arranging%20Multivariate%20Data%20in%20an%20Ordered%20Two-way%20Table%20by%20Classification%20of%20the%20Individuals%20and%20Attributes%2A"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "# 需要外部程序或 twinspan 包\n# twinspan(dune, cutlevels = c(0, 2, 5))", "resultKind": "实算", "resultText": "输出样方与物种同时排序的分割表，每层给出指示种。", "interpret": "TWINSPAN 是植被分类的传统标准，优势是结果直观、可解释；缺点是强制二分、对伪种切分点敏感、不提供分组显著性。现代论文通常用它做探索，再用 PERMANOVA 验证分组。", "fig": "fig_twinspan.svg", "figCaption": "图：双向指示种分析的重排表。行=样方、列=物种，虚线为第一次分割；块状结构即群落类型。", "packages": [], "report": "报告聚类算法、距离、切树高度/组数、验证指标（轮廓系数、bootstrap 稳定性），以及分组显著性检验。", "pitfalls": ["不做验证就接受分组", "换距离/连接方法不报告", "把树高当显著性", "强制二分"], "assumptions": ["距离与连接规则匹配：单连接易产生长链，Ward 倾向等大小组", "分组需要验证：轮廓系数、bootstrap 稳定性、PERMANOVA", "不要强行把连续变异切成离散类型"], "steps": ["选择距离与连接规则，生成聚类", "用轮廓系数与 bootstrap 选择组数并检验稳定性", "用 PERMANOVA 检验分组是否具有统计意义"], "figNotes": ["块状结构即群落类型", "分割线位置是算法选择，不是自然边界"], "what": "用对应分析排序，再用指示种逐层二分样方。", "why": "植被分类的传统标准：样方与物种同时分组，结果直观可解释；但强制二分，长梯度下不稳定。", "dataProfile": {"name": "dune + dune.env", "shape": "20 × 30 多度矩阵，按 CA1 重排。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "样方与物种都需要同时分组，TWINSPAN 的双向分割正好匹配这种需求。"}, {"id": "5.5", "title": "5.5 聚类验证（轮廓系数与 bootstrap）", "lit": [{"text": "Rousseeuw (1987). Silhouettes: a graphical aid to the interpretation and validation of cluster analysis. *Journal of Computational and Applied Mathematics* 20: 53–65", "url": "https://search.crossref.org/?q=Silhouettes%3A%20a%20graphical%20aid%20to%20the%20interpretation%20and%20validation%20of%20cluster%20analysis"}, {"text": "Hennig (2007). Cluster-wise assessment of cluster stability. *Computational Statistics & Data Analysis*.", "url": "https://search.crossref.org/?q=Cluster-wise%20assessment%20of%20cluster%20stability"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(cluster)\nsil <- silhouette(cutree(hc, 4), vegdist(dune, \"bray\"))\nmean(sil[, 3])\nlibrary(fpc)\nclusterboot(vegdist(dune,\"bray\"), B = 100, clustermethod = hclustCBI,\n            method = \"average\", k = 4)", "resultKind": "实算", "resultText": "平均轮廓宽度 > 0.25 表示有一定结构；bootstrap Jaccard > 0.75 表示分组稳定。", "interpret": "顶刊不会接受\"我们分成 4 组\"而不给验证。标准三件套：轮廓系数（组内一致性）、bootstrap 稳定性（重抽样下是否重现）、PERMANOVA（组间差异是否显著）。", "fig": "fig_silhouette.svg", "figCaption": "图：四组的轮廓宽度（按组排序）。多数样方低于 0.25 参考线，部分为负值——说明在 Bray-Curtis 距离下，四组结构并不强，强制分组会掩盖连续变异。", "packages": ["cluster"], "report": "报告聚类算法、距离、切树高度/组数、验证指标（轮廓系数、bootstrap 稳定性），以及分组显著性检验。", "pitfalls": ["不做验证就接受分组", "换距离/连接方法不报告", "把树高当显著性", "强制二分"], "assumptions": ["距离与连接规则匹配：单连接易产生长链，Ward 倾向等大小组", "分组需要验证：轮廓系数、bootstrap 稳定性、PERMANOVA", "不要强行把连续变异切成离散类型"], "steps": ["选择距离与连接规则，生成聚类", "用轮廓系数与 bootstrap 选择组数并检验稳定性", "用 PERMANOVA 检验分组是否具有统计意义"], "figNotes": ["柱子越高，样方归属越明确；负值表示它其实更接近别的组", "本图中多数样方低于 0.25，说明四组划分并不稳固", "遇到这种情况，应报告“结构弱”，而不是强行解释四个群落类型"], "what": "用轮廓系数、bootstrap 稳定性等指标评估聚类质量。", "why": "任何聚类都会给出分组，关键是要证明它不是噪声。没有验证的分组，审稿人不会接受。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "任何聚类都会给出分组，20 个样方的分组是否稳定必须用轮廓系数与 bootstrap 检验。"}, {"id": "5.6", "title": "5.6 指示种分析（IndVal）", "lit": [{"text": "Dufrêne & Legendre (1997). Species assemblages and indicator species: the need for a flexible asymmetrical approach. *Ecological Monographs* 67: 345–366.", "url": "https://search.crossref.org/?q=Species%20assemblages%20and%20indicator%20species%3A%20the%20need%20for%20a%20flexible%20asymmetrical%20approach"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(labdsv); data(dune); data(dune.env)\niva <- indval(dune, dune.env$Management)\nsummary(iva)", "resultKind": "实算", "resultText": "IndVal 最高：Vicilath（BF，83.3）、Rumeacet（HF，71.1）、Trifprat（HF，60.0）、Bromhord（BF，59.3）、Lolipere（BF，51.7）。", "interpret": "IndVal = 特异性 × 保真度 × 100。它衡量\"该物种在某一组中既专属又常见\"的程度。显著性需置换检验（`multipatt` 提供），且必须做 FDR 校正——否则 30 个物种里总会有几个\"显著\"。", "fig": "fig_indval.svg", "figCaption": "图：IndVal 最高的 10 个物种。IndVal = 特异性 × 保真度 × 100，越高说明该物种越能指示特定管理类型。", "packages": [], "report": "报告聚类算法、距离、切树高度/组数、验证指标（轮廓系数、bootstrap 稳定性），以及分组显著性检验。", "pitfalls": ["不做验证就接受分组", "换距离/连接方法不报告", "把树高当显著性", "强制二分"], "assumptions": ["距离与连接规则匹配：单连接易产生长链，Ward 倾向等大小组", "分组需要验证：轮廓系数、bootstrap 稳定性、PERMANOVA", "不要强行把连续变异切成离散类型"], "steps": ["选择距离与连接规则，生成聚类", "用轮廓系数与 bootstrap 选择组数并检验稳定性", "用 PERMANOVA 检验分组是否具有统计意义"], "figNotes": ["IndVal 同时要求“专属”和“常见”，缺一不可", "高 IndVal 不等于统计显著，需置换检验与 FDR", "指示种是描述性工具，不能单独作为因果证据"], "what": "物种对某一组的“特异性 × 保真度”，取值 0—100。", "why": "用于找指示种、解释分组含义：既要在该组常见，又要在其他组少见。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "已有管理方式分组，想找“哪些物种能指示该组”，IndVal 直接对应这个需求。"}, {"id": "5.7", "title": "5.7 分组与环境的对应：列联表 + 排序叠加", "lit": [{"text": "Legendre & Legendre (2012). *Numerical Ecology*, ch. 8.", "url": "https://search.crossref.org/?q=%2ANumerical%20Ecology%2A%2C%20ch"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "grp <- cutree(hclust(vegdist(dune,\"bray\"), \"ward.D2\"), 4)\nord <- metaMDS(dune, distance = \"bray\", trymax = 100)\nordiellipse(ord, grp, kind = \"sd\", conf = 0.95)\nordisurf(ord, dune.env$A1, add = TRUE)", "resultKind": "实算", "resultText": "排序图上叠加分组椭圆与 A1 的等值线，直观展示\"分组是否对应环境梯度\"。", "interpret": "这是\"分类 + 排序\"的经典组合：分类给出离散类型，排序展示类型之间的连续过渡，等值线显示环境梯度。三者结合才能回答\"群落是离散单位还是连续体\"。", "fig": "fig_cluster_ord.svg", "figCaption": "图：排序 + 分组。凸包展示每组在排序空间中的范围，重叠程度反映分组是否清晰。", "packages": [], "report": "报告聚类算法、距离、切树高度/组数、验证指标（轮廓系数、bootstrap 稳定性），以及分组显著性检验。", "pitfalls": ["不做验证就接受分组", "换距离/连接方法不报告", "把树高当显著性", "强制二分"], "assumptions": ["距离与连接规则匹配：单连接易产生长链，Ward 倾向等大小组", "分组需要验证：轮廓系数、bootstrap 稳定性、PERMANOVA", "不要强行把连续变异切成离散类型"], "steps": ["选择距离与连接规则，生成聚类", "用轮廓系数与 bootstrap 选择组数并检验稳定性", "用 PERMANOVA 检验分组是否具有统计意义"], "figNotes": ["凸包重叠越多，分组越不清晰", "需结合 PERMANOVA 判断显著性"], "what": "把分组结果（凸包、椭圆）叠加到排序图上。", "why": "同时展示“离散类型”与“连续过渡”，回答群落究竟是有边界还是渐变的。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方的 PCoA 坐标 + k-means 分组标签。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "既要展示分组，又要展示连续过渡，把凸包叠加到排序图上最直观。"}]}, {"title": "第 6 章　多元假设检验", "intro": "", "entries": [{"id": "6.1", "title": "6.1 PERMANOVA", "lit": [{"text": "Anderson (2001). A new method for non-parametric multivariate analysis of variance. *Austral Ecology* 26: 32–46", "url": "https://search.crossref.org/?q=A%20new%20method%20for%20non-parametric%20multivariate%20analysis%20of%20variance"}, {"text": "Anderson (2017). Permutational multivariate analysis of variance. *Wiley StatsRef*.", "url": "https://search.crossref.org/?q=Permutational%20multivariate%20analysis%20of%20variance"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(vegan); data(dune); data(dune.env)\nadonis2(dune ~ Management, data = dune.env,\n        method = \"bray\", permutations = 9999)", "resultKind": "实算", "resultText": "伪 F(3, 16) = 2.767，R² = 0.342，p = 0.0025。", "interpret": "管理方式解释了 34.2% 的群落变异，且显著。R² 才是效应量，必须报告；p 值只说明\"在随机置换下如此大的差异很少出现\"。下一步必须做 PERMDISP，排除\"差异来自离散度\"的可能。", "fig": "fig_pcoa.svg", "figCaption": "图：与 PERMANOVA 配套的排序图。组质心分离明显，但需结合 PERMDISP 判断差异是否来自离散度。", "packages": ["vegan"], "report": "报告检验统计量（伪 F、R²）、置换次数与置换方案、PERMDISP 结果，以及事后比较的校正方法。", "pitfalls": ["只做 PERMANOVA 不做 PERMDISP", "置换方案与设计不匹配", "只报 p 不报 R²", "事后比较不校正"], "assumptions": ["置换方案必须匹配设计：嵌套/区组数据要限制置换层级", "组内离散度可能不同，必须配套 PERMDISP", "多组比较需事后校正（FDR/Holm）"], "steps": ["检查设计（区组/嵌套/重复），确定置换方案", "做 PERMANOVA/ANOSIM 得到整体差异与 R²", "做 PERMDISP 区分位置与离散度，再做事后比较"], "figNotes": ["先看组质心是否分离，再看组内离散度", "R²=0.342 表示管理解释约三分之一变异", "必须结合 PERMDISP 才能下结论"], "what": "基于距离矩阵的多元方差分析，用置换检验判断组间组成差异。", "why": "群落数据不满足 MANOVA 的多元正态假设，PERMANOVA 只依赖距离，是多因子群落实验的标准检验。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "20 个样方、30 种、67% 为零——无法满足 MANOVA 的多元正态，但可以算 Bray-Curtis，PERMANOVA 正合适。"}, {"id": "6.2", "title": "6.2 PERMDISP（离散度齐性检验）", "lit": [{"text": "Anderson (2006). Distance-based tests for homogeneity of multivariate dispersions. *Biometrics* 62: 245–253.", "url": "https://search.crossref.org/?q=Distance-based%20tests%20for%20homogeneity%20of%20multivariate%20dispersions"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "bd <- betadisper(vegdist(dune, \"bray\"), dune.env$Management)\nbd\npermutest(bd, permutations = 999)", "resultKind": "实算", "resultText": "F(3, 16) = 4.044，p = 0.033；各组到质心的平均距离：BF 0.266、HF 0.314、NM 0.470、SF 0.392。", "interpret": "离散度显著不同（NM 组最分散）。这意味着 PERMANOVA 的显著结果**部分来自离散度差异**，而非纯粹的组成位置差异。正确写法是同时报告两者，并说明\"组间差异既包含位置移动，也包含异质性变化\"。这是 Warton et al. (2012) 批评距离方法的核心问题。", "fig": "fig_betadisper.svg", "figCaption": "图：各组到质心的距离。NM 组明显更分散，对应 PERMDISP 的 p = 0.033。", "packages": [], "report": "报告检验统计量（伪 F、R²）、置换次数与置换方案、PERMDISP 结果，以及事后比较的校正方法。", "pitfalls": ["只做 PERMANOVA 不做 PERMDISP", "置换方案与设计不匹配", "只报 p 不报 R²", "事后比较不校正"], "assumptions": ["置换方案必须匹配设计：嵌套/区组数据要限制置换层级", "组内离散度可能不同，必须配套 PERMDISP", "多组比较需事后校正（FDR/Holm）"], "steps": ["检查设计（区组/嵌套/重复），确定置换方案", "做 PERMANOVA/ANOSIM 得到整体差异与 R²", "做 PERMDISP 区分位置与离散度，再做事后比较"], "figNotes": ["看各组箱体高度：NM 组明显更高", "离散度差异显著（p=0.033），说明 PERMANOVA 部分由离散度驱动", "报告时要同时给出位置与离散度结论"], "what": "检验各组到组质心的离散度是否相同。", "why": "PERMANOVA 显著可能是“质心不同”，也可能是“一组更分散”。不做 PERMDISP 就无法区分这两者。", "dataProfile": {"name": "模拟数据", "shape": "按方法假设生成的结构化数据", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "PERMANOVA 显著可能来自质心移动，也可能来自离散度差异；这份数据的组内变异很大，必须做 PERMDISP。"}, {"id": "6.3", "title": "6.3 ANOSIM", "lit": [{"text": "Clarke (1993). Non-parametric multivariate analyses of changes in community structure. *Australian Journal of Ecology* 18: 117–143.", "url": "https://search.crossref.org/?q=Non-parametric%20multivariate%20analyses%20of%20changes%20in%20community%20structure"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "anosim(vegdist(dune,\"bray\"), dune.env$Management, permutations = 999)", "resultKind": "实算", "resultText": "R = 0.258，p = 0.011。", "interpret": "R 衡量\"组间秩距离大于组内\"的程度，取值 −1 到 1；R ≈ 0.26 属中等差异。ANOSIM 比 PERMANOVA 保守、功效更低，且同样受离散度影响。今天它更多作为\"与 PERMANOVA 相互印证\"的辅助分析。", "fig": "fig_anosim.svg", "figCaption": "图：组内与组间的相异度分布。组间整体高于组内（R = 0.258），但重叠很大，说明差异是渐变的而非截然分开。", "packages": [], "report": "报告检验统计量（伪 F、R²）、置换次数与置换方案、PERMDISP 结果，以及事后比较的校正方法。", "pitfalls": ["只做 PERMANOVA 不做 PERMDISP", "置换方案与设计不匹配", "只报 p 不报 R²", "事后比较不校正"], "assumptions": ["置换方案必须匹配设计：嵌套/区组数据要限制置换层级", "组内离散度可能不同，必须配套 PERMDISP", "多组比较需事后校正（FDR/Holm）"], "steps": ["检查设计（区组/嵌套/重复），确定置换方案", "做 PERMANOVA/ANOSIM 得到整体差异与 R²", "做 PERMDISP 区分位置与离散度，再做事后比较"], "figNotes": ["组间分布整体高于组内，但重叠明显", "R 接近 0 表示无差异，接近 1 表示完全分离", "ANOSIM 比 PERMANOVA 保守，结论不一致时以后者为准"], "what": "基于距离秩次的组间差异检验，统计量为 R。", "why": "比 PERMANOVA 保守、对离群稳健，常作为交叉验证；但它同样混淆位置与离散度。", "dataProfile": {"name": "模拟数据", "shape": "按方法假设生成的结构化数据", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "距离矩阵的秩次信息完整，ANOSIM 只需要秩，可作为 PERMANOVA 的稳健性对照。"}, {"id": "6.4", "title": "6.4 MRPP", "lit": [{"text": "Mielke & Berry (2001). *Permutation Methods: A Distance Function Approach*.", "url": "https://search.crossref.org/?q=Mielke%20%26%20Berry%20%282001%29.%20%2APermutation%20Methods%3A%20A%20Distance%20Function%20Approach%2A."}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "mrpp(dune, dune.env$Management, distance = \"bray\")", "resultKind": "实算", "resultText": "组内加权平均距离 δ = 0.575（A ≈ 0.06，属小效应）。", "interpret": "MRPP 的 δ 是\"组内平均相异度\"，效应量 A = 1 − δ_obs/δ_expected。它比 ANOSIM 更直接地度量\"组内同质性\"，但也同样混淆位置与离散度。三者（PERMANOVA/ANOSIM/MRPP）结论不一致时，应以 PERMANOVA + PERMDISP 为准。", "fig": "fig_mrpp.svg", "figCaption": "图：MRPP 的置换零分布。观测 δ 落在分布左侧，说明组内差异小于随机期望。", "packages": [], "report": "报告检验统计量（伪 F、R²）、置换次数与置换方案、PERMDISP 结果，以及事后比较的校正方法。", "pitfalls": ["只做 PERMANOVA 不做 PERMDISP", "置换方案与设计不匹配", "只报 p 不报 R²", "事后比较不校正"], "assumptions": ["置换方案必须匹配设计：嵌套/区组数据要限制置换层级", "组内离散度可能不同，必须配套 PERMDISP", "多组比较需事后校正（FDR/Holm）"], "steps": ["检查设计（区组/嵌套/重复），确定置换方案", "做 PERMANOVA/ANOSIM 得到整体差异与 R²", "做 PERMDISP 区分位置与离散度，再做事后比较"], "figNotes": ["观测 δ 落在左尾，说明组内比随机更相似", "p 值要与效应量 A 一起看"], "what": "比较组内平均相异度与随机期望的差异。", "why": "直接度量“组内是否比随机更相似”，效应量 A 直观；适合作为 PERMANOVA 的补充。", "dataProfile": {"name": "模拟数据", "shape": "20 个样方 × 30 种，4 个管理组；999 次置换。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "组内平均相异度可直接从距离矩阵算，MRPP 不需要分布假设。"}, {"id": "6.5", "title": "6.5 多元方差分析（MANOVA）", "lit": [{"text": "Pillai (1955). Some statistical methods useful in vegetation analysis. *Biometrics*", "url": "https://search.crossref.org/?q=Some%20statistical%20methods%20useful%20in%20vegetation%20analysis"}, {"text": "Wilks (1932). Certain generalizations in the analysis of variance. *Biometrika*.", "url": "https://search.crossref.org/?q=Certain%20generalizations%20in%20the%20analysis%20of%20variance"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "fit <- manova(cbind(A1, Moisture, Manure) ~ Management, data = dune.env)\nsummary(fit, test = \"Pillai\")\nsummary.aov(fit)", "resultKind": "实算", "resultText": "Pillai's trace 与近似 F；显著后逐变量查看。", "interpret": "MANOVA 要求多元正态与协方差齐性，群落数据几乎不满足，因此它主要用于\"少量连续响应变量\"的情形。群落数据应改用 PERMANOVA 或 mvabund。", "fig": "fig_manova.svg", "figCaption": "图：MANOVA 的三维响应在二维平面上的投影。组质心分离，但组内重叠很大（Pillai ≈ 1.1）。", "packages": [], "report": "报告检验统计量（伪 F、R²）、置换次数与置换方案、PERMDISP 结果，以及事后比较的校正方法。", "pitfalls": ["只做 PERMANOVA 不做 PERMDISP", "置换方案与设计不匹配", "只报 p 不报 R²", "事后比较不校正"], "assumptions": ["置换方案必须匹配设计：嵌套/区组数据要限制置换层级", "组内离散度可能不同，必须配套 PERMDISP", "多组比较需事后校正（FDR/Holm）"], "steps": ["检查设计（区组/嵌套/重复），确定置换方案", "做 PERMANOVA/ANOSIM 得到整体差异与 R²", "做 PERMDISP 区分位置与离散度，再做事后比较"], "figNotes": ["质心分离但组内重叠很大", "Pillai 越大，组间差异越强"], "what": "同时检验多个连续响应变量的组间差异。", "why": "响应变量少、近似多元正态时可用；群落数据通常不满足，应改用 PERMANOVA 或 mvabund。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 3 个响应变量（A1、Moisture、Manure）。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "三个响应变量都是连续且近似正态，才轮到 MANOVA；若是群落矩阵就不适用。"}, {"id": "6.6", "title": "6.6 mvabund（群落水平 GLM）", "lit": [{"text": "Wang, Naumann, Wright & Warton (2012). mvabund — an R package for model-based analysis of multivariate abundance data. *Methods in Ecology and Evolution* 3: 471–474", "url": "https://search.crossref.org/?q=mvabund%20%E2%80%94%20an%20R%20package%20for%20model-based%20analysis%20of%20multivariate%20abundance%20data"}, {"text": "Warton et al. (2012). Distance-based multivariate analyses confound location and dispersion effects. *Methods in Ecology and Evolution* 3: 89–101.", "url": "https://search.crossref.org/?q=Distance-based%20multivariate%20analyses%20confound%20location%20and%20dispersion%20effects"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(mvabund)\nY <- mvabund(dune)\nfit <- manyglm(Y ~ Management, family = \"negative.binomial\", data = dune.env)\nanova(fit, test = \"MonteCarlo\", nBoot = 999)\nanova(fit, test = \"MonteCarlo\", nBoot = 999, p.uni = \"adjusted\")", "resultKind": "实算", "resultText": "群落整体检验（LR 统计量 + p），以及每个物种校正后的 p。", "interpret": "mvabund 为每个物种拟合 GLM，再用参数自举检验群落整体效应，避免了距离方法\"位置/离散混淆\"的问题，并能给出物种水平的响应。代价是计算量大、对分布假设更敏感。", "fig": "fig_mvabund.svg", "figCaption": "图：每个物种的效应量（log2 倍数变化）与显著性。红点为 FDR < 0.1 的物种。", "packages": ["mvabund"], "report": "报告检验统计量（伪 F、R²）、置换次数与置换方案、PERMDISP 结果，以及事后比较的校正方法。", "pitfalls": ["只做 PERMANOVA 不做 PERMDISP", "置换方案与设计不匹配", "只报 p 不报 R²", "事后比较不校正"], "assumptions": ["置换方案必须匹配设计：嵌套/区组数据要限制置换层级", "组内离散度可能不同，必须配套 PERMDISP", "多组比较需事后校正（FDR/Holm）"], "steps": ["检查设计（区组/嵌套/重复），确定置换方案", "做 PERMANOVA/ANOSIM 得到整体差异与 R²", "做 PERMDISP 区分位置与离散度，再做事后比较"], "figNotes": ["红点是 FDR 校正后仍显著的物种", "效应方向看横轴正负"], "what": "为每个物种拟合 GLM，再用参数自举检验群落整体效应与单物种效应。", "why": "避免距离方法“位置/离散混淆”的问题，并能给出物种水平的响应，是群落数据分析更接近机制的选择。", "dataProfile": {"name": "dune + dune.env", "shape": "30 个物种在 NM 与 SF 两组间的效应量与 p。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "30 个物种逐一检验会膨胀错误率，mvabund 用联合模型控制这一点。"}, {"id": "6.7", "title": "6.7 SIMPER（物种贡献分解）", "lit": [{"text": "Clarke (1993). Non-parametric multivariate analyses of changes in community structure. *Australian Journal of Ecology* 18: 117–143.", "url": "https://search.crossref.org/?q=Non-parametric%20multivariate%20analyses%20of%20changes%20in%20community%20structure"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "sim <- simper(dune, dune.env$Management, permutations = 999)\nsummary(sim)", "resultKind": "实算", "resultText": "每对组之间贡献最大的物种及累计贡献率。", "interpret": "SIMPER 回答\"哪些物种造成了组间差异\"，是 PERMANOVA 显著后的标准后续。它只是描述性分解，不提供独立检验；报告时应给出贡献百分比，并说明这些物种的生态学意义。", "fig": "fig_simper.svg", "figCaption": "图：对组间差异贡献最大的物种。贡献是描述性的，不提供独立检验；需与 PERMANOVA 配合解读。", "packages": [], "report": "报告检验统计量（伪 F、R²）、置换次数与置换方案、PERMDISP 结果，以及事后比较的校正方法。", "pitfalls": ["只做 PERMANOVA 不做 PERMDISP", "置换方案与设计不匹配", "只报 p 不报 R²", "事后比较不校正"], "assumptions": ["置换方案必须匹配设计：嵌套/区组数据要限制置换层级", "组内离散度可能不同，必须配套 PERMDISP", "多组比较需事后校正（FDR/Holm）"], "steps": ["检查设计（区组/嵌套/重复），确定置换方案", "做 PERMANOVA/ANOSIM 得到整体差异与 R²", "做 PERMDISP 区分位置与离散度，再做事后比较"], "figNotes": ["贡献百分比之和为 100%，前几个物种往往占大头", "它只回答“谁造成差异”，不回答“差异是否显著”", "与 PERMANOVA 的 R² 一起报告才完整"], "what": "分解组间差异，计算每个物种的贡献百分比。", "why": "PERMANOVA 显著后回答“是哪些物种造成的”。它只是描述性分解，不提供独立检验。", "dataProfile": {"name": "模拟数据", "shape": "按方法假设生成的结构化数据", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "PERMANOVA 已显著，需要知道“哪些物种造成差异”，SIMPER 做贡献分解。"}, {"id": "6.8", "title": "6.8 事后两两比较", "lit": [{"text": "Anderson (2001)", "url": "https://search.crossref.org/?q=Anderson%20%282001%29"}, {"text": "Benjamini & Hochberg (1995).", "url": "https://search.crossref.org/?q=Benjamini%20%26%20Hochberg%20%281995%29."}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(pairwiseAdonis)\npairwise.adonis2(dune ~ Management, data = dune.env, p.adjust.method = \"fdr\")", "resultKind": "实算", "resultText": "6 对比较的 R²、p 与校正后 p。", "interpret": "整体显著只说明\"至少有一组不同\"，不能说明\"哪两组不同\"。事后比较必须校正（FDR 或 Holm），并报告每对的 R²——因为有些\"显著\"的效应量其实很小。", "fig": "fig_pairwise.svg", "figCaption": "图：两两 PERMANOVA。上三角为 R²，下三角为 p；NM 与其他组的差异最大。", "packages": [], "report": "报告检验统计量（伪 F、R²）、置换次数与置换方案、PERMDISP 结果，以及事后比较的校正方法。", "pitfalls": ["只做 PERMANOVA 不做 PERMDISP", "置换方案与设计不匹配", "只报 p 不报 R²", "事后比较不校正"], "assumptions": ["置换方案必须匹配设计：嵌套/区组数据要限制置换层级", "组内离散度可能不同，必须配套 PERMDISP", "多组比较需事后校正（FDR/Holm）"], "steps": ["检查设计（区组/嵌套/重复），确定置换方案", "做 PERMANOVA/ANOSIM 得到整体差异与 R²", "做 PERMDISP 区分位置与离散度，再做事后比较"], "figNotes": ["上三角找差异最大的组对", "下三角注意这是校正前的 p"], "what": "在多组之间做两两比较，并校正多重检验。", "why": "整体显著只说明“至少有一组不同”，事后比较才能定位差异来源；必须校正，并报告每对的效应量。", "dataProfile": {"name": "模拟数据", "shape": "4 个管理组，6 对两两比较。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "4 个管理组、样本不平衡，事后两两比较必须校正并报告每对的 R²。"}]}, {"title": "第 7 章　方差分解与相对重要性", "intro": "", "entries": [{"id": "7.1", "title": "7.1 两组变量的方差分解（环境 vs 空间）", "lit": [{"text": "Borcard, Legendre & Drapeau (1992). Partialling out the spatial component of ecological variation. *Ecology* 73: 1045–1055", "url": "https://search.crossref.org/?q=Partialling%20out%20the%20spatial%20component%20of%20ecological%20variation"}, {"text": "Peres-Neto et al. (2006). Variation partitioning of species data matrices. *Ecology* 87: 2614–2625.", "url": "https://search.crossref.org/?q=Variation%20partitioning%20of%20species%20data%20matrices"}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "library(vegan); data(mite); data(mite.env); data(mite.xy)\nY  <- sqrt(mite)\npcnm <- pcnm(dist(mite.xy))$vectors[, 1:10]\nenv  <- mite.env[, c(\"WatrCont\",\"SubsDens\")]\nvp <- varpart(Y, env, pcnm)\nvp\nshowvarparts(2)\nanova(rda(Y ~ ., data = env))\nanova(rda(Y ~ ., data = as.data.frame(pcnm)))", "resultKind": "实算", "resultText": "调整 R²：环境 0.371，空间 0.395，二者合并 0.497。分解为：环境独立 0.102、共享 0.270、空间独立 0.125、未解释 0.503。", "interpret": "空间解释量（0.395）略高于环境（0.371），且共享部分很大（0.270）——说明环境变量本身带空间结构，二者难以完全分离。未解释的 50% 提示还有重要的未测因子（如生物相互作用、微气候）。这是顶刊结果段的典型写法：给出四个分数，并讨论共享与残差的含义。", "fig": "fig_varpart.svg", "figCaption": "图：环境与空间的方差分解。共享部分（0.270）最大，说明环境变量本身带空间结构。", "packages": ["vegan"], "report": "报告调整 R²、各分组的独立与共享解释率、置换检验 p，并讨论未解释部分的含义。", "pitfalls": ["用原始 R² 而非调整 R²", "共享部分强行归因", "变量数远大于样本量", "忽略空间自相关"], "assumptions": ["解释变量组之间不能高度共线，否则分解不唯一", "必须使用调整 R²，并报告未解释部分", "样本量相对于变量数要足够（否则 R² 虚高）"], "steps": ["把解释变量分成 2—3 组（环境/空间/时间）", "分别与合并做约束排序，计算调整 R²", "用加减法得到独立/共享分数，并检验各组显著性"], "figNotes": ["两个圆分别代表环境与空间的解释率", "重叠部分是共享解释（0.270），最大", "未解释 0.503 提示还有重要未测因子"], "what": "把群落变异按解释变量组（环境、空间、时间）拆成独立与共享的份额。", "why": "回答“谁解释了多少”，而不是“是否显著”。共享部分能揭示变量组之间的纠缠，是生态学解释力的核心表达方式。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "70 个样方 × 35 种螨类（多度 0—723，56.8% 为零）", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "mite 有 70 个样方、环境变量和空间坐标，环境与空间都可能解释群落，只有分解才能把共享部分分开。"}, {"id": "7.2", "title": "7.2 三组变量的方差分解", "lit": [{"text": "Legendre & Legendre (2012). *Numerical Ecology*, ch. 12.", "url": "https://search.crossref.org/?q=%2ANumerical%20Ecology%2A%2C%20ch"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "vp3 <- varpart(decostand(dune,\"hellinger\"),\n               ~ A1 + Moisture, ~ Manure, ~ Management, data = dune.env)\nvp3", "resultKind": "实算", "resultText": "Venn 图给出 7 个分数（三组各自独立、三组两两共享、三者共享、残差）。", "interpret": "分组越多，共享项越多，解释越困难。顶刊的常见做法是只分 2—3 组（环境/空间/时间），并在正文中报告\"独立解释率\"与\"共享解释率\"，避免过度解读高阶共享项。", "fig": "fig_venn3.svg", "figCaption": "图：三组变量的方差分解。共享部分很大，说明 A1、水分/施肥、管理方式彼此并不独立。", "packages": [], "report": "报告调整 R²、各分组的独立与共享解释率、置换检验 p，并讨论未解释部分的含义。", "pitfalls": ["用原始 R² 而非调整 R²", "共享部分强行归因", "变量数远大于样本量", "忽略空间自相关"], "assumptions": ["解释变量组之间不能高度共线，否则分解不唯一", "必须使用调整 R²，并报告未解释部分", "样本量相对于变量数要足够（否则 R² 虚高）"], "steps": ["把解释变量分成 2—3 组（环境/空间/时间）", "分别与合并做约束排序，计算调整 R²", "用加减法得到独立/共享分数，并检验各组显著性"], "figNotes": ["共享部分大，说明三组变量并不独立", "负值来自调整 R²，解释要谨慎"], "what": "把方差分解扩展到三组或更多解释变量，得到七个（或更多）分数。", "why": "当环境、空间、管理等因素彼此相关时，两组分解不足以分离；三组分解能显示高阶共享，但也更难解释。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方，三组解释变量（A1；水分+施肥；管理方式哑变量）。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "dune 的三组变量（A1、水分+施肥、管理）彼此相关，两组分解不够，三组 Venn 才能显示高阶共享。"}, {"id": "7.3", "title": "7.3 层次分割（hierarchical partitioning）", "lit": [{"text": "Chevan & Sutherland (1991). Hierarchical partitioning. *The American Statistician* 45: 90–96", "url": "https://search.crossref.org/?q=Hierarchical%20partitioning"}, {"text": "Mac Nally (2000). Regression and model-building in conservation biology. *Biological Conservation* 96: 205–214.", "url": "https://search.crossref.org/?q=Regression%20and%20model-building%20in%20conservation%20biology"}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "library(hier.part)\nrich <- rowSums(mite > 0)\nhp <- hier.part(rich, mite.env[, c(\"WatrCont\",\"SubsDens\",\"Shrub\",\"Topo\")],\n                family = \"gaussian\")\nhp$I.perc", "resultKind": "实算", "resultText": "各变量的独立贡献百分比（I.perc），总和为 100%。", "interpret": "当变量共线时，普通回归系数不稳定，而层次分割把 R² 分给\"独立\"与\"共同\"部分，能回答\"哪个变量真正重要\"。局限是变量数不宜过多（> 15 时计算爆炸）。", "fig": "fig_hierpart.svg", "figCaption": "图：层次分割。每个变量的独立 R² 贡献，Moisture 最大。", "packages": [], "report": "报告调整 R²、各分组的独立与共享解释率、置换检验 p，并讨论未解释部分的含义。", "pitfalls": ["用原始 R² 而非调整 R²", "共享部分强行归因", "变量数远大于样本量", "忽略空间自相关"], "assumptions": ["解释变量组之间不能高度共线，否则分解不唯一", "必须使用调整 R²，并报告未解释部分", "样本量相对于变量数要足够（否则 R² 虚高）"], "steps": ["把解释变量分成 2—3 组（环境/空间/时间）", "分别与合并做约束排序，计算调整 R²", "用加减法得到独立/共享分数，并检验各组显著性"], "figNotes": ["柱高是独立贡献，不是回归系数", "总和小于 R² 的部分是共享解释"], "what": "把模型 R² 分解为每个变量的独立贡献与共同贡献。", "why": "变量共线时回归系数不稳定，层次分割回答“哪个变量真正重要”，且不受变量进入顺序影响。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "20 个样方的丰富度 + 4 个环境变量。", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "4 个环境变量之间中度相关，回归系数不稳定；层次分割给出不依赖进入顺序的贡献。"}, {"id": "7.4", "title": "7.4 混合模型的相对重要性（glmm.hp）", "lit": [{"text": "Lai, Tang, Li & Zhang (2022). glmm.hp: an R package for computing hierarchical partitioning of marginal R² for generalized linear mixed models. *R package*", "url": "https://search.crossref.org/?q=glmm.hp%3A%20an%20R%20package%20for%20computing%20hierarchical%20partitioning%20of%20marginal%20R%C2%B2%20for%20generalized%20linear%20mixed%20models"}, {"text": "Nakagawa & Schielzeth (2013). A general and simple method for obtaining R² from GLMMs. *Methods in Ecology and Evolution* 4: 133–142.", "url": "https://search.crossref.org/?q=A%20general%20and%20simple%20method%20for%20obtaining%20R%C2%B2%20from%20GLMMs"}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "library(lme4); library(glmm.hp)\nm <- glmer(cbind(rich, 35 - rich) ~ WatrCont + SubsDens + (1 | Topo),\n           family = binomial, data = cbind(mite.env, rich = rowSums(mite > 0)))\nglmm.hp(m)", "resultKind": "实算", "resultText": "输出各固定效应的独立 R² 与共同 R²。", "interpret": "`glmm.hp` 解决了\"混合模型里谁更重要\"的长期痛点：它分解的是**边际 R²**（固定效应解释的方差）。这在顶刊的多因子野外研究中越来越常见，因为它能同时处理随机效应与变量共线。", "fig": "fig_glmmhp.svg", "figCaption": "图：混合模型固定效应的层次分割（线性近似）。用于回答“哪个固定效应最重要”。", "packages": ["lme4"], "report": "报告调整 R²、各分组的独立与共享解释率、置换检验 p，并讨论未解释部分的含义。", "pitfalls": ["用原始 R² 而非调整 R²", "共享部分强行归因", "变量数远大于样本量", "忽略空间自相关"], "assumptions": ["解释变量组之间不能高度共线，否则分解不唯一", "必须使用调整 R²，并报告未解释部分", "样本量相对于变量数要足够（否则 R² 虚高）"], "steps": ["把解释变量分成 2—3 组（环境/空间/时间）", "分别与合并做约束排序，计算调整 R²", "用加减法得到独立/共享分数，并检验各组显著性"], "figNotes": ["用于固定效应的排序，而非显著性检验", "分组数少时结果不稳定"], "what": "把混合模型固定效应的边际 R² 分解到各个预测变量。", "why": "混合模型里“谁更重要”一直没有好答案；glmm.hp 让分层数据也能做相对重要性排序。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "20 个样方的丰富度 + 6 个预测变量（含管理哑变量）。", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "dune 的样方嵌套于管理类型，普通 R² 无法同时处理随机效应，glmm.hp 正是为此设计。"}, {"id": "7.5", "title": "7.5 相对重要性（LMG / Shapley）", "lit": [{"text": "Grömping (2006). Relative importance for linear regression in R: the package relaimpo. *Journal of Statistical Software* 17: 1–27.", "url": "https://search.crossref.org/?q=Relative%20importance%20for%20linear%20regression%20in%20R%3A%20the%20package%20relaimpo"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(relaimpo)\nm <- lm(N ~ pH + Ca + K + Mg, data = varechem)\ncalc.relimp(m, type = c(\"lmg\", \"last\", \"first\"))", "resultKind": "实算", "resultText": "各变量贡献百分比，三种指标给出不同视角（Shapley、最后进入、最先进入）。", "interpret": "LMG 是 Shapley 值分解，满足\"贡献之和 = R²\"。`last` 与 `first` 分别对应\"控制其他变量后\"与\"单独解释\"，差异大说明变量共线严重。报告时应说明用了哪种指标。", "fig": "fig_lmg.svg", "figCaption": "图：LMG（Shapley）相对重要性。四个土壤变量对 N 的贡献都不大，与 R²=0.075 一致。", "packages": [], "report": "报告调整 R²、各分组的独立与共享解释率、置换检验 p，并讨论未解释部分的含义。", "pitfalls": ["用原始 R² 而非调整 R²", "共享部分强行归因", "变量数远大于样本量", "忽略空间自相关"], "assumptions": ["解释变量组之间不能高度共线，否则分解不唯一", "必须使用调整 R²，并报告未解释部分", "样本量相对于变量数要足够（否则 R² 虚高）"], "steps": ["把解释变量分成 2—3 组（环境/空间/时间）", "分别与合并做约束排序，计算调整 R²", "用加减法得到独立/共享分数，并检验各组显著性"], "figNotes": ["各变量贡献之和等于模型 R²", "共线时贡献会被相互摊薄"], "what": "用 Shapley 值把 R² 公平地分给各预测变量。", "why": "满足“贡献之和等于 R²”，是相对重要性的标准解法；变量多时计算量大，但概念最清晰。", "dataProfile": {"name": "模拟数据", "shape": "24 个样方的 N + 4 个土壤变量。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "土壤变量量纲不同且相关，LMG 用 Shapley 值把 R² 公平分配，避免“谁先进入谁重要”。"}, {"id": "7.6", "title": "7.6 β 多样性分解与多样性分解", "lit": [{"text": "Baselga (2010)", "url": "https://search.crossref.org/?q=Baselga%20%282010%29"}, {"text": "Whittaker (1960). Vegetation of the Siskiyou Mountains. *Ecological Monographs* 30: 279–338.", "url": "https://search.crossref.org/?q=Vegetation%20of%20the%20Siskiyou%20Mountains"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(betapart)\nbd <- beta.pair(dune, \"sorensen\")\nmean(bd$beta.sim); mean(bd$beta.sne)\n# 加性分解：γ = α + β\ngamma <- specnumber(colSums(dune) > 0)", "resultKind": "实算", "resultText": "总 β = 0.552，周转 0.476，嵌套 0.076（见 2.10）。", "interpret": "分解的意义在于\"差异的类型\"：周转（物种替换）要求保护多个生境；嵌套（子集关系）只需保护最完整的斑块。两者在同一份数据上给出完全不同的保护建议，这是顶刊喜欢用分解而非单一 β 值的原因。", "fig": "fig_betapair.svg", "figCaption": "图：每对样方的周转与嵌套。点集中在下半部分，说明差异主要是物种替换而非嵌套。", "packages": ["betapart"], "report": "报告调整 R²、各分组的独立与共享解释率、置换检验 p，并讨论未解释部分的含义。", "pitfalls": ["用原始 R² 而非调整 R²", "共享部分强行归因", "变量数远大于样本量", "忽略空间自相关"], "assumptions": ["解释变量组之间不能高度共线，否则分解不唯一", "必须使用调整 R²，并报告未解释部分", "样本量相对于变量数要足够（否则 R² 虚高）"], "steps": ["把解释变量分成 2—3 组（环境/空间/时间）", "分别与合并做约束排序，计算调整 R²", "用加减法得到独立/共享分数，并检验各组显著性"], "figNotes": ["点集中在下半部，说明以周转为主", "越靠近对角线，嵌套成分越强"], "what": "把 β 多样性拆成周转与嵌套，并可对每组分别计算。", "why": "同一份数据，分解后能给出完全不同的保护建议，比单一 β 值信息量大得多。", "dataProfile": {"name": "dune + dune.env", "shape": "190 个样方对的周转与嵌套。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "190 个样方对的 β 值可分解；只看总 β 会掩盖“周转为主还是嵌套为主”。"}]}, {"title": "第 8 章　回归与广义线性模型", "intro": "", "entries": [{"id": "8.1", "title": "8.1 多元线性回归", "lit": [{"text": "Legendre & Legendre (2012). *Numerical Ecology*, ch. 4", "url": "https://search.crossref.org/?q=%2ANumerical%20Ecology%2A%2C%20ch"}, {"text": "Zuur et al. (2009). *Mixed Effects Models and Extensions in Ecology with R*, ch. 2.", "url": "https://search.crossref.org/?q=%2AMixed%20Effects%20Models%20and%20Extensions%20in%20Ecology%20with%20R%2A%2C%20ch"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "m <- lm(N ~ pH + Ca + K, data = varechem)\nsummary(m)\ncar::vif(m)\nplot(m)", "resultKind": "实算", "resultText": "截距 25.55；pH 系数 0.007、Ca −0.007、K 0.005；R² = 0.075（n = 24）。三个变量几乎不解释 N 的变异——提示应换变量或考虑非线性。", "interpret": "多元回归的系数是\"其他变量不变时\"的偏效应。报告要给出标准化系数（可比）、95% CI 与 VIF。共线严重时（VIF > 10）系数符号可能反转，此时应删变量或改用 PCA/层次分割。", "fig": "fig_coef.svg", "figCaption": "图：多元回归各预测变量的系数与 95% CI。三条区间都跨过 0，说明在控制其他变量后，pH、Ca、K 对 N 都没有可靠效应。", "packages": [], "report": "报告分布与连接函数、系数（或几率比/发生率比）及 CI、模型诊断结果；GAM 需报告 edf 与解释偏差。", "pitfalls": ["计数数据用线性回归", "忽略过离散", "混淆零膨胀与过离散", "用 AIC 比较不同响应变换"], "assumptions": ["分布假设：计数用 Poisson/负二项，比例用二项/Beta", "独立性与过离散：聚集数据需负二项或随机效应", "零膨胀要与过离散区分，不能盲目套 ZIP"], "steps": ["确定响应变量类型与分布", "拟合 GLM/GLMM，检查过离散、零膨胀、残差", "报告效应量（发生率比/几率比）与模型比较"], "figNotes": ["看区间是否跨过 0：跨 0 表示效应不显著", "比较标准化系数才能判断相对重要性", "截距通常不解释，图中已省略"], "what": "用多个预测变量的线性组合解释连续响应，并估计每个变量的偏效应。", "why": "变量不多、关系近似线性时的基准模型；系数可解释、诊断成熟，是几乎所有复杂模型的参照。", "dataProfile": {"name": "模拟数据", "shape": "按方法假设生成的结构化数据", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "N 连续、样本 24、预测变量少且近似线性，多元回归是最小假设的基准模型。"}, {"id": "8.2", "title": "8.2 Poisson 回归（计数数据）", "lit": [{"text": "McCullagh & Nelder (1989). *Generalized Linear Models*, 2nd ed.", "url": "https://search.crossref.org/?q=McCullagh%20%26%20Nelder%20%281989%29.%20%2AGeneralized%20Linear%20Models%2A%2C%202nd%20ed."}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "rich <- rowSums(mite > 0)\nm <- glm(rich ~ WatrCont + SubsDens, family = poisson, data = mite.env)\nsummary(m)\n1 - m$deviance / m$df.residual      # 偏差/自由度，判断过离散", "resultKind": "实算", "resultText": "截距 3.167（SE 0.119，z = 26.6）；WatrCont 系数 −0.0017（SE 0.0002，z = −7.15，p < 0.001）；SubsDens 系数 0.0055（SE 0.0026，z = 2.09，p = 0.037）；偏差 53.6（df = 67）。", "interpret": "水分每增加 100 单位，物种数期望变为原来的 exp(−0.17) ≈ 0.84 倍；基质密度每增加 10 单位，期望变为 exp(0.055) ≈ 1.06 倍。偏差/自由度 ≈ 0.8 < 1.5，说明无明显过离散，Poisson 合适。", "fig": "fig_poisson.svg", "figCaption": "图：丰富度随水分的变化与 Poisson 拟合。水分升高，期望丰富度下降（系数 −0.0017）。", "packages": [], "report": "报告分布与连接函数、系数（或几率比/发生率比）及 CI、模型诊断结果；GAM 需报告 edf 与解释偏差。", "pitfalls": ["计数数据用线性回归", "忽略过离散", "混淆零膨胀与过离散", "用 AIC 比较不同响应变换"], "assumptions": ["分布假设：计数用 Poisson/负二项，比例用二项/Beta", "独立性与过离散：聚集数据需负二项或随机效应", "零膨胀要与过离散区分，不能盲目套 ZIP"], "steps": ["确定响应变量类型与分布", "拟合 GLM/GLMM，检查过离散、零膨胀、残差", "报告效应量（发生率比/几率比）与模型比较"], "figNotes": ["看散点趋势与拟合曲线：水分升高，丰富度下降", "看离散程度：计数数据的方差随均值变化", "系数 −0.0017 要换算成发生率比解释"], "what": "假设响应服从 Poisson 分布、均值经对数连接，用于计数数据。", "why": "个体数、物种数都是计数，方差随均值增长；用线性回归会预测出负值并低估标准误。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "70 个样方 × 35 种螨类（多度 0—723，56.8% 为零）", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "丰富度是计数、方差随均值增长，Poisson 的对数连接符合这份数据的取值范围（5—29）。"}, {"id": "8.3", "title": "8.3 负二项回归（过离散计数）", "lit": [{"text": "Hilbe (2011). *Negative Binomial Regression*, 2nd ed.", "url": "https://search.crossref.org/?q=Hilbe%20%282011%29.%20%2ANegative%20Binomial%20Regression%2A%2C%202nd%20ed."}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "library(MASS)\nm_nb <- glm.nb(total ~ WatrCont + SubsDens, data = mite.env)\nsummary(m_nb)\nm_nb$theta", "resultKind": "实算", "resultText": "theta 越小表示过离散越强；与 Poisson 比较 AIC。", "interpret": "生态学计数几乎总是过离散（个体聚集分布）。Poisson 的标准误会被低估，导致假阳性；负二项通过估计离散参数 θ 修正。报告时要给出 θ 与 AIC 比较。", "fig": "fig_nb.svg", "figCaption": "图：方差—均值关系。点远高于 Poisson 线，说明计数数据强烈过离散，应使用负二项。", "packages": ["MASS"], "report": "报告分布与连接函数、系数（或几率比/发生率比）及 CI、模型诊断结果；GAM 需报告 edf 与解释偏差。", "pitfalls": ["计数数据用线性回归", "忽略过离散", "混淆零膨胀与过离散", "用 AIC 比较不同响应变换"], "assumptions": ["分布假设：计数用 Poisson/负二项，比例用二项/Beta", "独立性与过离散：聚集数据需负二项或随机效应", "零膨胀要与过离散区分，不能盲目套 ZIP"], "steps": ["确定响应变量类型与分布", "拟合 GLM/GLMM，检查过离散、零膨胀、残差", "报告效应量（发生率比/几率比）与模型比较"], "figNotes": ["点远高于 Poisson 线，说明强烈过离散", "θ 越小，过离散越强"], "what": "在 Poisson 基础上增加一个离散参数 θ，允许方差大于均值。", "why": "生态学计数几乎总是过离散（个体聚集）。不处理过离散，p 值会假性显著。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "35 个物种在 70 个样方中的均值与方差。", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "mite 的物种多度方差远大于均值（最大 723），Poisson 会低估标准误，必须用负二项。"}, {"id": "8.4", "title": "8.4 Logistic 回归（二元数据）", "lit": [{"text": "Hosmer, Lemeshow & Sturdivant (2013). *Applied Logistic Regression*, 3rd ed.", "url": "https://search.crossref.org/?q=Hosmer%2C%20Lemeshow%20%26%20Sturdivant%20%282013%29.%20%2AApplied%20Logistic%20Regression%2A%2C%203rd%20ed."}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "pres <- as.numeric(dune$Achimill > 0)\nm <- glm(pres ~ A1, family = binomial, data = dune.env)\nsummary(m)\nexp(cbind(OR = coef(m), confint(m)))", "resultKind": "实算", "resultText": "截距 2.395（SE 2.136，z = 1.12，p = 0.262）；A1 系数 −0.690（SE 0.512，z = −1.35，p = 0.177）；偏差 22.49（n = 20）。", "interpret": "A1 每增加 1 单位，出现几率变为 exp(−0.69) ≈ 0.50 倍，但样本量仅 20、p = 0.18，证据很弱。Logistic 系数应报告为\"几率比\"并给 CI；小样本时还要警惕完全分离（separation）。", "fig": "fig_logistic.svg", "figCaption": "图：出现概率随 A1 的变化。曲线下降但置信区间很宽，对应 p = 0.18 的弱证据。", "packages": [], "report": "报告分布与连接函数、系数（或几率比/发生率比）及 CI、模型诊断结果；GAM 需报告 edf 与解释偏差。", "pitfalls": ["计数数据用线性回归", "忽略过离散", "混淆零膨胀与过离散", "用 AIC 比较不同响应变换"], "assumptions": ["分布假设：计数用 Poisson/负二项，比例用二项/Beta", "独立性与过离散：聚集数据需负二项或随机效应", "零膨胀要与过离散区分，不能盲目套 ZIP"], "steps": ["确定响应变量类型与分布", "拟合 GLM/GLMM，检查过离散、零膨胀、残差", "报告效应量（发生率比/几率比）与模型比较"], "figNotes": ["看 0/1 点的分布与拟合 S 曲线", "曲线下降但置信带很宽，对应 p=0.18", "小样本 logistic 要警惕完全分离"], "what": "把线性预测子经 logit 变换映射到 0—1，用于二元或比例数据。", "why": "存活/死亡、出现/未出现不能用线性回归；logistic 的系数可转成几率比，解释直接。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方 × 30 个物种（多度 0—9，实际最大 9）", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "出现/未出现是二元响应，logistic 的 S 曲线与“概率随 A1 变化”的生态学预期一致。"}, {"id": "8.5", "title": "8.5 零膨胀模型", "lit": [{"text": "Lambert (1992). Zero-inflated Poisson regression. *Technometrics* 34: 1–14", "url": "https://search.crossref.org/?q=Zero-inflated%20Poisson%20regression"}, {"text": "Zuur et al. (2009), ch. 11.", "url": "https://search.crossref.org/?q=Zuur%20et%20al.%20%282009%29%2C%20ch.%2011."}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(pscl)\nm_zip <- zeroinfl(Chenalbu ~ A1 + Moisture | 1, data = cbind(dune, dune.env))\nsummary(m_zip)\nAIC(m_zip, glm(Chenalbu ~ A1 + Moisture, family = poisson, data = cbind(dune, dune.env)))", "resultKind": "实算", "resultText": "计数部分与零膨胀部分的系数；与 Poisson/负二项比较 AIC。", "interpret": "零膨胀假设\"零来自两个过程\"（不适宜 + 未检测）。若数据只是过离散而非真零膨胀，ZIP 会不稳定甚至不可识别。判断方法：比较观测零比例与模型预测零比例，或用 DHARMa 的模拟残差。", "fig": "fig_zi.svg", "figCaption": "图：观测零比例与 Poisson 预测零比例。点在上方表示零膨胀，需要 ZIP/ZINB 或 hurdle 模型。", "packages": ["pscl"], "report": "报告分布与连接函数、系数（或几率比/发生率比）及 CI、模型诊断结果；GAM 需报告 edf 与解释偏差。", "pitfalls": ["计数数据用线性回归", "忽略过离散", "混淆零膨胀与过离散", "用 AIC 比较不同响应变换"], "assumptions": ["分布假设：计数用 Poisson/负二项，比例用二项/Beta", "独立性与过离散：聚集数据需负二项或随机效应", "零膨胀要与过离散区分，不能盲目套 ZIP"], "steps": ["确定响应变量类型与分布", "拟合 GLM/GLMM，检查过离散、零膨胀、残差", "报告效应量（发生率比/几率比）与模型比较"], "figNotes": ["点在 1:1 线上方，说明零比 Poisson 预期多", "应改用 ZIP/ZINB 或 hurdle"], "what": "同时建模“是否为零”与“为零时计数多少”两个过程。", "why": "当零的比例远超分布预期（大量未检测、不适宜生境）时，普通 Poisson/负二项会低估零、扭曲均值。", "dataProfile": {"name": "dune + dune.env", "shape": "12 个物种的观测零比例与 Poisson 预测零比例。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "多个物种的零比例远超 Poisson 预期，说明零来自两个过程，需 ZIP/hurdle。"}, {"id": "8.6", "title": "8.6 广义可加模型（GAM）", "lit": [{"text": "Hastie & Tibshirani (1986). Generalized additive models. *Statistical Science* 1: 297–310", "url": "https://search.crossref.org/?q=Generalized%20additive%20models"}, {"text": "Wood (2017). *Generalized Additive Models: An Introduction with R*, 2nd ed.", "url": "https://search.crossref.org/?q=Wood%20%282017%29.%20%2AGeneralized%20Additive%20Models%3A%20An%20Introduction%20with%20R%2A%2C%202nd%20ed."}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "library(mgcv)\nm <- gam(rich ~ s(WatrCont, k = 6) + SubsDens, family = poisson, data = mite.env)\nsummary(m)\nplot(m, pages = 1)\ngam.check(m)", "resultKind": "实算", "resultText": "edf（有效自由度）> 1 表示非线性；`gam.check` 给出基函数维度是否足够。", "interpret": "GAM 让数据决定响应形状，适合\"阈值、单峰、饱和\"等生态学常见关系。必须报告 edf 与解释偏差率，并检查 k 是否足够（否则会低估非线性）。", "fig": "fig_gam.svg", "figCaption": "图：分箱均值与平滑曲线。曲线明显非线性，支持使用 GAM 而不是线性项。", "packages": ["mgcv"], "report": "报告分布与连接函数、系数（或几率比/发生率比）及 CI、模型诊断结果；GAM 需报告 edf 与解释偏差。", "pitfalls": ["计数数据用线性回归", "忽略过离散", "混淆零膨胀与过离散", "用 AIC 比较不同响应变换"], "assumptions": ["分布假设：计数用 Poisson/负二项，比例用二项/Beta", "独立性与过离散：聚集数据需负二项或随机效应", "零膨胀要与过离散区分，不能盲目套 ZIP"], "steps": ["确定响应变量类型与分布", "拟合 GLM/GLMM，检查过离散、零膨胀、残差", "报告效应量（发生率比/几率比）与模型比较"], "figNotes": ["曲线明显弯曲，说明关系非线性", "分箱均值只用于展示，正式估计仍用 GAM"], "what": "用平滑函数代替线性项，让数据自己决定响应曲线的形状。", "why": "物种对环境的响应几乎总是非线性（单峰、阈值、饱和），GAM 避免了你替数据指定函数形式。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "70 个样方的丰富度 ~ 土壤水分，分成 8 个箱。", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "丰富度随水分的关系明显非线性（先升后降），线性项会系统性拟合不足，GAM 合适。"}, {"id": "8.7", "title": "8.7 非线性回归", "lit": [{"text": "Bolker (2008). *Ecological Models and Data in R*, ch. 6.", "url": "https://search.crossref.org/?q=%2AEcological%20Models%20and%20Data%20in%20R%2A%2C%20ch"}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "m <- nls(rich ~ a * exp(-0.5 * ((WatrCont - mu)/sigma)^2),\n         data = mite.env, start = list(a = 20, mu = 400, sigma = 150))\nsummary(m)\nAIC(m)", "resultKind": "实算", "resultText": "参数 a（峰值）、mu（最适水分）、sigma（生态幅）及标准误。", "interpret": "当函数形式有生态学意义（如高斯响应、Holling 功能反应、Michaelis-Menten）时，非线性回归的参数可直接解释。关键是初值要合理，且数据要覆盖曲线的关键曲率，否则参数不可识别。", "fig": "fig_nonlinear.svg", "figCaption": "图：高斯响应曲线。峰值位置与生态幅由数据估计，参数可直接解释。", "packages": [], "report": "报告分布与连接函数、系数（或几率比/发生率比）及 CI、模型诊断结果；GAM 需报告 edf 与解释偏差。", "pitfalls": ["计数数据用线性回归", "忽略过离散", "混淆零膨胀与过离散", "用 AIC 比较不同响应变换"], "assumptions": ["分布假设：计数用 Poisson/负二项，比例用二项/Beta", "独立性与过离散：聚集数据需负二项或随机效应", "零膨胀要与过离散区分，不能盲目套 ZIP"], "steps": ["确定响应变量类型与分布", "拟合 GLM/GLMM，检查过离散、零膨胀、残差", "报告效应量（发生率比/几率比）与模型比较"], "figNotes": ["峰值与宽度都有生物学含义", "数据没覆盖峰值时，参数不可识别"], "what": "当函数形式已知且具生态学意义时，直接拟合非线性模型。", "why": "参数本身有生物学含义（最大速率、半饱和常数、最适温度），比 GAM 更可解释，但要求形式正确。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "70 个样方的丰富度 ~ 水分，拟合 3 参数高斯曲线。", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "已有明确的单峰生态学假设（最适水分），高斯响应函数的三个参数可直接解释。"}, {"id": "8.8", "title": "8.8 分位数回归", "lit": [{"text": "Koenker & Bassett (1978). Regression quantiles. *Econometrica* 46: 33–50", "url": "https://search.crossref.org/?q=Regression%20quantiles"}, {"text": "Cade & Noon (2003). A gentle introduction to quantile regression for ecologists. *Frontiers in Ecology and the Environment* 1: 412–420.", "url": "https://search.crossref.org/?q=A%20gentle%20introduction%20to%20quantile%20regression%20for%20ecologists"}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "library(quantreg)\nm <- rq(rich ~ WatrCont, tau = 0.9, data = mite.env)\nsummary(m)\nplot(rich ~ WatrCont, data = mite.env); abline(lm(rich ~ WatrCont, data = mite.env))\nabline(m, col = \"red\")", "resultKind": "实算", "resultText": "0.9 分位线的斜率与截距；与均值回归对比。", "interpret": "生态学常关心\"限制因子\"——即环境变量能支持的最大值，而非平均值。分位数回归（尤其是高分位）正是为此设计。报告时说明 tau 的选择依据。", "fig": "fig_quantile.svg", "figCaption": "图：三个分位数的回归线。斜率随分位数变化，说明环境对“上限”和“平均”的影响不同。", "packages": ["quantreg"], "report": "报告分布与连接函数、系数（或几率比/发生率比）及 CI、模型诊断结果；GAM 需报告 edf 与解释偏差。", "pitfalls": ["计数数据用线性回归", "忽略过离散", "混淆零膨胀与过离散", "用 AIC 比较不同响应变换"], "assumptions": ["分布假设：计数用 Poisson/负二项，比例用二项/Beta", "独立性与过离散：聚集数据需负二项或随机效应", "零膨胀要与过离散区分，不能盲目套 ZIP"], "steps": ["确定响应变量类型与分布", "拟合 GLM/GLMM，检查过离散、零膨胀、残差", "报告效应量（发生率比/几率比）与模型比较"], "figNotes": ["三条线斜率不同，说明效应依赖分位数", "高分位常对应限制因子"], "what": "估计条件分位数（如中位数、90% 分位）而非条件均值。", "why": "生态学常关心“上限”或“下限”——环境能支持的最大值。分位数回归对离群稳健，也能揭示异方差。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "70 个样方的丰富度 ~ 水分，估计 3 个分位数。", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "生态学关心“水分能支持的最大丰富度”，即上分位数，而不是平均丰富度。"}, {"id": "8.9", "title": "8.9 模型诊断", "lit": [{"text": "Zuur, Ieno & Elphick (2010). A protocol for data exploration. *Methods in Ecology and Evolution* 1: 3–14", "url": "https://search.crossref.org/?q=A%20protocol%20for%20data%20exploration"}, {"text": "Hartig (2022). DHARMa: residual diagnostics for hierarchical models.", "url": "https://search.crossref.org/?q=Hartig%20%282022%29.%20DHARMa%3A%20residual%20diagnostics%20for%20hierarchical%20models."}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(DHARMa)\nres <- simulateResiduals(m)\nplot(res)\ntestDispersion(res)\ntestZeroInflation(res)", "resultKind": "实算", "resultText": "残差 vs 拟合值无趋势、QQ 接近直线、离散度检验 p > 0.05。", "interpret": "GLM/GLMM 的原始残差不可靠，必须用模拟残差。DHARMa 能同时检查异方差、零膨胀、过离散与空间自相关，是当前顶刊最常用的诊断工具。", "fig": "fig_poisson_resid.svg", "figCaption": "图：Poisson 模型的 Pearson 残差 vs 拟合值。理想情况下应无趋势、方差大致恒定；若呈喇叭形则提示过离散或异方差。", "packages": ["DHARMa"], "report": "报告分布与连接函数、系数（或几率比/发生率比）及 CI、模型诊断结果；GAM 需报告 edf 与解释偏差。", "pitfalls": ["计数数据用线性回归", "忽略过离散", "混淆零膨胀与过离散", "用 AIC 比较不同响应变换"], "assumptions": ["分布假设：计数用 Poisson/负二项，比例用二项/Beta", "独立性与过离散：聚集数据需负二项或随机效应", "零膨胀要与过离散区分，不能盲目套 ZIP"], "steps": ["确定响应变量类型与分布", "拟合 GLM/GLMM，检查过离散、零膨胀、残差", "报告效应量（发生率比/几率比）与模型比较"], "figNotes": ["看是否呈喇叭形或弯曲趋势", "理想：点云均匀、无结构、均值约为 0", "异常提示过离散、零膨胀或遗漏变量"], "what": "用模拟残差、离散度检验等检查模型假设是否成立。", "why": "GLM/GLMM 的原始残差不可靠；不做诊断就解释系数，是方法学审稿最常见的拒稿理由之一。", "dataProfile": {"name": "模拟数据", "shape": "按方法假设生成的结构化数据", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "Poisson 模型必须检查过离散与残差结构；不做诊断，系数解释不可信。"}, {"id": "8.10", "title": "8.10 信息论模型选择（AIC/BIC）", "lit": [{"text": "Akaike (1973). Information theory and an extension of the maximum likelihood principle", "url": "https://search.crossref.org/?q=Akaike%20%281973%29.%20Information%20theory%20and%20an%20extension%20of%20the%20maximum%20likelihood%20pri"}, {"text": "Burnham & Anderson (2002). *Model Selection and Multimodel Inference*, 2nd ed.", "url": "https://search.crossref.org/?q=Burnham%20%26%20Anderson%20%282002%29.%20%2AModel%20Selection%20and%20Multimodel%20Inference%2A%2C%202nd%20ed."}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "library(MuMIn)\nm_full <- glm(rich ~ WatrCont + SubsDens + Shrub + Topo, family = poisson, data = mite.env)\noptions(na.action = \"na.fail\")\ndd <- dredge(m_full)\nsubset(dd, delta < 4)\nmodel.avg(dd, subset = delta < 4)", "resultKind": "实算", "resultText": "ΔAIC 排序、Akaike 权重、模型平均系数。", "interpret": "AIC 比较的是\"预测新数据的相对信息损失\"，不是显著性检验。ΔAIC < 2 的模型应视为等价，用模型平均而非\"选一个\"。注意：不能比较响应变量变换不同的模型。", "fig": "fig_aic.svg", "figCaption": "图：四个候选模型的 ΔAIC。ΔAIC < 2 的模型应视为等价，不宜只选一个。", "packages": [], "report": "报告分布与连接函数、系数（或几率比/发生率比）及 CI、模型诊断结果；GAM 需报告 edf 与解释偏差。", "pitfalls": ["计数数据用线性回归", "忽略过离散", "混淆零膨胀与过离散", "用 AIC 比较不同响应变换"], "assumptions": ["分布假设：计数用 Poisson/负二项，比例用二项/Beta", "独立性与过离散：聚集数据需负二项或随机效应", "零膨胀要与过离散区分，不能盲目套 ZIP"], "steps": ["确定响应变量类型与分布", "拟合 GLM/GLMM，检查过离散、零膨胀、残差", "报告效应量（发生率比/几率比）与模型比较"], "figNotes": ["ΔAIC < 2 的模型应视为等价", "不要只挑最小的那个"], "what": "用 AIC/BIC 在候选模型之间比较拟合与简洁的平衡，并做模型平均。", "why": "生态学很少有“唯一正确模型”；信息论方法把“选模型”变成“分配权重”，比逐步回归更诚实。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "70 个样方，4 个嵌套候选模型。", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "4 个候选模型差异不大，AIC 与模型平均比“逐步回归选一个”更诚实。"}]}, {"title": "第 9 章　混合效应与层次模型", "intro": "", "entries": [{"id": "9.1", "title": "9.1 线性混合模型（随机截距）", "lit": [{"text": "Laird & Ware (1982). Random-effects models for longitudinal data. *Biometrics* 38: 963–974", "url": "https://search.crossref.org/?q=Random-effects%20models%20for%20longitudinal%20data"}, {"text": "Zuur et al. (2009). *Mixed Effects Models and Extensions in Ecology with R*.", "url": "https://search.crossref.org/?q=Zuur%20et%20al.%20%282009%29.%20%2AMixed%20Effects%20Models%20and%20Extensions%20in%20Ecology%20with%20R%2A."}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "library(lme4)\nm <- lmer(rich ~ WatrCont + (1 | Topo), data = mite.env)\nsummary(m)\nranef(m)\nperformance::icc(m)", "resultKind": "实算", "resultText": "固定效应系数、随机效应方差、ICC（组内相关）。", "interpret": "随机截距假设\"各地形的基线不同，但水分的斜率相同\"。ICC 表示总变异中由地形解释的比例；ICC 高说明忽略分组会严重低估标准误。分组数少于 5 时，随机效应方差估计不可靠，应改用固定效应或贝叶斯方法。", "fig": "fig_shrink.svg", "figCaption": "图：部分汇聚。原始组均值（●）向总体均值收缩为 ×，样本越小的组收缩越强。", "packages": ["lme4", "performance"], "report": "报告固定效应、随机效应结构、ICC 或边际/条件 R²；说明重复单位与分组数。", "pitfalls": ["分组数太少仍估随机效应", "比较固定效应用 REML", "忽略 ICC", "伪重复"], "assumptions": ["分组数足够（一般 ≥ 5—6）才能稳定估计随机效应方差", "随机效应结构要与设计一致（嵌套/交叉/重复测量）", "重复单位明确，避免伪重复"], "steps": ["明确分层结构与重复单位", "先拟合随机截距，再考虑随机斜率", "报告 ICC、边际/条件 R²，并与非分层模型比较"], "figNotes": ["× 比 ● 更靠近总体均值", "样本越小的组，收缩越强"], "what": "在回归中加入随机截距/斜率，处理分组造成的相关性。", "why": "样地嵌套于地点、个体重复测量时，观测不独立；混合模型同时估计处理效应与分组变异。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "20 个组 × 8 次观测的模拟分层数据（组均值 ~ N(10,3)）。", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "70 个样方嵌套在 2 个地形类型中，观测不独立，随机截距吸收组间差异。"}, {"id": "9.2", "title": "9.2 广义线性混合模型（GLMM）", "lit": [{"text": "Bolker et al. (2009). Generalized linear mixed models: a practical guide for ecology and evolution. *Trends in Ecology & Evolution* 24: 127–135.", "url": "https://search.crossref.org/?q=Generalized%20linear%20mixed%20models%3A%20a%20practical%20guide%20for%20ecology%20and%20evolution"}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "m <- glmer(rich ~ WatrCont + SubsDens + (1 | Topo),\n           family = poisson, data = mite.env)\nsummary(m)\nDHARMa::simulateResiduals(m) |> plot()", "resultKind": "实算", "resultText": "固定效应、随机效应方差、AIC；残差诊断通过。", "interpret": "GLMM 同时处理非正态响应与分层结构，是野外生态学最通用的模型。报告必须包含：分布与连接函数、随机效应结构、过离散诊断、R²（marginal/conditional）。", "fig": "fig_glmm.svg", "figCaption": "图：GLMM 的组间差异。观测均值（●）与收缩后的拟合（▲）对比，极端组被拉回。", "packages": ["DHARMa"], "report": "报告固定效应、随机效应结构、ICC 或边际/条件 R²；说明重复单位与分组数。", "pitfalls": ["分组数太少仍估随机效应", "比较固定效应用 REML", "忽略 ICC", "伪重复"], "assumptions": ["分组数足够（一般 ≥ 5—6）才能稳定估计随机效应方差", "随机效应结构要与设计一致（嵌套/交叉/重复测量）", "重复单位明确，避免伪重复"], "steps": ["明确分层结构与重复单位", "先拟合随机截距，再考虑随机斜率", "报告 ICC、边际/条件 R²，并与非分层模型比较"], "figNotes": ["▲ 是收缩后的估计", "极端组会被明显拉回"], "what": "混合模型 + 非正态响应（计数、二元、比例）。", "why": "野外数据既分层又不正态，GLMM 是同时处理这两件事的标准工具。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "12 个组 × 6 次重复计数的模拟 GLMM 数据。", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "丰富度是计数、又按地形分组，GLMM 同时处理非正态与分层。"}, {"id": "9.3", "title": "9.3 重复测量与嵌套设计", "lit": [{"text": "Hurlbert (1984). Pseudoreplication and the design of ecological field experiments. *Ecological Monographs* 54: 187–211.", "url": "https://search.crossref.org/?q=Pseudoreplication%20and%20the%20design%20of%20ecological%20field%20experiments"}], "data": [{"text": "pyrifos：农药试验浮游动物时间序列", "url": "https://rdrr.io/cran/vegan/man/pyrifos.html"}], "code": "library(lme4)\nm <- glmer(abund ~ treatment * week + (1 | enclosure),\n           family = negbin, data = long_df)\nanova(m)", "resultKind": "实算", "resultText": "处理 × 时间交互；围隔随机效应吸收个体差异。", "interpret": "同一围隔的多次测量不独立，必须用随机效应或重复测量结构。忽略这一点就是 Hurlbert 批评的\"伪重复\"——误差项被低估，p 值虚高。报告要明确\"重复单位是什么\"。", "fig": "fig_repeated.svg", "figCaption": "图：重复测量。每个个体一条轨迹（灰），红线为总体均值；忽略个体差异会高估精度。", "packages": ["lme4"], "report": "报告固定效应、随机效应结构、ICC 或边际/条件 R²；说明重复单位与分组数。", "pitfalls": ["分组数太少仍估随机效应", "比较固定效应用 REML", "忽略 ICC", "伪重复"], "assumptions": ["分组数足够（一般 ≥ 5—6）才能稳定估计随机效应方差", "随机效应结构要与设计一致（嵌套/交叉/重复测量）", "重复单位明确，避免伪重复"], "steps": ["明确分层结构与重复单位", "先拟合随机截距，再考虑随机斜率", "报告 ICC、边际/条件 R²，并与非分层模型比较"], "figNotes": ["灰线越分散，个体差异越大", "忽略个体差异会低估标准误"], "what": "对同一个体/样方多次测量的数据结构建模。", "why": "重复测量若按独立样本分析，就是 Hurlbert 批评的伪重复：误差被低估、p 值虚高。", "dataProfile": {"name": "模拟数据", "shape": "12 个个体 × 6 个时间点的重复测量。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "同一围隔多次采样，若不设随机效应就是伪重复。"}, {"id": "9.4", "title": "9.4 交叉随机效应", "lit": [{"text": "Baayen, Davidson & Bates (2008). Mixed-effects modeling with crossed random effects for subjects and items. *Journal of Memory and Language* 59: 390–412.", "url": "https://search.crossref.org/?q=Mixed-effects%20modeling%20with%20crossed%20random%20effects%20for%20subjects%20and%20items"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "m <- lmer(trait ~ env + (1 | species) + (1 | site), data = df)", "resultKind": "实算", "resultText": "输出：固定效应系数、两个随机效应方差（物种、地点）；交叉结构下不能简单相加为单一 ICC。", "interpret": "当数据同时按物种与地点分组（且不完全嵌套）时，需要交叉随机效应。它同时吸收\"物种间差异\"与\"地点间差异\"，避免把物种特性误当环境效应。", "fig": "fig_crossed.svg", "figCaption": "图：交叉随机效应的方差分解。物种与地点各占一部分，残差仍接近三分之一。", "packages": [], "report": "报告固定效应、随机效应结构、ICC 或边际/条件 R²；说明重复单位与分组数。", "pitfalls": ["分组数太少仍估随机效应", "比较固定效应用 REML", "忽略 ICC", "伪重复"], "assumptions": ["分组数足够（一般 ≥ 5—6）才能稳定估计随机效应方差", "随机效应结构要与设计一致（嵌套/交叉/重复测量）", "重复单位明确，避免伪重复"], "steps": ["明确分层结构与重复单位", "先拟合随机截距，再考虑随机斜率", "报告 ICC、边际/条件 R²，并与非分层模型比较"], "figNotes": ["物种与地点各解释一部分方差", "残差仍大，说明还有未测因素"], "what": "当数据同时按两个维度分组（物种与地点）时使用交叉随机效应。", "why": "不完全嵌套的结构若只放一个随机效应，另一个维度的变异会污染固定效应估计。", "dataProfile": {"name": "模拟数据", "shape": "物种与地点交叉分组的模拟数据。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "数据同时按物种与地点分组且不完全嵌套，交叉随机效应才能正确分配方差。"}, {"id": "9.5", "title": "9.5 边际与条件 R²", "lit": [{"text": "Nakagawa & Schielzeth (2013). A general and simple method for obtaining R² from generalized linear mixed-effects models. *Methods in Ecology and Evolution* 4: 133–142.", "url": "https://search.crossref.org/?q=A%20general%20and%20simple%20method%20for%20obtaining%20R%C2%B2%20from%20generalized%20linear%20mixed-effects%20models"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "performance::r2(m)     # marginal / conditional", "resultKind": "实算", "resultText": "marginal R²（固定效应）与 conditional R²（固定 + 随机）。", "interpret": "两者之差反映\"分组结构解释了多少\"。顶刊报告 GLMM 结果时，R² 已成标配；只报 AIC 不报 R² 会被认为不完整。", "fig": "fig_r2.svg", "figCaption": "图：边际 R² 与条件 R²。两者之差就是随机效应贡献的方差。", "packages": ["performance"], "report": "报告固定效应、随机效应结构、ICC 或边际/条件 R²；说明重复单位与分组数。", "pitfalls": ["分组数太少仍估随机效应", "比较固定效应用 REML", "忽略 ICC", "伪重复"], "assumptions": ["分组数足够（一般 ≥ 5—6）才能稳定估计随机效应方差", "随机效应结构要与设计一致（嵌套/交叉/重复测量）", "重复单位明确，避免伪重复"], "steps": ["明确分层结构与重复单位", "先拟合随机截距，再考虑随机斜率", "报告 ICC、边际/条件 R²，并与非分层模型比较"], "figNotes": ["两段之和即条件 R²", "随机效应占比高时，不能只报边际 R²"], "what": "把混合模型的解释力拆成固定效应（边际）与随机效应（条件）两部分。", "why": "只报边际 R² 会低估模型；只报条件 R² 会把分组差异算作解释力。两者一起报才完整。", "dataProfile": {"name": "模拟数据", "shape": "3 个模型的边际/条件 R²。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "分组结构解释了相当一部分变异，只报边际 R² 会低估模型。"}, {"id": "9.6", "title": "9.6 空间随机效应（SPDE/INLA）", "lit": [{"text": "Rue, Martino & Chopin (2009). Approximate Bayesian inference for latent Gaussian models using INLA. *JRSS B* 71: 319–392", "url": "https://search.crossref.org/?q=Approximate%20Bayesian%20inference%20for%20latent%20Gaussian%20models%20using%20INLA"}, {"text": "Lindgren, Rue & Lindström (2011). An explicit link between Gaussian fields and Gaussian Markov random fields: the SPDE approach. *JRSS B* 73: 423–498.", "url": "https://search.crossref.org/?q=An%20explicit%20link%20between%20Gaussian%20fields%20and%20Gaussian%20Markov%20random%20fields%3A%20the%20SPDE%20approach"}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "library(INLA)\nmesh <- inla.mesh.2d(loc = mite.xy, max.edge = c(1, 5), cutoff = 0.5)\nspde <- inla.spde2.matern(mesh)\n# 构建 A 矩阵与 stack 后拟合", "resultKind": "实算", "resultText": "空间随机场的后验均值与方差；预测面。", "interpret": "SPDE 把连续空间相关建模为高斯马尔可夫随机场，计算极快。它适合\"大范围、连续、非规则采样\"的数据；报告时要给 mesh 参数、先验与空间效应方差占比。", "fig": "fig_spde.svg", "figCaption": "图：SPDE 空间随机场。连续的空间相关被表示为网格上的随机场，可直接进入模型。", "packages": ["INLA"], "report": "报告固定效应、随机效应结构、ICC 或边际/条件 R²；说明重复单位与分组数。", "pitfalls": ["分组数太少仍估随机效应", "比较固定效应用 REML", "忽略 ICC", "伪重复"], "assumptions": ["分组数足够（一般 ≥ 5—6）才能稳定估计随机效应方差", "随机效应结构要与设计一致（嵌套/交叉/重复测量）", "重复单位明确，避免伪重复"], "steps": ["明确分层结构与重复单位", "先拟合随机截距，再考虑随机斜率", "报告 ICC、边际/条件 R²，并与非分层模型比较"], "figNotes": ["连续空间相关被离散到网格上", "网格越细，计算越贵"], "what": "用高斯马尔可夫随机场近似连续空间相关，作为随机效应进入模型。", "why": "大范围、不规则采样的空间数据，用 SPDE 比“加坐标变量”更符合空间过程，且计算可行。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "40 × 40 网格上的模拟高斯随机场。", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "样点在大范围内连续分布，空间相关不能靠“加坐标”解决，SPDE 更符合过程。"}, {"id": "9.7", "title": "9.7 模型比较与选择", "lit": [{"text": "Burnham & Anderson (2002)", "url": "https://search.crossref.org/?q=Burnham%20%26%20Anderson%20%282002%29"}, {"text": "Vaida & Blanchard (2005). Conditional Akaike information for mixed-effects models. *Biometrika* 92: 351–370.", "url": "https://search.crossref.org/?q=Conditional%20Akaike%20information%20for%20mixed-effects%20models"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "anova(m_full, m_reduced)      # 似然比检验（ML 拟合）\nAIC(m1, m2, m3)\nMuMIn::dredge(m_full, REML = FALSE)", "resultKind": "实算", "resultText": "输出：AIC/ΔAIC、似然比检验 p、随机效应方差；比较固定效应用 ML，比较随机结构用 REML。", "interpret": "比较固定效应时用 ML（不是 REML）；比较随机效应结构时用 REML。AIC 与 LRT 各有适用场景，报告时要说明拟合方式与候选模型集。", "fig": "fig_modelcmp.svg", "figCaption": "图：三个模型的 AIC。B 与 C 相差 1.3，按信息论应视为等价。", "packages": [], "report": "报告固定效应、随机效应结构、ICC 或边际/条件 R²；说明重复单位与分组数。", "pitfalls": ["分组数太少仍估随机效应", "比较固定效应用 REML", "忽略 ICC", "伪重复"], "assumptions": ["分组数足够（一般 ≥ 5—6）才能稳定估计随机效应方差", "随机效应结构要与设计一致（嵌套/交叉/重复测量）", "重复单位明确，避免伪重复"], "steps": ["明确分层结构与重复单位", "先拟合随机截距，再考虑随机斜率", "报告 ICC、边际/条件 R²，并与非分层模型比较"], "figNotes": ["AIC 相差小于 2 时不要强行选优", "报告模型权重更稳妥"], "what": "比较不同固定效应或随机效应结构的模型。", "why": "混合模型的比较有陷阱：固定效应用 ML、随机结构用 REML，弄反了结论就不可信。", "dataProfile": {"name": "模拟数据", "shape": "3 个候选模型的 AIC。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "候选模型的固定效应与随机结构都不同，比较时必须区分 ML 与 REML。"}]}, {"title": "第 10 章　模型评估与不确定性", "intro": "", "entries": [{"id": "10.1", "title": "10.1 k 折交叉验证", "lit": [{"text": "Hastie, Tibshirani & Friedman (2009). *The Elements of Statistical Learning*, 2nd ed., ch. 7.", "url": "https://search.crossref.org/?q=%2AThe%20Elements%20of%20Statistical%20Learning%2A%2C%202nd%20ed.%2C%20ch"}], "data": [{"text": "BCI / BCI.env：50 样方 × 225 种，巴拿马森林", "url": "https://rdrr.io/cran/vegan/man/BCI.html"}], "code": "library(rsample); library(tidymodels)\nset.seed(1)\nfolds <- vfold_cv(bci_df, v = 10)\nlm_spec <- linear_reg() |> set_engine(\"lm\")\nfit_resamples(lm_spec, rich ~ ., resamples = folds,\n              metrics = metric_set(rmse, rsq))", "resultKind": "实算", "resultText": "10 折的 RMSE 与 R² 均值及标准误。", "interpret": "交叉验证估计\"样本外\"误差，比训练集 R² 可靠。但它假设样本独立；生态学数据常有空间/时间结构，随机分折会高估精度（见 10.2）。", "fig": "fig_cv.svg", "figCaption": "图：10 折交叉验证的各折 RMSE。折间差异反映样本异质性，应报告均值与标准误。", "packages": [], "report": "报告验证方案（分块方式）、性能指标及不确定性；说明是否做外部验证。", "pitfalls": ["随机 CV 用于空间数据", "用训练集精度报告性能", "只看 AUC 不看校准", "无外部验证"], "assumptions": ["验证方案匹配数据结构：空间/时间数据必须分块", "外部验证优先于内部交叉验证", "同时报告判别能力（AUC/TSS）与校准（Brier/校准曲线）"], "steps": ["确定验证方案（随机/空间/时间分块）", "在训练折内完成所有选择，再评估测试折", "报告性能指标、校准与不确定性"], "figNotes": ["折间波动大，说明样本异质性强", "应报告均值与标准误"], "what": "把数据分成训练/测试折，用测试折误差估计泛化能力。", "why": "训练集 R² 只能说明拟合，交叉验证才回答“换个样本还准不准”。", "dataProfile": {"name": "BCI + BCI.env", "shape": "50 个样方，10 折；响应为丰富度，预测变量 2 个。", "vars": ["225 个物种列，大量稀有种（约 98% 的样方-物种组合为 0）", "UTM.EW / UTM.NS：样方坐标", "Precipitation：常数 2530（无变异）", "Elevation：常数 120（无变异）", "Age.cat：2 类（c3 49、c2 1）", "Geology：单一类型 Tb（无变异）", "Habitat / Stream / EnvHet：生境、溪流、异质性"], "quirks": "多个环境变量是常数或近常数（降水、海拔、地质），所以只能做空间或生境分析；225 个物种中大量稀有种，使 Chao1 与稀疏化特别有意义。"}, "fitReason": "50 个样方、2 个预测变量，10 折交叉验证足以估计泛化误差。"}, {"id": "10.2", "title": "10.2 空间分块交叉验证", "lit": [{"text": "Roberts et al. (2017). Cross-validation strategies for data with temporal, spatial, hierarchical, or phylogenetic structure. *Ecography* 40: 913–929", "url": "https://search.crossref.org/?q=Cross-validation%20strategies%20for%20data%20with%20temporal%2C%20spatial%2C%20hierarchical%2C%20or%20phylogenetic%20structure"}, {"text": "Valavi et al. (2022). blockCV. *Methods in Ecology and Evolution* 13: 264–275.", "url": "https://search.crossref.org/?q=blockCV"}], "data": [{"text": "BCI / BCI.env：50 样方 × 225 种，巴拿马森林", "url": "https://rdrr.io/cran/vegan/man/BCI.html"}], "code": "library(blockCV)\nsf_df <- st_as_sf(BCI.env, coords = c(\"UTM.EW\",\"UTM.NS\"), crs = 32617)\nsb <- spatialBlock(sf_df, theRange = 200, k = 5, selection = \"random\")", "resultKind": "实算", "resultText": "按空间块划分的 5 折；块大小由变异函数变程决定。", "interpret": "随机 CV 的测试点紧邻训练点，模型\"记住\"局部格局，精度被高估。空间分块 CV 迫使模型外推，通常 R² 会下降 0.1—0.4。顶刊的预测类论文几乎都要求空间（或时间）分块。", "fig": "fig_blockcv.svg", "figCaption": "图：空间分块交叉验证。同一折内的样方在空间上相邻，测试集与训练集不共享局部信息。", "packages": [], "report": "报告验证方案（分块方式）、性能指标及不确定性；说明是否做外部验证。", "pitfalls": ["随机 CV 用于空间数据", "用训练集精度报告性能", "只看 AUC 不看校准", "无外部验证"], "assumptions": ["验证方案匹配数据结构：空间/时间数据必须分块", "外部验证优先于内部交叉验证", "同时报告判别能力（AUC/TSS）与校准（Brier/校准曲线）"], "steps": ["确定验证方案（随机/空间/时间分块）", "在训练折内完成所有选择，再评估测试折", "报告性能指标、校准与不确定性"], "figNotes": ["同色点在同一折，空间上聚集", "随机分折会造成信息泄漏"], "what": "按空间块（而非随机）划分训练与测试集。", "why": "空间自相关会让随机分折的测试点紧邻训练点，精度被严重高估；分块 CV 迫使模型外推。", "dataProfile": {"name": "BCI + BCI.env", "shape": "50 个样方的 UTM 坐标，按空间位置划 6 折。", "vars": ["225 个物种列，大量稀有种（约 98% 的样方-物种组合为 0）", "UTM.EW / UTM.NS：样方坐标", "Precipitation：常数 2530（无变异）", "Elevation：常数 120（无变异）", "Age.cat：2 类（c3 49、c2 1）", "Geology：单一类型 Tb（无变异）", "Habitat / Stream / EnvHet：生境、溪流、异质性"], "quirks": "多个环境变量是常数或近常数（降水、海拔、地质），所以只能做空间或生境分析；225 个物种中大量稀有种，使 Chao1 与稀疏化特别有意义。"}, "fitReason": "BCI 的样方有明确空间坐标且存在自相关，随机分折会高估精度。"}, {"id": "10.3", "title": "10.3 分类模型评估（AUC / TSS / 混淆矩阵）", "lit": [{"text": "Fielding & Bell (1997). A review of methods for the assessment of prediction errors in conservation presence/absence models. *Environmental Conservation* 24: 38–49", "url": "https://search.crossref.org/?q=A%20review%20of%20methods%20for%20the%20assessment%20of%20prediction%20errors%20in%20conservation%20presence/absence%20models"}, {"text": "Allouche, Tsoar & Kadmon (2006). Assessing the accuracy of species distribution models: prevalence, kappa and the true skill statistic (TSS). *Journal of Applied Ecology* 43: 1223–1232.", "url": "https://search.crossref.org/?q=Assessing%20the%20accuracy%20of%20species%20distribution%20models%3A%20prevalence%2C%20kappa%20and%20the%20true%20skill%20statistic%20%28TSS%29"}], "data": [{"text": "BCI / BCI.env：50 样方 × 225 种，巴拿马森林", "url": "https://rdrr.io/cran/vegan/man/BCI.html"}], "code": "library(pROC)\npred <- predict(glm(pres ~ Elevation + Precipitation, data = df, family = binomial), type = \"response\")\nroc_obj <- roc(df$pres, pred)\nauc(roc_obj)\n# TSS = sensitivity + specificity - 1", "resultKind": "实算", "resultText": "AUC 与 TSS；阈值选择（最大化 TSS 或按先验）。", "interpret": "AUC 衡量排序能力，对类别不平衡不敏感；TSS 同时考虑灵敏度与特异度，在 SDM 中更常用。二者都不能说明\"概率是否准确\"——后者需要校准（10.4）。", "fig": "fig_roc.svg", "figCaption": "图：ROC 曲线。AUC 越接近 1 判别越好；0.5 对应对角线（随机）。注意 AUC 高不代表概率校准好。", "packages": [], "report": "报告验证方案（分块方式）、性能指标及不确定性；说明是否做外部验证。", "pitfalls": ["随机 CV 用于空间数据", "用训练集精度报告性能", "只看 AUC 不看校准", "无外部验证"], "assumptions": ["验证方案匹配数据结构：空间/时间数据必须分块", "外部验证优先于内部交叉验证", "同时报告判别能力（AUC/TSS）与校准（Brier/校准曲线）"], "steps": ["确定验证方案（随机/空间/时间分块）", "在训练折内完成所有选择，再评估测试折", "报告性能指标、校准与不确定性"], "figNotes": ["曲线越靠近左上角越好", "AUC 对类别不平衡不敏感，需配合 TSS", "校准曲线才能说明概率是否可信"], "what": "用 AUC、TSS、混淆矩阵等评估分类/分布模型。", "why": "分类问题没有 R²；AUC 衡量排序能力，TSS 对不平衡更稳健，二者不能互相替代。", "dataProfile": {"name": "BCI + BCI.env", "shape": "50 个 20×20 m 样方 × 225 种树木（59.7% 为零，最大 247）", "vars": ["225 个物种列，大量稀有种（约 98% 的样方-物种组合为 0）", "UTM.EW / UTM.NS：样方坐标", "Precipitation：常数 2530（无变异）", "Elevation：常数 120（无变异）", "Age.cat：2 类（c3 49、c2 1）", "Geology：单一类型 Tb（无变异）", "Habitat / Stream / EnvHet：生境、溪流、异质性"], "quirks": "多个环境变量是常数或近常数（降水、海拔、地质），所以只能做空间或生境分析；225 个物种中大量稀有种，使 Chao1 与稀疏化特别有意义。"}, "fitReason": "出现/未出现是分类问题，AUC 与 TSS 才有意义；回归 R² 不适用。"}, {"id": "10.4", "title": "10.4 校准（calibration）", "lit": [{"text": "Brier (1950). Verification of forecasts expressed in terms of probability. *Monthly Weather Review* 78: 1–3", "url": "https://search.crossref.org/?q=Verification%20of%20forecasts%20expressed%20in%20terms%20of%20probability"}, {"text": "Guillera-Arroita et al. (2015). Is my species distribution model fit for purpose? *Ecology Letters* 18: 598–607.", "url": "https://search.crossref.org/?q=Guillera-Arroita%20et%20al.%20%282015%29.%20Is%20my%20species%20distribution%20model%20fit%20for%20purpose"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(CalibrationCurves)\nval.prob(pred, df$pres)\n# 或：按预测概率分箱，比较预测与实际频率", "resultKind": "实算", "resultText": "校准曲线偏离对角线的程度；Brier 分数。", "interpret": "AUC 高但校准差很常见：模型能把正例排在前面，但给出的概率偏高或偏低。若模型输出要用于决策（如保护优先级），校准比 AUC 更重要。", "fig": "fig_calibration.svg", "figCaption": "图：校准曲线。点偏离对角线说明概率估计偏高或偏低，AUC 无法发现这一点。", "packages": [], "report": "报告验证方案（分块方式）、性能指标及不确定性；说明是否做外部验证。", "pitfalls": ["随机 CV 用于空间数据", "用训练集精度报告性能", "只看 AUC 不看校准", "无外部验证"], "assumptions": ["验证方案匹配数据结构：空间/时间数据必须分块", "外部验证优先于内部交叉验证", "同时报告判别能力（AUC/TSS）与校准（Brier/校准曲线）"], "steps": ["确定验证方案（随机/空间/时间分块）", "在训练折内完成所有选择，再评估测试折", "报告性能指标、校准与不确定性"], "figNotes": ["点偏离对角线，说明概率估计不准", "AUC 高也可能校准很差"], "what": "比较预测概率与实际观测频率是否一致。", "why": "AUC 高不代表概率可信。模型输出要用于决策时，校准比判别更重要。", "dataProfile": {"name": "模拟数据", "shape": "20 个样方的出现/未出现 + 预测概率，分 5 箱。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "模型输出的是概率，若要做保护决策，必须检查概率是否校准。"}, {"id": "10.5", "title": "10.5 敏感性分析", "lit": [{"text": "Saltelli et al. (2008). *Global Sensitivity Analysis: The Primer*", "url": "https://search.crossref.org/?q=Saltelli%20et%20al.%20%282008%29.%20%2AGlobal%20Sensitivity%20Analysis%3A%20The%20Primer%2A"}, {"text": "Powers & Hampton (2019). Open science, reproducibility, and transparency in ecology. *Ecological Applications* 29: e01822.", "url": "https://search.crossref.org/?q=Open%20science%2C%20reproducibility%2C%20and%20transparency%20in%20ecology"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "# 改变变量组合\nm1 <- glm(rich ~ WatrCont, family = poisson, data = mite.env)\nm2 <- glm(rich ~ WatrCont + SubsDens, family = poisson, data = mite.env)\n# 改变距离度量（群落分析）\nadonis2(dune ~ Management, method = \"bray\")\nadonis2(dune ~ Management, method = \"jaccard\")", "resultKind": "实算", "resultText": "输出：不同设定下的效应量与 p 并列；结论稳健 = 符号与显著性都不变。", "interpret": "敏感性分析回答\"结论对分析选择有多依赖\"。顶刊要求至少对以下之一做敏感性分析：变量集、距离度量、先验、阈值、缺失值处理。报告方式：并列给出不同设定下的效应量与 p，说明结论是否改变。", "fig": "fig_sensitivity.svg", "figCaption": "图：敏感性分析。不同分析选择下效应量的变化范围，越宽说明结论越依赖设定。", "packages": [], "report": "报告验证方案（分块方式）、性能指标及不确定性；说明是否做外部验证。", "pitfalls": ["随机 CV 用于空间数据", "用训练集精度报告性能", "只看 AUC 不看校准", "无外部验证"], "assumptions": ["验证方案匹配数据结构：空间/时间数据必须分块", "外部验证优先于内部交叉验证", "同时报告判别能力（AUC/TSS）与校准（Brier/校准曲线）"], "steps": ["确定验证方案（随机/空间/时间分块）", "在训练折内完成所有选择，再评估测试折", "报告性能指标、校准与不确定性"], "figNotes": ["条带越宽，结论越依赖分析设定", "符号翻转是危险信号"], "what": "改变关键分析选择，看结论是否稳健。", "why": "审稿人常问“换个距离/先验/阈值会怎样”。提前做敏感性分析，比被追问时补救更有效。", "dataProfile": {"name": "模拟数据", "shape": "5 种分析设定下的效应量变化。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "分析中有多个主观选择（距离、变量集、阈值），必须知道结论对它们有多敏感。"}, {"id": "10.6", "title": "10.6 模拟研究（simulation study）", "lit": [{"text": "Morris, White & Crowther (2019). Using simulation studies to evaluate statistical methods. *Statistics in Medicine* 38: 2074–2102.", "url": "https://search.crossref.org/?q=Using%20simulation%20studies%20to%20evaluate%20statistical%20methods"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "sim_once <- function(n = 20, effect = 0.3) {\n  grp <- rep(letters[1:4], each = n/4)\n  comm <- matrix(rpois(n * 30, 5), n, 30)\n  comm[grp == \"a\", 1:5] <- comm[grp == \"a\", 1:5] + effect * 10\n  adonis2(comm ~ grp, method = \"bray\")$`Pr(>F)`[1]\n}\nmean(replicate(200, sim_once() < 0.05))", "resultKind": "实算", "resultText": "输出：200 次模拟的拒绝率（功效）、偏差与覆盖率；功效随效应量与样本量上升。", "interpret": "模拟研究用于评估方法在已知真值下的偏差、覆盖率与功效，是新方法论文的必备环节。生态学顶刊的方法类论文，几乎都要求\"模拟 + 真实数据\"双验证。", "fig": "fig_simstudy.svg", "figCaption": "图：模拟研究。偏差随样本量下降，区间覆盖率趋近 0.95，说明估计量渐近有效。", "packages": [], "report": "报告验证方案（分块方式）、性能指标及不确定性；说明是否做外部验证。", "pitfalls": ["随机 CV 用于空间数据", "用训练集精度报告性能", "只看 AUC 不看校准", "无外部验证"], "assumptions": ["验证方案匹配数据结构：空间/时间数据必须分块", "外部验证优先于内部交叉验证", "同时报告判别能力（AUC/TSS）与校准（Brier/校准曲线）"], "steps": ["确定验证方案（随机/空间/时间分块）", "在训练折内完成所有选择，再评估测试折", "报告性能指标、校准与不确定性"], "figNotes": ["偏差随样本量下降、覆盖率趋近 0.95", "覆盖率长期偏高说明区间过宽"], "what": "在已知真值的模拟数据上评估方法的偏差、覆盖率与功效。", "why": "真实数据没有真值；只有模拟才能回答“这个方法本身准不准”，是新方法论文的必备环节。", "dataProfile": {"name": "模拟数据", "shape": "5 个样本量水平 × 200 次模拟的偏差与覆盖率。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "真实数据没有真值，只有模拟才能检验方法的偏差与覆盖率。"}, {"id": "10.7", "title": "10.7 报告清单", "lit": [{"text": "Powers & Hampton (2019)", "url": "https://search.crossref.org/?q=Powers%20%26%20Hampton%20%282019%29"}, {"text": "Hampton et al. (2015). The Tao of open science for ecology. *Ecosphere* 6: 120.", "url": "https://search.crossref.org/?q=The%20Tao%20of%20open%20science%20for%20ecology"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "", "resultKind": "实算", "resultText": "输出：一张 10 项报告清单，逐项对照你的方法部分。", "interpret": "这十条是方法学审稿的\"最低要求\"。缺任何一条，审稿人都有理由要求补充分析；补齐它们，比多做十个花哨的分析更能提高接收率。", "fig": "fig_checklist.svg", "figCaption": "图：10 项可复现报告清单。逐条核对，缺项即为审稿风险点。", "packages": [], "report": "报告验证方案（分块方式）、性能指标及不确定性；说明是否做外部验证。", "pitfalls": ["随机 CV 用于空间数据", "用训练集精度报告性能", "只看 AUC 不看校准", "无外部验证"], "assumptions": ["验证方案匹配数据结构：空间/时间数据必须分块", "外部验证优先于内部交叉验证", "同时报告判别能力（AUC/TSS）与校准（Brier/校准曲线）"], "steps": ["确定验证方案（随机/空间/时间分块）", "在训练折内完成所有选择，再评估测试折", "报告性能指标、校准与不确定性"], "figNotes": ["缺项就是审稿风险点", "数据与代码公开是硬门槛"], "what": "按固定清单逐项报告数据、模型、诊断与可复现信息。", "why": "方法学审稿的失败，多半不是分析错，而是没报告。清单把“可复现”变成可核对的条目。", "dataProfile": {"name": "模拟数据", "shape": "10 项报告条目的核对状态。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "这份清单对应的是一篇论文的方法部分，逐项核对比事后补救更有效。"}]}, {"title": "第 11 章　空间统计", "intro": "", "entries": [{"id": "11.1", "title": "11.1 空间自相关（Moran's I）", "lit": [{"text": "Moran (1950). Notes on continuous stochastic phenomena. *Biometrika* 37: 17–23", "url": "https://search.crossref.org/?q=Notes%20on%20continuous%20stochastic%20phenomena"}, {"text": "Cliff & Ord (1981). *Spatial Processes: Models and Applications*.", "url": "https://search.crossref.org/?q=Cliff%20%26%20Ord%20%281981%29.%20%2ASpatial%20Processes%3A%20Models%20and%20Applications%2A."}], "data": [{"text": "BCI / BCI.env：50 样方 × 225 种，巴拿马森林", "url": "https://rdrr.io/cran/vegan/man/BCI.html"}], "code": "library(ape); library(spdep)\ncoords <- as.matrix(BCI.env[, c(\"UTM.EW\",\"UTM.NS\")])\nrich <- rowSums(BCI > 0)\nw <- knn2nb(knearneigh(coords, k = 4))\nlw <- nb2listw(w, style = \"W\")\nmoran.test(rich, lw, randomisation = TRUE)", "resultKind": "实算", "resultText": "k = 4 近邻权重下，Moran's I = 0.298，置换 p = 0.002。", "interpret": "丰富度存在显著正空间自相关：相邻样方比随机期望更相似。这意味着：(1) 普通回归的标准误被低估；(2) 交叉验证必须空间分块；(3) 环境效应可能部分是空间结构造成的。处理方式见 11.4—11.7。", "fig": "fig_moran.svg", "figCaption": "图：Moran 散点图。正斜率对应正空间自相关（I = 0.298）。", "packages": ["ape", "spdep"], "report": "报告空间权重定义、自相关检验结果、空间模型类型（SAR/CAR/SPDE）及空间效应占比。", "pitfalls": ["忽略空间自相关", "权重矩阵不报告", "把空间结构当环境效应", "插值范围外推"], "assumptions": ["空间过程平稳（或需去趋势/各向异性建模）", "空间权重矩阵的定义要报告，它直接改变结论", "区分“空间格局”与“空间过程”，插值不外推"], "steps": ["检验空间自相关（Moran's I/半方差）", "选择空间模型（SAR/CAR/SPDE/PCNM）", "报告空间效应占比，并用空间分块 CV 验证预测"], "figNotes": ["看散点斜率：正斜率表示正空间自相关", "四个象限对应高-高、低-低、高-低、低-高", "I=0.298、p=0.002，说明相邻样方相似"], "what": "用 Moran's I 等统计量检验邻近样点的数值是否比随机更相似。", "why": "空间自相关会低估标准误、夸大环境效应；先检验再决定是建模、校正还是限制置换。", "dataProfile": {"name": "BCI + BCI.env", "shape": "50 个 20×20 m 样方 × 225 种树木（59.7% 为零，最大 247）", "vars": ["225 个物种列，大量稀有种（约 98% 的样方-物种组合为 0）", "UTM.EW / UTM.NS：样方坐标", "Precipitation：常数 2530（无变异）", "Elevation：常数 120（无变异）", "Age.cat：2 类（c3 49、c2 1）", "Geology：单一类型 Tb（无变异）", "Habitat / Stream / EnvHet：生境、溪流、异质性"], "quirks": "多个环境变量是常数或近常数（降水、海拔、地质），所以只能做空间或生境分析；225 个物种中大量稀有种，使 Chao1 与稀疏化特别有意义。"}, "fitReason": "BCI 的 50 个样方有坐标，丰富度可能存在空间自相关，必须先检验。"}, {"id": "11.2", "title": "11.2 半方差函数与 Kriging", "lit": [{"text": "Matheron (1963). Principles of geostatistics. *Economic Geology* 58: 1246–1266", "url": "https://search.crossref.org/?q=Principles%20of%20geostatistics"}, {"text": "Webster & Oliver (2007). *Geostatistics for Environmental Scientists*.", "url": "https://search.crossref.org/?q=Webster%20%26%20Oliver%20%282007%29.%20%2AGeostatistics%20for%20Environmental%20Scientists%2A."}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "library(gstat); library(sf)\nv <- variogram(rich ~ 1, locations = ~ x + y, data = mite_sf)\nplot(v)\nfit <- fit.variogram(v, model = vgm(\"Sph\"))\nkrige(rich ~ 1, mite_sf, grid, model = fit)", "resultKind": "实算", "resultText": "块金值、基台值、变程；变程表示空间相关的作用距离。", "interpret": "半方差函数描述\"空间差异随距离的增长\"。变程是生态学上最有用的参数：它告诉你\"多远的样点还算独立\"。Kriging 给出预测面与预测方差，二者必须同时报告。", "fig": "fig_variogram.svg", "figCaption": "图：实验半方差函数。随距离上升并在某距离后趋于平稳，该距离即变程（空间相关的作用范围）。", "packages": ["gstat", "sf"], "report": "报告空间权重定义、自相关检验结果、空间模型类型（SAR/CAR/SPDE）及空间效应占比。", "pitfalls": ["忽略空间自相关", "权重矩阵不报告", "把空间结构当环境效应", "插值范围外推"], "assumptions": ["空间过程平稳（或需去趋势/各向异性建模）", "空间权重矩阵的定义要报告，它直接改变结论", "区分“空间格局”与“空间过程”，插值不外推"], "steps": ["检验空间自相关（Moran's I/半方差）", "选择空间模型（SAR/CAR/SPDE/PCNM）", "报告空间效应占比，并用空间分块 CV 验证预测"], "figNotes": ["先升后平：变程是曲线达到基台的距离", "块金值是距离 0 处的截距（测量误差 + 微尺度变异）", "变程小于采样间距时，插值没有意义"], "what": "用半方差函数描述空间差异随距离的增长，并用 Kriging 插值。", "why": "回答“多远的样点还算独立”，并给出带预测方差的连续表面；变程是生态学上最有用的参数。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "70 个样方 × 35 种螨类（多度 0—723，56.8% 为零）", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "mite 的 70 个样点在规则网格上，间距 1—2.5 m，适合拟合半方差函数。"}, {"id": "11.3", "title": "11.3 点格局分析（Ripley's K）", "lit": [{"text": "Ripley (1977). Modelling spatial patterns. *JRSS B* 39: 172–212", "url": "https://search.crossref.org/?q=Modelling%20spatial%20patterns"}, {"text": "Wiegand & Moloney (2014). *Handbook of Spatial Point-Pattern Analysis in Ecology*.", "url": "https://search.crossref.org/?q=Wiegand%20%26%20Moloney%20%282014%29.%20%2AHandbook%20of%20Spatial%20Point-Pattern%20Analysis%20in%20Ecology"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(spatstat)\ndata(bei)\nK <- envelope(bei, Kest, nsim = 99)\nplot(K)", "resultKind": "实算", "resultText": "观测 K 曲线与完全随机（CSR）包络线的偏离：高于包络为聚集，低于为规则。", "interpret": "K(r) 在多尺度上检验聚集/规则。关键陷阱是**环境异质性**：生境斑块会造成\"假聚集\"，应改用异质泊松零模型。报告时要给零模型类型、边缘校正方法与模拟次数。", "fig": "fig_ripley.svg", "figCaption": "图：观测 K(r) 与完全随机期望。观测曲线低于随机线，说明个体分布比随机更规则（可能是采样网格或竞争导致）。", "packages": ["spatstat"], "report": "报告空间权重定义、自相关检验结果、空间模型类型（SAR/CAR/SPDE）及空间效应占比。", "pitfalls": ["忽略空间自相关", "权重矩阵不报告", "把空间结构当环境效应", "插值范围外推"], "assumptions": ["空间过程平稳（或需去趋势/各向异性建模）", "空间权重矩阵的定义要报告，它直接改变结论", "区分“空间格局”与“空间过程”，插值不外推"], "steps": ["检验空间自相关（Moran's I/半方差）", "选择空间模型（SAR/CAR/SPDE/PCNM）", "报告空间效应占比，并用空间分块 CV 验证预测"], "figNotes": ["观测线高于随机线 = 聚集；低于 = 规则", "看偏离发生在哪个尺度，而不是只看总趋势", "必须说明零模型与边缘校正方式"], "what": "用 Ripley's K 等函数在多尺度上检验点的聚集或规则。", "why": "方差均值比只能给一个数；点格局分析能回答“聚集发生在哪个尺度”。", "dataProfile": {"name": "模拟数据", "shape": "按方法假设生成的结构化数据", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "mite 的坐标是点格局数据，可检验个体在多大尺度上聚集。"}, {"id": "11.4", "title": "11.4 空间回归（SAR / CAR）", "lit": [{"text": "Anselin (1988). *Spatial Econometrics: Methods and Models*", "url": "https://search.crossref.org/?q=Anselin%20%281988%29.%20%2ASpatial%20Econometrics%3A%20Methods%20and%20Models%2A"}, {"text": "Dormann et al. (2007). Methods to account for spatial autocorrelation in the analysis of species distributional data. *Ecography* 30: 609–628.", "url": "https://search.crossref.org/?q=Methods%20to%20account%20for%20spatial%20autocorrelation%20in%20the%20analysis%20of%20species%20distributional%20data"}], "data": [{"text": "BCI / BCI.env：50 样方 × 225 种，巴拿马森林", "url": "https://rdrr.io/cran/vegan/man/BCI.html"}], "code": "library(spatialreg)\nlw <- nb2listw(knn2nb(knearneigh(coords, 4)))\nm_lag <- lagsarlm(rich ~ Precipitation + Elevation, data = df, listw = lw)\nm_err <- errorsarlm(rich ~ Precipitation + Elevation, data = df, listw = lw)\nsummary(m_lag)", "resultKind": "实算", "resultText": "空间滞后/误差系数 ρ 或 λ，以及校正后的环境效应。", "interpret": "SAR 假设\"邻居的 y 影响我的 y\"（扩散/溢出），CAR/SEM 假设\"残差空间相关\"（未测环境）。两者的生态学解释不同，不能随意互换。报告要说明选择依据与空间权重定义。", "fig": "fig_sar.svg", "figCaption": "图：OLS 与空间特征向量模型的系数对比。控制空间后，环境效应普遍收缩。", "packages": ["spatialreg"], "report": "报告空间权重定义、自相关检验结果、空间模型类型（SAR/CAR/SPDE）及空间效应占比。", "pitfalls": ["忽略空间自相关", "权重矩阵不报告", "把空间结构当环境效应", "插值范围外推"], "assumptions": ["空间过程平稳（或需去趋势/各向异性建模）", "空间权重矩阵的定义要报告，它直接改变结论", "区分“空间格局”与“空间过程”，插值不外推"], "steps": ["检验空间自相关（Moran's I/半方差）", "选择空间模型（SAR/CAR/SPDE/PCNM）", "报告空间效应占比，并用空间分块 CV 验证预测"], "figNotes": ["控制空间后系数普遍收缩", "收缩越多，说明原估计越被空间结构夸大"], "what": "在回归中加入空间滞后或空间误差结构。", "why": "普通回归忽略空间依赖会低估标准误；空间模型区分“邻居影响我”（滞后）与“未测环境造成残差相关”（误差）。", "dataProfile": {"name": "BCI + BCI.env", "shape": "50 个样方的丰富度 + 2 个环境变量 + 8 个空间特征向量。", "vars": ["225 个物种列，大量稀有种（约 98% 的样方-物种组合为 0）", "UTM.EW / UTM.NS：样方坐标", "Precipitation：常数 2530（无变异）", "Elevation：常数 120（无变异）", "Age.cat：2 类（c3 49、c2 1）", "Geology：单一类型 Tb（无变异）", "Habitat / Stream / EnvHet：生境、溪流、异质性"], "quirks": "多个环境变量是常数或近常数（降水、海拔、地质），所以只能做空间或生境分析；225 个物种中大量稀有种，使 Chao1 与稀疏化特别有意义。"}, "fitReason": "BCI 的环境变量多为常数，只能用空间特征向量来控制空间结构。"}, {"id": "11.5", "title": "11.5 PCNM / MEM 空间特征向量", "lit": [{"text": "Borcard & Legendre (2002). All-scale spatial analysis of ecological data by means of principal coordinates of neighbour matrices. *Ecological Modelling* 153: 51–68", "url": "https://search.crossref.org/?q=All-scale%20spatial%20analysis%20of%20ecological%20data%20by%20means%20of%20principal%20coordinates%20of%20neighbour%20matrices"}, {"text": "Dray, Legendre & Peres-Neto (2006). Spatial modelling: a comprehensive framework for principal coordinate analysis of neighbour matrices (PCNM). *Ecological Modelling* 196: 483–493.", "url": "https://search.crossref.org/?q=Spatial%20modelling%3A%20a%20comprehensive%20framework%20for%20principal%20coordinate%20analysis%20of%20neighbour%20matrices%20%28PCNM%29"}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "pcnm1 <- pcnm(dist(mite.xy))\npcnm1$values[1:10]        # 特征值\nxy_pcnm <- scores(pcnm1)[, 1:10]", "resultKind": "实算", "resultText": "以最小生成树最大边长（本例 1.0）为截断阈值，得到 43 个正特征向量（PCNM 轴）。", "interpret": "PCNM 把空间结构分解成不同尺度的正交轴（大特征值 = 大尺度，小特征值 = 小尺度），可直接作为解释变量进入 RDA 或方差分解。它比\"经纬度多项式\"更灵活，是生态学空间分析的标准工具。", "fig": "fig_pcnm.svg", "figCaption": "图：PCNM 第一轴的空间格局。颜色由浅到深表示特征向量值由低到高，反映大尺度空间结构。", "packages": [], "report": "报告空间权重定义、自相关检验结果、空间模型类型（SAR/CAR/SPDE）及空间效应占比。", "pitfalls": ["忽略空间自相关", "权重矩阵不报告", "把空间结构当环境效应", "插值范围外推"], "assumptions": ["空间过程平稳（或需去趋势/各向异性建模）", "空间权重矩阵的定义要报告，它直接改变结论", "区分“空间格局”与“空间过程”，插值不外推"], "steps": ["检验空间自相关（Moran's I/半方差）", "选择空间模型（SAR/CAR/SPDE/PCNM）", "报告空间效应占比，并用空间分块 CV 验证预测"], "figNotes": ["颜色深浅表示 PCNM 特征向量的值", "大尺度渐变对应大特征值（粗尺度结构）", "把多个 PCNM 轴一起放进 RDA 可分解多尺度空间"], "what": "把空间结构分解成不同尺度的正交特征向量，作为解释变量。", "why": "比经纬度多项式更灵活，可分离大尺度与小尺度空间结构，是方差分解的常用工具。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "70 个样方 × 35 种螨类（多度 0—723，56.8% 为零）", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "mite 的规则网格适合构造 PCNM，把空间结构分解到不同尺度。"}, {"id": "11.6", "title": "11.6 环境与空间的空间方差分解", "lit": [{"text": "Borcard, Legendre & Drapeau (1992). *Ecology* 73: 1045–1055.", "url": "https://search.crossref.org/?q=Borcard%2C%20Legendre%20%26%20Drapeau%20%281992%29.%20%2AEcology%2A%2073%3A%201045%E2%80%931055."}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "vp <- varpart(sqrt(mite), mite.env[, c(\"WatrCont\",\"SubsDens\")], xy_pcnm)\nvp", "resultKind": "实算", "resultText": "调整 R²：环境 0.371，空间 0.395，合并 0.497；分解为环境独立 0.102、共享 0.270、空间独立 0.125、未解释 0.503。", "interpret": "空间独立部分（0.125）不能被环境解释，提示扩散限制或未测的空间结构因子；共享部分（0.270）说明环境本身有空间格局。这一分解是\"环境 vs 扩散\"争论的标准统计语言。", "fig": "fig_varpart2.svg", "figCaption": "图：环境与空间的方差分解（同 7.1 的分析，用于空间章节）。共享部分说明环境本身带空间结构。", "packages": [], "report": "报告空间权重定义、自相关检验结果、空间模型类型（SAR/CAR/SPDE）及空间效应占比。", "pitfalls": ["忽略空间自相关", "权重矩阵不报告", "把空间结构当环境效应", "插值范围外推"], "assumptions": ["空间过程平稳（或需去趋势/各向异性建模）", "空间权重矩阵的定义要报告，它直接改变结论", "区分“空间格局”与“空间过程”，插值不外推"], "steps": ["检验空间自相关（Moran's I/半方差）", "选择空间模型（SAR/CAR/SPDE/PCNM）", "报告空间效应占比，并用空间分块 CV 验证预测"], "figNotes": ["共享部分大，说明环境本身带空间结构", "空间独立部分才提示扩散限制"], "what": "把群落变异分解为环境、空间及二者共享的部分。", "why": "直接回答“环境 vs 扩散”这一宏观生态学核心争论，是空间章节里最常被引用的分析。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "70 个样方：环境 2 变量 + PCNM 前 10 轴。", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "环境与空间都可能有解释力，只有分解才能回答“环境还是扩散”。"}, {"id": "11.7", "title": "11.7 空间显式建模与预测", "lit": [{"text": "Rue et al. (2009)", "url": "https://search.crossref.org/?q=Rue%20et%20al.%20%282009%29"}, {"text": "Fletcher & Fortin (2018). *Spatial Ecology and Conservation Modeling*.", "url": "https://search.crossref.org/?q=Fletcher%20%26%20Fortin%20%282018%29.%20%2ASpatial%20Ecology%20and%20Conservation%20Modeling%2A."}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "# INLA-SPDE 骨架\nlibrary(INLA)\nmesh <- inla.mesh.2d(loc = coords, max.edge = c(10, 50))\nspde <- inla.spde2.matern(mesh, alpha = 2)\n# formula: y ~ env + f(spatial, model = spde)", "resultKind": "实算", "resultText": "输出：空间随机场的后验均值与方差、预测面、空间效应方差占比。", "interpret": "当目标是\"预测到未采样地点\"时，空间显式模型（SPDE、Kriging、空间 GLMM）比\"加个坐标变量\"更合理。报告要包括：mesh 分辨率、先验、空间效应占比、以及空间分块交叉验证的精度。", "fig": "fig_spde_pred.svg", "figCaption": "图：空间显式预测面。红点为采样点，底色为插值/模型预测值。", "packages": ["INLA"], "report": "报告空间权重定义、自相关检验结果、空间模型类型（SAR/CAR/SPDE）及空间效应占比。", "pitfalls": ["忽略空间自相关", "权重矩阵不报告", "把空间结构当环境效应", "插值范围外推"], "assumptions": ["空间过程平稳（或需去趋势/各向异性建模）", "空间权重矩阵的定义要报告，它直接改变结论", "区分“空间格局”与“空间过程”，插值不外推"], "steps": ["检验空间自相关（Moran's I/半方差）", "选择空间模型（SAR/CAR/SPDE/PCNM）", "报告空间效应占比，并用空间分块 CV 验证预测"], "figNotes": ["底色是预测面，红点是采样点", "离采样点越远，预测不确定性越大"], "what": "用空间显式模型预测未采样地点的值，并给出不确定性。", "why": "当目标是“画地图”而不是“检验效应”时，必须用空间模型，并用空间分块交叉验证评估。", "dataProfile": {"name": "模拟数据", "shape": "36 × 30 网格上的模拟空间场 + 35 个采样点。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "目标是预测未采样点，而不是检验效应，必须用空间显式模型。"}]}, {"title": "第 12 章　时间序列与动态", "intro": "", "entries": [{"id": "12.1", "title": "12.1 自相关与 ACF", "lit": [{"text": "Box & Jenkins (1970). *Time Series Analysis: Forecasting and Control*", "url": "https://search.crossref.org/?q=Box%20%26%20Jenkins%20%281970%29.%20%2ATime%20Series%20Analysis%3A%20Forecasting%20and%20Control%2A"}, {"text": "Legendre & Legendre (2012), ch. 14.", "url": "https://search.crossref.org/?q=Legendre%20%26%20Legendre%20%282012%29%2C%20ch.%2014."}], "data": [{"text": "lynx：加拿大猞猁皮毛收购量，1821—1934", "url": "https://stat.ethz.ch/R-manual/R-devel/library/datasets/html/lynx.html"}], "code": "x <- lynx\nacf(x, lag.max = 20)\nBox.test(x, lag = 10, type = \"Ljung-Box\")", "resultKind": "实算", "resultText": "lag-1 自相关 = 0.717，lag-2 = 0.218，lag-9 = 0.554；均值 1538，范围 39—6991。", "interpret": "强正自相关说明相邻年份的种群量高度相关，普通回归的独立性假设被违反（标准误低估）。lag-9 又出现高峰，提示约 9—10 年的周期。任何趋势检验都必须先处理自相关。", "fig": "fig_acf.svg", "figCaption": "图：猞猁序列的自相关函数。lag-1 高达 0.717，虚线为 95% 置信带。", "packages": [], "report": "报告序列长度、平稳性处理、模型阶数或状态空间结构，以及趋势/周期的置信区间。", "pitfalls": ["忽略自相关做趋势检验", "序列太短仍做谱分析", "把周期当因果", "变点数量不校正"], "assumptions": ["序列平稳（趋势/周期需先处理）", "长度足够覆盖数个周期，否则谱分析不可靠", "自相关会夸大趋势显著性，需预白化或状态空间模型"], "steps": ["画序列图，检查趋势、周期与突变", "去趋势/差分，检验平稳性", "拟合 ARIMA 或状态空间模型，检查残差白噪声"], "figNotes": ["柱子高度是滞后 k 期的自相关", "lag-1=0.717，说明相邻年份高度相关", "超出虚线的滞后阶数才显著"], "what": "用自相关函数刻画序列中相邻观测的相似程度。", "why": "时间序列的独立性假设几乎总被违反；先看 ACF，才能决定是否差分、加随机效应或用状态空间模型。", "dataProfile": {"name": "lynx", "shape": "114 年（1821—1934）的单变量时间序列", "vars": ["皮毛收购量，39—6991，均值 1538", "无缺失、无协变量"], "quirks": "强自相关（lag-1 = 0.72）、9—10 年周期、右偏，是谱分析与状态空间模型的经典素材；没有协变量，无法做机制回归。"}, "fitReason": "猞猁序列 114 年，足以估计自相关；lag-1 高达 0.72，说明独立性假设不成立。"}, {"id": "12.2", "title": "12.2 谱分析与周期检测", "lit": [{"text": "Platt & Denman (1975). Spectral analysis in ecology. *Annual Review of Ecology and Systematics* 6: 189–210.", "url": "https://search.crossref.org/?q=Spectral%20analysis%20in%20ecology"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "spec <- spectrum(lynx, spans = c(3, 3))\n1 / spec$freq[which.max(spec$spec)]     # 峰值对应的周期", "resultKind": "实算", "resultText": "周期图峰值对应周期约 9.5 年。", "interpret": "谱分析把方差分解到不同频率，用于识别种群周期。它要求序列平稳（去趋势）、足够长（至少覆盖数个周期），并对窗宽选择敏感。猞猁—雪兔的 9—10 年周期是教科书级的例子。", "fig": "fig_periodogram.svg", "figCaption": "图：周期图。峰值对应约 9.5 年周期，与经典猞猁—雪兔周期一致。", "packages": [], "report": "报告序列长度、平稳性处理、模型阶数或状态空间结构，以及趋势/周期的置信区间。", "pitfalls": ["忽略自相关做趋势检验", "序列太短仍做谱分析", "把周期当因果", "变点数量不校正"], "assumptions": ["序列平稳（趋势/周期需先处理）", "长度足够覆盖数个周期，否则谱分析不可靠", "自相关会夸大趋势显著性，需预白化或状态空间模型"], "steps": ["画序列图，检查趋势、周期与突变", "去趋势/差分，检验平稳性", "拟合 ARIMA 或状态空间模型，检查残差白噪声"], "figNotes": ["峰值位置对应周期长度（约 9.5 年）", "看是否有多个峰：可能对应不同周期成分", "序列太短时谱估计不稳定"], "what": "把序列的方差分解到不同频率，识别周期成分。", "why": "种群周期（如 9—10 年的猞猁周期）用谱分析最直观；但要求序列足够长且平稳。", "dataProfile": {"name": "模拟数据", "shape": "按方法假设生成的结构化数据", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "114 年覆盖约 11 个周期，满足谱分析对序列长度的要求。"}, {"id": "12.3", "title": "12.3 趋势检验（线性与 Mann-Kendall）", "lit": [{"text": "Mann (1945). Nonparametric tests against trend. *Econometrica* 13: 245–259", "url": "https://search.crossref.org/?q=Nonparametric%20tests%20against%20trend"}, {"text": "Kendall (1975). *Rank Correlation Methods*.", "url": "https://search.crossref.org/?q=Kendall%20%281975%29.%20%2ARank%20Correlation%20Methods%2A."}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(trend)\nmk.test(lynx)\nsens.slope(lynx)          # Sen's slope\nlm(lynx ~ time(lynx))     # 线性趋势（需校正自相关）", "resultKind": "实算", "resultText": "线性趋势斜率 3.285 只/年，约为均值的 0.21%/年——趋势很弱，且被 9—10 年周期主导。", "interpret": "Mann-Kendall 是非参数趋势检验，不假设分布，但同样假设观测独立。对强自相关序列，应使用\"预白化\"（pre-whitening）或块 bootstrap，否则 p 值会虚假显著。报告要写斜率、CI 与自相关处理方式。", "fig": "fig_lynx.svg", "figCaption": "图：猞猁序列与线性趋势。趋势斜率仅 3.3 只/年，序列主要被 9—10 年周期主导。", "packages": ["trend"], "report": "报告序列长度、平稳性处理、模型阶数或状态空间结构，以及趋势/周期的置信区间。", "pitfalls": ["忽略自相关做趋势检验", "序列太短仍做谱分析", "把周期当因果", "变点数量不校正"], "assumptions": ["序列平稳（趋势/周期需先处理）", "长度足够覆盖数个周期，否则谱分析不可靠", "自相关会夸大趋势显著性，需预白化或状态空间模型"], "steps": ["画序列图，检查趋势、周期与突变", "去趋势/差分，检验平稳性", "拟合 ARIMA 或状态空间模型，检查残差白噪声"], "figNotes": ["看长期趋势线与原始序列的关系", "趋势斜率很小（3.3/年），主要变异来自周期", "强自相关下趋势检验需预白化"], "what": "检验序列是否存在单调趋势，并估计斜率。", "why": "监测数据的核心问题。强自相关下普通趋势检验会假性显著，需预白化或改用状态空间模型。", "dataProfile": {"name": "模拟数据", "shape": "按方法假设生成的结构化数据", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "监测数据常问“是否下降”，但强自相关下普通趋势检验会假性显著。"}, {"id": "12.4", "title": "12.4 ARIMA 模型", "lit": [{"text": "Box & Jenkins (1970).", "url": "https://search.crossref.org/?q=Box%20%26%20Jenkins%20%281970%29."}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(forecast)\nfit <- auto.arima(log(lynx))\nsummary(fit)\ncheckresiduals(fit)\nforecast(fit, h = 10)", "resultKind": "实算", "resultText": "AR/MA 阶数、AIC、残差白噪声检验、10 年预测区间。", "interpret": "ARIMA 用自回归与移动平均刻画序列依赖。生态学序列通常很短（< 50 年），参数估计不稳，且非平稳与观测误差会破坏假设。现代替代是状态空间模型（12.6），它能把过程与观测误差分开。", "fig": "fig_arima.svg", "figCaption": "图：AR(2) 模型与 20 年预测。阴影为随预测步长扩大的预测区间。", "packages": ["forecast"], "report": "报告序列长度、平稳性处理、模型阶数或状态空间结构，以及趋势/周期的置信区间。", "pitfalls": ["忽略自相关做趋势检验", "序列太短仍做谱分析", "把周期当因果", "变点数量不校正"], "assumptions": ["序列平稳（趋势/周期需先处理）", "长度足够覆盖数个周期，否则谱分析不可靠", "自相关会夸大趋势显著性，需预白化或状态空间模型"], "steps": ["画序列图，检查趋势、周期与突变", "去趋势/差分，检验平稳性", "拟合 ARIMA 或状态空间模型，检查残差白噪声"], "figNotes": ["阴影随预测步长变宽", "长期预测应谨慎解读"], "what": "用自回归与移动平均项刻画序列依赖，并做短期预测。", "why": "适合平稳、较长的序列；生态序列常太短，ARIMA 的参数估计不稳，需谨慎。", "dataProfile": {"name": "模拟数据", "shape": "114 年序列，用前 94 年拟合 AR(2)，预测 20 年。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "序列较长且近似平稳（对数后），AR(2) 足以刻画其依赖结构。"}, {"id": "12.5", "title": "12.5 变点检测", "lit": [{"text": "Killick, Fearnhead & Eckley (2012). Optimal detection of changepoints with a linear computational cost. *JASA* 107: 1590–1598.", "url": "https://search.crossref.org/?q=Optimal%20detection%20of%20changepoints%20with%20a%20linear%20computational%20cost"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(changepoint)\ncp <- cpt.meanvar(log(lynx), method = \"PELT\")\ncpts(cp)\nplot(cp)", "resultKind": "实算", "resultText": "检测到的变点位置与数量；BIC 选择变点数。", "interpret": "变点检测用于识别\"状态转换\"（regime shift），如群落突变、湖泊富营养化转折。它回答\"何时变\"，但不回答\"为什么变\"；必须与外部驱动变量（气候、管理）结合解释，并做多重检验校正。", "fig": "fig_changepoint.svg", "figCaption": "图：变点检测。两条虚线为检测到的均值突变位置。", "packages": ["changepoint"], "report": "报告序列长度、平稳性处理、模型阶数或状态空间结构，以及趋势/周期的置信区间。", "pitfalls": ["忽略自相关做趋势检验", "序列太短仍做谱分析", "把周期当因果", "变点数量不校正"], "assumptions": ["序列平稳（趋势/周期需先处理）", "长度足够覆盖数个周期，否则谱分析不可靠", "自相关会夸大趋势显著性，需预白化或状态空间模型"], "steps": ["画序列图，检查趋势、周期与突变", "去趋势/差分，检验平稳性", "拟合 ARIMA 或状态空间模型，检查残差白噪声"], "figNotes": ["虚线位置是检测到的均值突变", "变点数量需要校正"], "what": "检测序列均值或方差发生突变的位置。", "why": "生态系统常有状态转换（regime shift）。变点检测回答“何时变”，机制仍需外部驱动变量解释。", "dataProfile": {"name": "模拟数据", "shape": "114 年序列，搜索 2 个均值变点。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "猞猁序列存在明显的均值突变，变点检测可定位这些年份。"}, {"id": "12.6", "title": "12.6 状态空间模型", "lit": [{"text": "Auger-Méthé et al. (2021). A guide to state–space modeling of ecological time series. *Ecological Monographs* 91: e01470.", "url": "https://search.crossref.org/?q=A%20guide%20to%20state%E2%80%93space%20modeling%20of%20ecological%20time%20series"}], "data": [{"text": "lynx：加拿大猞猁皮毛收购量，1821—1934", "url": "https://stat.ethz.ch/R-manual/R-devel/library/datasets/html/lynx.html"}], "code": "library(MARSS)\nfit <- MARSS(matrix(log(lynx), nrow = 1), model = list(U = \"equal\", Q = \"diagonal\"))\nsummary(fit)", "resultKind": "实算", "resultText": "过程误差方差 Q、观测误差方差 R、潜在状态估计。", "interpret": "状态空间模型把\"真实种群\"与\"观测\"分开，是处理监测数据的最严谨框架。它需要重复观测或强先验来识别 Q 与 R；否则二者不可分。顶刊的长期监测论文几乎都用这一框架。", "fig": "fig_statespace.svg", "figCaption": "图：状态空间模型。观测（灰）围绕真实状态波动，Kalman 平滑（绿）更接近真实值。", "packages": ["MARSS"], "report": "报告序列长度、平稳性处理、模型阶数或状态空间结构，以及趋势/周期的置信区间。", "pitfalls": ["忽略自相关做趋势检验", "序列太短仍做谱分析", "把周期当因果", "变点数量不校正"], "assumptions": ["序列平稳（趋势/周期需先处理）", "长度足够覆盖数个周期，否则谱分析不可靠", "自相关会夸大趋势显著性，需预白化或状态空间模型"], "steps": ["画序列图，检查趋势、周期与突变", "去趋势/差分，检验平稳性", "拟合 ARIMA 或状态空间模型，检查残差白噪声"], "figNotes": ["平滑线比观测更接近真实状态", "观测误差越大，平滑收益越大"], "what": "把“真实状态”与“观测误差”分开建模。", "why": "监测数据几乎都带观测误差；状态空间模型能剥离误差、估计真实动态，是长期监测的标准框架。", "dataProfile": {"name": "lynx", "shape": "60 个时间点：真实 AR(1) 状态 + 观测噪声。", "vars": ["皮毛收购量，39—6991，均值 1538", "无缺失、无协变量"], "quirks": "强自相关（lag-1 = 0.72）、9—10 年周期、右偏，是谱分析与状态空间模型的经典素材；没有协变量，无法做机制回归。"}, "fitReason": "监测数据带观测误差，状态空间模型把真实动态与误差分开。"}, {"id": "12.7", "title": "12.7 动态占域模型", "lit": [{"text": "MacKenzie et al. (2003). Estimating site occupancy, colonization, and local extinction when a species is detected imperfectly. *Ecology* 84: 2200–2207.", "url": "https://search.crossref.org/?q=Estimating%20site%20occupancy%2C%20colonization%2C%20and%20local%20extinction%20when%20a%20species%20is%20detected%20imperfectly"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(unmarked)\numf <- unmarkedMultFrame(y = det_hist, numPrimary = n_years)\nfit <- colext(~ 1, ~ 1, ~ 1, ~ 1, data = umf)\nsummary(fit)", "resultKind": "实算", "resultText": "初始占域率、定殖率 γ、灭绝率 ε、检测率 p。", "interpret": "动态占域同时估计\"分布状态\"与\"变化速率\"，并把检测概率显式建模。它回答的是\"分布区在扩张还是收缩\"，而不是\"今年看到几只\"。是多物种监测数据的标准方法。", "fig": "fig_dynocc.svg", "figCaption": "图：动态占域。未校正的观测比例系统性低于真实占域率。", "packages": ["unmarked"], "report": "报告序列长度、平稳性处理、模型阶数或状态空间结构，以及趋势/周期的置信区间。", "pitfalls": ["忽略自相关做趋势检验", "序列太短仍做谱分析", "把周期当因果", "变点数量不校正"], "assumptions": ["序列平稳（趋势/周期需先处理）", "长度足够覆盖数个周期，否则谱分析不可靠", "自相关会夸大趋势显著性，需预白化或状态空间模型"], "steps": ["画序列图，检查趋势、周期与突变", "去趋势/差分，检验平稳性", "拟合 ARIMA 或状态空间模型，检查残差白噪声"], "figNotes": ["未校正的观测比例系统性偏低", "差距就是检测不完全的代价"], "what": "同时估计占域率、定殖率、灭绝率与检测率。", "why": "分布区在扩张还是收缩，不能靠“今年看到几只”；动态占域把检测过程显式建模后才能回答。", "dataProfile": {"name": "模拟数据", "shape": "15 年的占域率轨迹（真实 vs 未校正观测）。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "分布调查有重复访问，才能同时估计占域率与检测率。"}]}, {"title": "第 13 章　种群统计与不完全观测", "intro": "", "entries": [{"id": "13.1", "title": "13.1 生命表", "lit": [{"text": "Pearl & Reed (1920). On the rate of growth of the population of the United States. *PNAS* 6: 275–288", "url": "https://search.crossref.org/?q=On%20the%20rate%20of%20growth%20of%20the%20population%20of%20the%20United%20States"}, {"text": "Deevey (1947). Life tables for natural populations of animals. *Quarterly Review of Biology* 22: 283–314.", "url": "https://search.crossref.org/?q=Life%20tables%20for%20natural%20populations%20of%20animals"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "lx <- c(1000, 800, 600, 300, 120, 20)   # 各年龄存活数\nmx <- c(0, 0.2, 0.8, 1.2, 0.9, 0.3)     # 生殖力\ndx <- -diff(c(lx, 0))\nqx <- dx / lx\nLx <- (lx + c(lx[-1], 0)) / 2\nR0 <- sum(Lx * mx) / lx[1]\nT  <- sum(seq_along(Lx) * Lx * mx) / sum(Lx * mx)\nr  <- log(R0) / T", "resultKind": "实算", "resultText": "R0（净生殖率）、T（世代时间）、r（内禀增长率），以及存活曲线。", "interpret": "生命表是种群统计的基础。队列生命表跟踪同一批个体，静态生命表按年龄抽样（需假设稳定年龄结构）。忽略这个假设是最常见的错误。", "fig": "fig_survivor.svg", "figCaption": "图：存活曲线（I 型）。早期存活率高、后期快速下降，是大型哺乳动物与人类的典型形状。", "packages": [], "report": "报告估计方法、关键假设（封闭性、等捕获率、g(0)=1）、参数 CI 与模型选择依据。", "pitfalls": ["单次调查估占域", "忽略检测概率", "g(0) 假设不成立", "把 PVA 当绝对预测"], "assumptions": ["封闭性假设：调查期内无大量迁入迁出/死亡", "等捕获率或可建模的捕获异质性", "距离取样要求 g(0)=1，否则密度被低估"], "steps": ["明确调查设计与可识别参数（N、φ、p、ψ）", "拟合模型并做拟合优度/模型选择", "报告参数 CI，并讨论关键假设"], "figNotes": ["I 型：早期平坦、后期陡降", "II 型：近似直线（恒定死亡率）", "III 型：早期陡降（大量幼体死亡）"], "what": "按年龄或阶段记录存活与生殖，计算 R0、世代时间与内禀增长率。", "why": "种群统计的起点：把“活多久、生多少”变成可比较的参数。区分队列表与静态表，是避免误读的关键。", "dataProfile": {"name": "模拟数据", "shape": "按方法假设生成的结构化数据", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "存活与生殖数据是年龄结构的，生命表把“活多久、生多少”整理成可比较的参数。"}, {"id": "13.2", "title": "13.2 Leslie 矩阵与种群投影", "lit": [{"text": "Leslie (1945). On the use of matrices in certain population mathematics. *Biometrika* 33: 183–212.", "url": "https://search.crossref.org/?q=On%20the%20use%20of%20matrices%20in%20certain%20population%20mathematics"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "A <- matrix(c(0, 0, 2.0,\n              0.5, 0, 0,\n              0, 0.8, 0.9), nrow = 3, byrow = TRUE)\neig <- eigen(A)\nlambda <- Re(eig$values[1])\nstable <- abs(Re(eig$vectors[, 1])); stable / sum(stable)", "resultKind": "实算", "resultText": "λ = 1.343；稳定阶段分布为 0.489（幼体）、0.182（亚成体）、0.329（成体）——种群以幼体为主，但成体贡献了主要生殖。", "interpret": "λ > 1 表示长期增长，λ < 1 表示衰退。稳定阶段分布说明\"若环境恒定，种群最终会以什么结构存在\"。注意 λ 是渐近性质，短期动态可能完全相反（瞬态放大）。", "fig": "fig_leslie.svg", "figCaption": "图：Leslie 矩阵投影。三条线分别对应幼体、亚成体、成体；长期增长率 λ = 1.343。", "packages": [], "report": "报告估计方法、关键假设（封闭性、等捕获率、g(0)=1）、参数 CI 与模型选择依据。", "pitfalls": ["单次调查估占域", "忽略检测概率", "g(0) 假设不成立", "把 PVA 当绝对预测"], "assumptions": ["封闭性假设：调查期内无大量迁入迁出/死亡", "等捕获率或可建模的捕获异质性", "距离取样要求 g(0)=1，否则密度被低估"], "steps": ["明确调查设计与可识别参数（N、φ、p、ψ）", "拟合模型并做拟合优度/模型选择", "报告参数 CI，并讨论关键假设"], "figNotes": ["三条线分别对应幼体、亚成体、成体", "长期看三条线平行上升（λ>1）", "λ 是渐近增长率，短期可能波动"], "what": "把生命表写成投影矩阵，用线性代数预测种群长期动态。", "why": "矩阵形式让 λ、稳定年龄结构与生殖价值都能算出来，是种群管理的通用语言。", "dataProfile": {"name": "模拟数据", "shape": "按方法假设生成的结构化数据", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "同一套生命率可按年龄写成矩阵，λ 与稳定结构就变成线性代数问题。"}, {"id": "13.3", "title": "13.3 敏感度与弹性分析", "lit": [{"text": "Caswell (1978). A general formula for the sensitivity of population growth rate to changes in life history parameters. *Theoretical Population Biology* 14: 215–230", "url": "https://search.crossref.org/?q=A%20general%20formula%20for%20the%20sensitivity%20of%20population%20growth%20rate%20to%20changes%20in%20life%20history%20parameters"}, {"text": "de Kroon, Plaisier, van Groenendael & Caswell (1986). Elasticity: the relative contribution of demographic parameters to population growth rate. *Ecology* 67: 1427–1431.", "url": "https://search.crossref.org/?q=Elasticity%3A%20the%20relative%20contribution%20of%20demographic%20parameters%20to%20population%20growth%20rate"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(popbio)\nsensitivity(A)\nelasticity(A)", "resultKind": "实算", "resultText": "弹性矩阵：成体存活（0.9）为 0.404，幼体存活（0.5）为 0.199，生殖力（2.0）为 0.199，亚成体存活（0.8）为 0.199。", "interpret": "弹性表示\"某生命率按比例改变时，λ 改变的相对幅度\"。本例中**成体存活**最重要（0.404），保护应优先降低成体死亡率。这是保护生物学\"该保护哪个阶段\"的标准定量依据。", "fig": "fig_elasticity.svg", "figCaption": "图：弹性矩阵。颜色越深表示该生命率对 λ 的相对贡献越大；成体存活（0.9）弹性最高（0.404）。", "packages": ["popbio"], "report": "报告估计方法、关键假设（封闭性、等捕获率、g(0)=1）、参数 CI 与模型选择依据。", "pitfalls": ["单次调查估占域", "忽略检测概率", "g(0) 假设不成立", "把 PVA 当绝对预测"], "assumptions": ["封闭性假设：调查期内无大量迁入迁出/死亡", "等捕获率或可建模的捕获异质性", "距离取样要求 g(0)=1，否则密度被低估"], "steps": ["明确调查设计与可识别参数（N、φ、p、ψ）", "拟合模型并做拟合优度/模型选择", "报告参数 CI，并讨论关键假设"], "figNotes": ["颜色越深，弹性越大（对 λ 影响越大）", "成体存活弹性最高（0.404），保护应优先", "弹性矩阵每行/列之和有助检查计算"], "what": "计算 λ 对每个生命率的偏导（敏感度）与比例影响（弹性）。", "why": "保护与收获管理必须回答“动哪个生命率最有效”。弹性分析给出的正是这个优先级。", "dataProfile": {"name": "模拟数据", "shape": "按方法假设生成的结构化数据", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "矩阵元素已知，才能算 λ 对每个生命率的偏导；这是保护优先级的定量依据。"}, {"id": "13.4", "title": "13.4 Lincoln-Petersen 估计", "lit": [{"text": "Petersen (1896). The yearly immigration of young plaice into the Limfjord. *Report of the Danish Biological Station*", "url": "https://search.crossref.org/?q=The%20yearly%20immigration%20of%20young%20plaice%20into%20the%20Limfjord"}, {"text": "Lincoln (1930). Calculating waterfowl abundance on the basis of banding returns. *USDA Circular* 118.", "url": "https://search.crossref.org/?q=Calculating%20waterfowl%20abundance%20on%20the%20basis%20of%20banding%20returns"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "n1 <- 120; n2 <- 100; m <- 30\nN_hat <- n1 * n2 / m\nN_chapman <- (n1 + 1) * (n2 + 1) / (m + 1) - 1", "resultKind": "实算", "resultText": "N̂ = 400；Chapman 校正估计 = 393。", "interpret": "估计的前提是：种群封闭、所有个体等概率捕获、标记不影响存活与可捕性、两次捕获间充分混合。m 很小时估计偏差大且方差极大，必须报告置信区间（对数正态近似或剖面似然）。", "fig": "fig_lincoln.svg", "figCaption": "图：Lincoln-Petersen 估计对重捕数 m 的敏感性。m 很小时估计急剧上升且不稳定，说明重捕数太少会让估计失去意义。", "packages": [], "report": "报告估计方法、关键假设（封闭性、等捕获率、g(0)=1）、参数 CI 与模型选择依据。", "pitfalls": ["单次调查估占域", "忽略检测概率", "g(0) 假设不成立", "把 PVA 当绝对预测"], "assumptions": ["封闭性假设：调查期内无大量迁入迁出/死亡", "等捕获率或可建模的捕获异质性", "距离取样要求 g(0)=1，否则密度被低估"], "steps": ["明确调查设计与可识别参数（N、φ、p、ψ）", "拟合模型并做拟合优度/模型选择", "报告参数 CI，并讨论关键假设"], "figNotes": ["m 越小，N̂ 越大且方差越大", "m < 10 时估计几乎不可用", "应报告置信区间，而不是单点估计"], "what": "用两次捕获中标记个体的比例，估计封闭种群的规模。", "why": "第一次系统性地估计“看不见的总体”。假设多、精度低，但概念简单，是理解捕获—再捕获的入口。", "dataProfile": {"name": "模拟数据", "shape": "按方法假设生成的结构化数据", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "两次捕获、封闭种群，是 Lincoln-Petersen 的典型场景；样本小、假设多，只能作快速估计。"}, {"id": "13.5", "title": "13.5 Cormack-Jolly-Seber 模型", "lit": [{"text": "Cormack (1964). Estimates of survival from the sighting of marked animals. *Biometrika* 51: 429–438", "url": "https://search.crossref.org/?q=Estimates%20of%20survival%20from%20the%20sighting%20of%20marked%20animals"}, {"text": "Jolly (1965). Explicit estimates from capture-recapture data. *Biometrika* 52: 225–247", "url": "https://search.crossref.org/?q=Explicit%20estimates%20from%20capture-recapture%20data"}, {"text": "Seber (1965). A note on the multiple-recapture census. *Biometrika* 52: 249–259.", "url": "https://search.crossref.org/?q=A%20note%20on%20the%20multiple-recapture%20census"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(RMark)\ndata(dipper)\nrun.dipper <- function() {\n  process.data(dipper, model = \"CJS\")\n  mark(dipper)\n}", "resultKind": "实算", "resultText": "表观存活率 φ 与捕获率 p，可按年份/组别建模。", "interpret": "CJS 估计的是\"表观存活率\"（存活且未永久迁出），因为死亡与迁出无法区分。它要求个体独立、标记不丢失。报告要给出模型选择（φ 常数 vs 时间依赖）与拟合优度检验。", "fig": "fig_cjs.svg", "figCaption": "图：CJS 模型的估计值与真值（模拟）。φ 与 p 都能被较好地恢复。", "packages": ["RMark"], "report": "报告估计方法、关键假设（封闭性、等捕获率、g(0)=1）、参数 CI 与模型选择依据。", "pitfalls": ["单次调查估占域", "忽略检测概率", "g(0) 假设不成立", "把 PVA 当绝对预测"], "assumptions": ["封闭性假设：调查期内无大量迁入迁出/死亡", "等捕获率或可建模的捕获异质性", "距离取样要求 g(0)=1，否则密度被低估"], "steps": ["明确调查设计与可识别参数（N、φ、p、ψ）", "拟合模型并做拟合优度/模型选择", "报告参数 CI，并讨论关键假设"], "figNotes": ["估计值接近真值，说明参数可识别", "样本少时区间会明显变宽"], "what": "利用多年捕获历史，同时估计表观存活率与捕获率。", "why": "开放种群的标准方法：允许出生、死亡、迁入迁出，是野生动物存活率估计的主力。", "dataProfile": {"name": "模拟数据", "shape": "120 只个体 × 6 次捕获的模拟历史（φ=0.7，p=0.5）。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "多年、多个体的捕获历史，恰好提供 CJS 所需的“个体 × 时间”结构。"}, {"id": "13.6", "title": "13.6 占域模型", "lit": [{"text": "MacKenzie et al. (2002). Estimating site occupancy rates when detection probabilities are less than one. *Ecology* 83: 2248–2255.", "url": "https://search.crossref.org/?q=Estimating%20site%20occupancy%20rates%20when%20detection%20probabilities%20are%20less%20than%20one"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(unmarked)\numf <- unmarkedFrameOccu(y = det_matrix, siteCovs = env)\nfit <- occu(~ 1 ~ elevation, data = umf)\nsummary(fit)\nbackTransform(fit, type = \"state\")", "resultKind": "实算", "resultText": "占域率 ψ 与检测率 p；环境对 ψ 的效应。", "interpret": "占域模型解决\"没看到 ≠ 不存在\"。它要求重复访问（至少 2—3 次）才能同时识别 ψ 与 p；单次调查无法识别。报告要给出 ψ、p 及二者的驱动变量，并说明封闭性假设。", "fig": "fig_occ.svg", "figCaption": "图：占域模型的估计值与真值（模拟）。3 次重复访问足以同时识别 ψ 与 p。", "packages": ["unmarked"], "report": "报告估计方法、关键假设（封闭性、等捕获率、g(0)=1）、参数 CI 与模型选择依据。", "pitfalls": ["单次调查估占域", "忽略检测概率", "g(0) 假设不成立", "把 PVA 当绝对预测"], "assumptions": ["封闭性假设：调查期内无大量迁入迁出/死亡", "等捕获率或可建模的捕获异质性", "距离取样要求 g(0)=1，否则密度被低估"], "steps": ["明确调查设计与可识别参数（N、φ、p、ψ）", "拟合模型并做拟合优度/模型选择", "报告参数 CI，并讨论关键假设"], "figNotes": ["3 次重复就足以同时识别 ψ 与 p", "单次调查无法识别"], "what": "用重复访问的出现/未出现数据，同时估计占域率与检测率。", "why": "解决“没看到 ≠ 不存在”。单次调查无法识别 ψ 与 p，这是分布调查最常被忽略的前提。", "dataProfile": {"name": "模拟数据", "shape": "80 个站点 × 3 次调查（ψ=0.6，p=0.4）。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "重复访问的出现/未出现数据，才能同时识别占域率与检测率。"}, {"id": "13.7", "title": "13.7 N-mixture 模型", "lit": [{"text": "Royle (2004). N-mixture models for estimating population size from spatially replicated counts. *Biometrics* 60: 108–115.", "url": "https://search.crossref.org/?q=N-mixture%20models%20for%20estimating%20population%20size%20from%20spatially%20replicated%20counts"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "fit <- pcount(~ 1 ~ habitat, data = umf_counts, K = 50)\nsummary(fit)", "resultKind": "实算", "resultText": "局部多度 λ 与检测率 p。", "interpret": "N-mixture 不需要个体标记，仅靠重复计数即可同时估计多度与检测率，因此广泛应用于鸟类计数。但它对分布假设敏感，常出现边界估计（p → 1），使用前应做模拟检验。", "fig": "fig_nmix.svg", "figCaption": "图：N-mixture 的估计值与真值（模拟）。λ 与 p 同时被估计，但对分布假设敏感。", "packages": [], "report": "报告估计方法、关键假设（封闭性、等捕获率、g(0)=1）、参数 CI 与模型选择依据。", "pitfalls": ["单次调查估占域", "忽略检测概率", "g(0) 假设不成立", "把 PVA 当绝对预测"], "assumptions": ["封闭性假设：调查期内无大量迁入迁出/死亡", "等捕获率或可建模的捕获异质性", "距离取样要求 g(0)=1，否则密度被低估"], "steps": ["明确调查设计与可识别参数（N、φ、p、ψ）", "拟合模型并做拟合优度/模型选择", "报告参数 CI，并讨论关键假设"], "figNotes": ["λ 与 p 同时被估计", "对分布假设敏感，需做模拟检验"], "what": "用重复计数同时估计局部多度与检测率。", "why": "没有个体标记也能估多度，适合鸟类计数等场景；代价是对分布假设敏感。", "dataProfile": {"name": "模拟数据", "shape": "50 个站点 × 3 次计数（λ=6，p=0.35）。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "重复计数、无个体标记，N-mixture 正是为这种数据设计的。"}, {"id": "13.8", "title": "13.8 距离取样", "lit": [{"text": "Buckland et al. (2001). *Introduction to Distance Sampling*", "url": "https://search.crossref.org/?q=Buckland%20et%20al.%20%282001%29.%20%2AIntroduction%20to%20Distance%20Sampling%2A"}, {"text": "Burnham & Anderson (1976). Mathematical models for nonparametric inferences from line transect data. *Biometrics*.", "url": "https://search.crossref.org/?q=Mathematical%20models%20for%20nonparametric%20inferences%20from%20line%20transect%20data"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(Distance)\nddf <- ds(distdata, key = \"hn\", adjustment = \"cos\")\nsummary(ddf)", "resultKind": "实算", "resultText": "检测函数参数、有效检测半宽、密度估计及 CI。", "interpret": "距离取样用\"检测概率随距离衰减\"估计密度，核心假设是 g(0) = 1（线上个体必被检测）。在雨林、夜间或隐蔽物种中该假设常被违反，导致密度低估；此时需用标记—重捕距离取样（MRDS）。", "fig": "fig_distance.svg", "figCaption": "图：距离取样的检测函数。柱为观测距离分布，曲线为拟合的 g(x)。", "packages": ["Distance"], "report": "报告估计方法、关键假设（封闭性、等捕获率、g(0)=1）、参数 CI 与模型选择依据。", "pitfalls": ["单次调查估占域", "忽略检测概率", "g(0) 假设不成立", "把 PVA 当绝对预测"], "assumptions": ["封闭性假设：调查期内无大量迁入迁出/死亡", "等捕获率或可建模的捕获异质性", "距离取样要求 g(0)=1，否则密度被低估"], "steps": ["明确调查设计与可识别参数（N、φ、p、ψ）", "拟合模型并做拟合优度/模型选择", "报告参数 CI，并讨论关键假设"], "figNotes": ["曲线随距离衰减，形状决定有效检测宽度", "g(0)=1 是整个方法的关键假设"], "what": "用检测距离随距离衰减的关系估计密度。", "why": "样线/样点调查的标准方法，核心假设是 g(0)=1。违反它（雨林、夜行种）会系统性低估密度。", "dataProfile": {"name": "模拟数据", "shape": "约 400 个检测距离，半正态检测函数（σ=32）。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "样线调查记录了每个个体的检测距离，半正态检测函数可以直接拟合。"}, {"id": "13.9", "title": "13.9 生存分析", "lit": [{"text": "Cox (1972). Regression models and life-tables. *JRSS B* 34: 187–220", "url": "https://search.crossref.org/?q=Regression%20models%20and%20life-tables"}, {"text": "Kaplan & Meier (1958). Nonparametric estimation from incomplete observations. *JASA* 53: 457–481.", "url": "https://search.crossref.org/?q=Nonparametric%20estimation%20from%20incomplete%20observations"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(survival)\nfit <- survfit(Surv(time, status) ~ treatment, data = df)\nplot(fit)\ncox <- coxph(Surv(time, status) ~ treatment + size, data = df)\nsummary(cox)\ncox.zph(cox)", "resultKind": "实算", "resultText": "生存曲线、风险比（HR）及比例风险假设检验。", "interpret": "生存分析处理\"删失\"（研究结束时仍存活、或失访）。Cox 模型给出风险比，不假设基线风险形式。必须检验比例风险假设（`cox.zph`），否则 HR 不可解释。", "fig": "fig_survival.svg", "figCaption": "图：Kaplan-Meier 生存曲线。两条曲线的分离程度即处理效应。", "packages": ["survival"], "report": "报告估计方法、关键假设（封闭性、等捕获率、g(0)=1）、参数 CI 与模型选择依据。", "pitfalls": ["单次调查估占域", "忽略检测概率", "g(0) 假设不成立", "把 PVA 当绝对预测"], "assumptions": ["封闭性假设：调查期内无大量迁入迁出/死亡", "等捕获率或可建模的捕获异质性", "距离取样要求 g(0)=1，否则密度被低估"], "steps": ["明确调查设计与可识别参数（N、φ、p、ψ）", "拟合模型并做拟合优度/模型选择", "报告参数 CI，并讨论关键假设"], "figNotes": ["曲线分离即处理效应", "同时看中位生存时间"], "what": "分析事件发生时间（死亡、迁出、萌发），并处理删失。", "why": "很多个体在研究结束时仍存活，直接算平均寿命会偏短；生存分析专门处理这种删失。", "dataProfile": {"name": "模拟数据", "shape": "两组各 40 个个体的生存时间与删失。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "生存时间带删失（研究结束时仍存活），普通均值会偏短，必须用生存分析。"}, {"id": "13.10", "title": "13.10 种群生存力分析（PVA）", "lit": [{"text": "Shaffer (1981). Minimum population sizes for species conservation. *BioScience* 31: 131–134", "url": "https://search.crossref.org/?q=Minimum%20population%20sizes%20for%20species%20conservation"}, {"text": "Beissinger & McCullough (2002). *Population Viability Analysis*.", "url": "https://search.crossref.org/?q=Beissinger%20%26%20McCullough%20%282002%29.%20%2APopulation%20Viability%20Analysis%2A."}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(popbio)\n# 随机矩阵模拟\nsim <- replicate(1000, {\n  A_r <- A * matrix(runif(9, 0.8, 1.2), 3, 3)\n  pop.projection(A_r, c(10, 10, 10), 50)$lambda\n})\nmean(sim < 1)", "resultKind": "实算", "resultText": "灭绝概率、λ 的分布、最小可存活种群。", "interpret": "PVA 用随机模拟估计灭绝风险，适合比较不同管理情景，而不是给出\"绝对预测\"。报告要说明：随机性来源、模拟时长、阈值定义、以及参数不确定性是否传播。", "fig": "fig_pva.svg", "figCaption": "图：PVA 的灭绝概率随年限上升。这是 300 次随机模拟的结果，不是解析解。", "packages": ["popbio"], "report": "报告估计方法、关键假设（封闭性、等捕获率、g(0)=1）、参数 CI 与模型选择依据。", "pitfalls": ["单次调查估占域", "忽略检测概率", "g(0) 假设不成立", "把 PVA 当绝对预测"], "assumptions": ["封闭性假设：调查期内无大量迁入迁出/死亡", "等捕获率或可建模的捕获异质性", "距离取样要求 g(0)=1，否则密度被低估"], "steps": ["明确调查设计与可识别参数（N、φ、p、ψ）", "拟合模型并做拟合优度/模型选择", "报告参数 CI，并讨论关键假设"], "figNotes": ["灭绝概率随年限上升", "这是随机模拟结果，不是解析解"], "what": "用随机模拟估计种群在未来降到阈值以下的概率。", "why": "把灭绝风险变成可比较的数字，用于管理情景比较；它是相对工具，不是绝对预测。", "dataProfile": {"name": "模拟数据", "shape": "3 阶段矩阵 + 25% 环境噪声，300 次重复。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "有投影矩阵与随机性设定，才能模拟灭绝概率；没有生命率数据就无法做 PVA。"}]}, {"title": "第 14 章　性状、功能与系统发育", "intro": "", "entries": [{"id": "14.1", "title": "14.1 群落加权均值（CWM）", "lit": [{"text": "Garnier et al. (2004). Plant functional markers capture ecosystem properties during secondary succession. *Ecology* 85: 2630–2637", "url": "https://search.crossref.org/?q=Plant%20functional%20markers%20capture%20ecosystem%20properties%20during%20secondary%20succession"}, {"text": "Lavorel et al. (2008). Assessing functional diversity in the field. *Functional Ecology* 22: 134–147.", "url": "https://search.crossref.org/?q=Assessing%20functional%20diversity%20in%20the%20field"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(FD)\ntraits <- read.csv(\"traits.csv\", row.names = 1)\ncwm <- functcomp(traits, dune, CWM.type = \"all\")\nhead(cwm)", "resultKind": "实算", "resultText": "每个样方的性状加权平均值（按多度加权）。", "interpret": "CWM 描述\"群落的优势性状\"，适合分析环境筛选（如干旱梯度下 SLA 下降）。它与功能多样性（性状差异）回答不同问题，不能互相替代。报告时要说明性状来源与种内变异的处理方式。", "fig": "fig_cwm.svg", "figCaption": "图：CWM 沿 A1 梯度的变化。性状加权均值随环境单调变化，提示环境筛选。", "packages": ["FD"], "report": "报告性状来源与标准化、系统发育树来源与分支长度、零模型类型及敏感性分析。", "pitfalls": ["性状选择主观且不报告", "忽略系统发育非独立性", "零模型选择不当", "树的不确定性未传播"], "assumptions": ["性状同源、可比、测量误差可控", "系统发育树的分支长度与拓扑已知（或做敏感性分析）", "零模型的选择要与假设匹配（taxa.labels vs phylogeny.pool）"], "steps": ["整理性状矩阵并标准化", "计算多样性/信号/PGLS", "用零模型或敏感性分析检验结论稳健性"], "figNotes": ["CWM 随环境单调变化，提示环境筛选", "非线性说明存在最适值"], "what": "按多度加权计算群落的平均性状值。", "why": "描述“群落的优势性状”，用于分析环境筛选；与功能多样性（性状差异）回答不同问题。", "dataProfile": {"name": "dune + dune.env", "shape": "30 种 × 3 个性状（模拟）+ 20 个样方的多度。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "只有多度没有性状时算不了 CWM；这里用模拟性状演示“多度加权”的计算逻辑。"}, {"id": "14.2", "title": "14.2 第四角分析", "lit": [{"text": "Legendre, Galzin & Harmelin-Vivien (1997). Relating behavior to habitat: solutions to the fourth-corner problem. *Ecology* 78: 547–562", "url": "https://search.crossref.org/?q=Relating%20behavior%20to%20habitat%3A%20solutions%20to%20the%20fourth-corner%20problem"}, {"text": "Dray & Legendre (2008). Testing the species traits–environment relationships: the fourth-corner problem revisited. *Ecology* 89: 3400–3412.", "url": "https://search.crossref.org/?q=Testing%20the%20species%20traits%E2%80%93environment%20relationships%3A%20the%20fourth-corner%20problem%20revisited"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(ade4)\n# L: 样方×物种; R: 样方×环境; Q: 物种×性状\nplot(fourthcorner.rlq(L, R, Q, model.type = \"poly\"))\nfourthcorner(L, R, Q, model.type = 2)\nfourthcorner(L, R, Q, model.type = 4)", "resultKind": "实算", "resultText": "性状—环境组合的关联强度与置换 p（Model 2 与 Model 4）。", "interpret": "第四角回答\"具有某性状的物种是否更常出现在某环境\"。**两种置换模型都要报告**：Model 2 检验性状—环境关联，Model 4 检验多度—环境关联。只报一个会被认为分析不完整。", "fig": "fig_fourth.svg", "figCaption": "图：第四角的性状—环境关联矩阵。颜色与数值表示相关强度与方向。", "packages": ["ade4"], "report": "报告性状来源与标准化、系统发育树来源与分支长度、零模型类型及敏感性分析。", "pitfalls": ["性状选择主观且不报告", "忽略系统发育非独立性", "零模型选择不当", "树的不确定性未传播"], "assumptions": ["性状同源、可比、测量误差可控", "系统发育树的分支长度与拓扑已知（或做敏感性分析）", "零模型的选择要与假设匹配（taxa.labels vs phylogeny.pool）"], "steps": ["整理性状矩阵并标准化", "计算多样性/信号/PGLS", "用零模型或敏感性分析检验结论稳健性"], "figNotes": ["颜色与数值表示关联方向与强度", "显著性取决于置换模型的选择"], "what": "检验物种性状与环境之间的关联，同时利用多度信息。", "why": "回答“具有某性状的物种是否更常出现在某环境”，是性状—环境关系的经典框架。", "dataProfile": {"name": "dune + dune.env", "shape": "30 种性状、20 个样方环境、30×20 多度。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "三张表（多度、环境、性状）齐全，第四角才能把性状与环境联系起来。"}, {"id": "14.3", "title": "14.3 RLQ 分析", "lit": [{"text": "Dolédec et al. (1996). Matching species traits to environmental variables: a new three-table ordination method. *Environmental and Ecological Statistics* 3: 143–166.", "url": "https://search.crossref.org/?q=Matching%20species%20traits%20to%20environmental%20variables%3A%20a%20new%20three-table%20ordination%20method"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "rlq <- rlq(L, R, Q)\nplot(rlq)\nrandtest(rlq, modeltype = 6, nrepet = 999)", "resultKind": "实算", "resultText": "性状—环境协变轴、物种与样方得分、整体显著性。", "interpret": "RLQ 是第四角的多变量版本：它同时压缩三张表，找出\"性状组合—环境梯度\"的共同轴。它比第四角更适合性状与环境变量都很多的情形，但结果解释更抽象，需要结合载荷图。", "fig": "fig_rlq.svg", "figCaption": "图：RLQ 的样方得分与优势种性状得分。二者协变说明性状—环境存在共同轴。", "packages": [], "report": "报告性状来源与标准化、系统发育树来源与分支长度、零模型类型及敏感性分析。", "pitfalls": ["性状选择主观且不报告", "忽略系统发育非独立性", "零模型选择不当", "树的不确定性未传播"], "assumptions": ["性状同源、可比、测量误差可控", "系统发育树的分支长度与拓扑已知（或做敏感性分析）", "零模型的选择要与假设匹配（taxa.labels vs phylogeny.pool）"], "steps": ["整理性状矩阵并标准化", "计算多样性/信号/PGLS", "用零模型或敏感性分析检验结论稳健性"], "figNotes": ["两点云协变，说明存在性状—环境共同轴", "轴的含义要结合载荷解释"], "what": "把样方×环境、样方×物种、物种×性状三张表联合起来做排序。", "why": "第四角的多变量版本，适合性状与环境变量都很多的情形，能提取性状—环境共同轴。", "dataProfile": {"name": "模拟数据", "shape": "三张表：20×3 环境、20×30 多度、30×3 性状。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "性状与环境变量都多于 2 个，RLQ 的三表联合比单个性状相关更全面。"}, {"id": "14.4", "title": "14.4 功能多样性指数", "lit": [{"text": "Villéger, Mason & Mouillot (2008). New multidimensional functional diversity indices. *Ecology* 89: 2290–2301", "url": "https://search.crossref.org/?q=New%20multidimensional%20functional%20diversity%20indices"}, {"text": "Laliberté & Legendre (2010). A distance-based framework for measuring functional diversity. *Ecology* 91: 299–305.", "url": "https://search.crossref.org/?q=A%20distance-based%20framework%20for%20measuring%20functional%20diversity"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(FD)\nfd <- dbFD(traits, dune, w.abun = TRUE, stand.x = TRUE)\nfd$FRic; fd$FEve; fd$FDiv; fd$RaoQ", "resultKind": "实算", "resultText": "FRic（功能空间体积）、FEve（均匀度）、FDiv（离散度）、RaoQ。", "interpret": "四个指数分别刻画功能空间的不同侧面，彼此可能不一致。顶刊通常至少报告 FRic 与 RaoQ，并说明性状选择依据（性状数应少于物种数，且需检验共线）。", "fig": "fig_fdindices.svg", "figCaption": "图：FRic、FEve、FDiv 三个维度的对比。它们从不同角度描述功能结构。", "packages": ["FD"], "report": "报告性状来源与标准化、系统发育树来源与分支长度、零模型类型及敏感性分析。", "pitfalls": ["性状选择主观且不报告", "忽略系统发育非独立性", "零模型选择不当", "树的不确定性未传播"], "assumptions": ["性状同源、可比、测量误差可控", "系统发育树的分支长度与拓扑已知（或做敏感性分析）", "零模型的选择要与假设匹配（taxa.labels vs phylogeny.pool）"], "steps": ["整理性状矩阵并标准化", "计算多样性/信号/PGLS", "用零模型或敏感性分析检验结论稳健性"], "figNotes": ["三个指数并不同步", "同时报告才构成完整的功能结构描述"], "what": "用功能丰富度、均匀度、离散度等指数刻画性状空间。", "why": "物种数相同不代表功能相同；FD 指标体系让“功能结构”可量化、可比较。", "dataProfile": {"name": "dune + dune.env", "shape": "20 个样方的 FRic、FEve、FDiv。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "多度 + 性状矩阵，才能计算 FRic/FEve/FDiv 这类多维功能指数。"}, {"id": "14.5", "title": "14.5 系统发育信号（K / λ）", "lit": [{"text": "Blomberg, Garland & Ives (2003). Testing for phylogenetic signal in comparative data. *Evolution* 57: 717–745", "url": "https://search.crossref.org/?q=Testing%20for%20phylogenetic%20signal%20in%20comparative%20data"}, {"text": "Pagel (1999). Inferring the historical patterns of biological evolution. *Nature* 401: 877–884.", "url": "https://search.crossref.org/?q=Inferring%20the%20historical%20patterns%20of%20biological%20evolution"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(phytools)\ntree <- force.ultrametric(nj(as.dist(dune.phylodis)))\nx <- setNames(runif(30), tree$tip.label)   # 换成真实性状\nphylosig(tree, x, method = \"K\", test = TRUE)\nphylosig(tree, x, method = \"lambda\", test = TRUE)", "resultKind": "实算", "resultText": "K 值与置换 p；λ 的 ML 估计。", "interpret": "K ≈ 1 表示性状符合 Brownian 运动（亲缘越近越相似）；K < 1 表示亲缘种差异更大；λ 可视为信号强度的连续度量。二者都必须报告树来源与分支长度处理方式。", "fig": "fig_k.svg", "figCaption": "图：Blomberg's K 的零分布与观测值。观测落在分布内说明性状没有强系统发育信号。", "packages": ["phytools"], "report": "报告性状来源与标准化、系统发育树来源与分支长度、零模型类型及敏感性分析。", "pitfalls": ["性状选择主观且不报告", "忽略系统发育非独立性", "零模型选择不当", "树的不确定性未传播"], "assumptions": ["性状同源、可比、测量误差可控", "系统发育树的分支长度与拓扑已知（或做敏感性分析）", "零模型的选择要与假设匹配（taxa.labels vs phylogeny.pool）"], "steps": ["整理性状矩阵并标准化", "计算多样性/信号/PGLS", "用零模型或敏感性分析检验结论稳健性"], "figNotes": ["观测落在零分布内，说明信号不强", "K < 1 表示亲缘种差异更大"], "what": "用 Blomberg's K 或 Pagel's λ 量化性状在系统发育上的保守程度。", "why": "判断比较分析是否必须做系统发育校正：信号强时，忽略亲缘关系会严重高估显著性。", "dataProfile": {"name": "dune + dune.env", "shape": "30 种树 + 1 个性状，200 次随机性状模拟。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "有系统发育树与性状，才能估计 K/λ；没有树就只能假设物种独立。"}, {"id": "14.6", "title": "14.6 系统发育广义最小二乘（PGLS）", "lit": [{"text": "Grafen (1989). The phylogenetic regression. *Philosophical Transactions of the Royal Society B* 326: 119–157", "url": "https://search.crossref.org/?q=The%20phylogenetic%20regression"}, {"text": "Freckleton, Harvey & Pagel (2002). Phylogenetic analysis and comparative data: a test and review of evidence. *American Naturalist* 160: 712–726.", "url": "https://search.crossref.org/?q=Phylogenetic%20analysis%20and%20comparative%20data%3A%20a%20test%20and%20review%20of%20evidence"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(caper)\ncomp <- comparative.data(tree, data.frame(species = ..., trait = ..., env = ...),\n                         names.col = species)\npgls(trait ~ env, data = comp, lambda = \"ML\")", "resultKind": "实算", "resultText": "校正系统发育后的斜率与 λ。", "interpret": "PGLS 在回归中加入系统发育协方差，避免\"亲缘种不算独立样本\"导致的假阳性。λ = 0 等价于普通回归，λ = 1 等价于 Brownian。报告要给出 λ 估计与树的不确定性。", "fig": "fig_pgls.svg", "figCaption": "图：OLS 与 PGLS 的斜率对比。校正系统发育后斜率变化，说明非独立性影响了估计。", "packages": ["caper"], "report": "报告性状来源与标准化、系统发育树来源与分支长度、零模型类型及敏感性分析。", "pitfalls": ["性状选择主观且不报告", "忽略系统发育非独立性", "零模型选择不当", "树的不确定性未传播"], "assumptions": ["性状同源、可比、测量误差可控", "系统发育树的分支长度与拓扑已知（或做敏感性分析）", "零模型的选择要与假设匹配（taxa.labels vs phylogeny.pool）"], "steps": ["整理性状矩阵并标准化", "计算多样性/信号/PGLS", "用零模型或敏感性分析检验结论稳健性"], "figNotes": ["校正后斜率变化，说明非独立性有影响", "变化大时必须以 PGLS 为准"], "what": "在回归中加入系统发育协方差，得到校正后的效应。", "why": "跨物种比较的标准方法：物种不是独立样本，PGLS 让斜率不再被亲缘关系扭曲。", "dataProfile": {"name": "模拟数据", "shape": "30 种树 + 2 个性状，比较 OLS 与 PGLS。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "跨 30 个物种比较，亲缘关系不可忽略，PGLS 才能给出不受系统发育扭曲的斜率。"}, {"id": "14.7", "title": "14.7 独立对比（FIC）", "lit": [{"text": "Felsenstein (1985). Phylogenies and the comparative method. *American Naturalist* 125: 1–15.", "url": "https://search.crossref.org/?q=Phylogenies%20and%20the%20comparative%20method"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(ape)\nx <- setNames(rnorm(30), tree$tip.label)\ny <- setNames(rnorm(30), tree$tip.label)\npic_x <- pic(x, tree); pic_y <- pic(y, tree)\nsummary(lm(pic_y ~ pic_x - 1))", "resultKind": "实算", "resultText": "通过原点的回归斜率与 p。", "interpret": "独立对比把\"物种值\"转换为\"节点处的分化值\"，使其在 Brownian 模型下独立。它要求树完全解析、分支长度已知。今天 PGLS 更常用，但 FIC 的直观性仍是理解比较方法的最佳入口。", "fig": "fig_fic.svg", "figCaption": "图：独立对比的散点。通过原点的回归斜率即性状间的进化相关。", "packages": ["ape"], "report": "报告性状来源与标准化、系统发育树来源与分支长度、零模型类型及敏感性分析。", "pitfalls": ["性状选择主观且不报告", "忽略系统发育非独立性", "零模型选择不当", "树的不确定性未传播"], "assumptions": ["性状同源、可比、测量误差可控", "系统发育树的分支长度与拓扑已知（或做敏感性分析）", "零模型的选择要与假设匹配（taxa.labels vs phylogeny.pool）"], "steps": ["整理性状矩阵并标准化", "计算多样性/信号/PGLS", "用零模型或敏感性分析检验结论稳健性"], "figNotes": ["通过原点的斜率即进化相关", "离群对比点影响很大"], "what": "把物种值转换为节点处的独立对比值，再做回归。", "why": "Felsenstein 的经典解法，直观展示“如何去除系统发育非独立性”，是理解 PGLS 的最佳入口。", "dataProfile": {"name": "模拟数据", "shape": "29 个独立对比值（30 种树）。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "树完全解析、性状连续，独立对比的标准化差值才可计算。"}, {"id": "14.8", "title": "14.8 系统发育 β 多样性与群落结构", "lit": [{"text": "Webb et al. (2002). Phylogenies and community ecology. *Annual Review of Ecology and Systematics* 33: 475–505", "url": "https://search.crossref.org/?q=Phylogenies%20and%20community%20ecology"}, {"text": "Kembel et al. (2010). Picante. *Bioinformatics* 26: 1463–1464.", "url": "https://search.crossref.org/?q=Picante"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(picante)\ncomm <- dune[, colnames(dune) %in% attr(dune.phylodis, \"Labels\")]\nses.mpd(comm, dune.phylodis, null.model = \"taxa.labels\", runs = 999)\nses.mntd(comm, dune.phylodis, null.model = \"taxa.labels\", runs = 999)", "resultKind": "实算", "resultText": "MPD/MNTD 的标准化效应量（SES）；负值 = 系统发育聚集。", "interpret": "聚集提示环境筛选（近缘种耐性相似），发散提示竞争排斥。但这个推断高度依赖零模型：`taxa.labels` 与 `phylogeny.pool` 给出不同结论。顶刊要求说明零模型选择并做敏感性分析。", "fig": "fig_nri.svg", "figCaption": "图：NRI 的零分布。观测值偏离 0 表示系统发育聚集或发散。", "packages": ["picante"], "report": "报告性状来源与标准化、系统发育树来源与分支长度、零模型类型及敏感性分析。", "pitfalls": ["性状选择主观且不报告", "忽略系统发育非独立性", "零模型选择不当", "树的不确定性未传播"], "assumptions": ["性状同源、可比、测量误差可控", "系统发育树的分支长度与拓扑已知（或做敏感性分析）", "零模型的选择要与假设匹配（taxa.labels vs phylogeny.pool）"], "steps": ["整理性状矩阵并标准化", "计算多样性/信号/PGLS", "用零模型或敏感性分析检验结论稳健性"], "figNotes": ["偏离 0 表示聚集或发散", "零模型选择直接决定结论"], "what": "计算群落中物种的系统发育多样性及其标准化值（NRI/NTI）。", "why": "判断群落是系统发育聚集（环境筛选）还是发散（竞争排斥），但结论高度依赖零模型。", "dataProfile": {"name": "dune + dune.env", "shape": "200 次随机群落的 NRI 零分布。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "有树 + 多群落的存在/缺失，才能算 PD 与 NRI/NTI 的标准化值。"}]}, {"title": "第 15 章　网络分析", "intro": "", "entries": [{"id": "15.1", "title": "15.1 共现网络构建（SparCC）", "lit": [{"text": "Friedman & Alm (2012). Inferring correlation networks from genomic survey data. *PLoS Computational Biology* 8: e1002687", "url": "https://search.crossref.org/?q=Inferring%20correlation%20networks%20from%20genomic%20survey%20data"}, {"text": "Kurtz et al. (2015). Sparse and compositionally robust inference of microbial ecological networks. *PLoS Computational Biology* 11: e1004226.", "url": "https://search.crossref.org/?q=Sparse%20and%20compositionally%20robust%20inference%20of%20microbial%20ecological%20networks"}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "library(SpiecEasi)\nse <- spiec.easi(t(mite), method = \"sparcc\", lambda.min.ratio = 1e-2)\nnet <- adj2igraph(getRefit(se))", "resultKind": "实算", "resultText": "稀疏化的共现网络；边表示校正组成性后的关联。", "interpret": "共现 ≠ 互作。SparCC/SpiecEasi 只能给出\"统计关联\"，其来源可能是共同环境、扩散限制或真正的相互作用。顶刊要求：零模型检验、稳定性分析、以及至少两种方法的一致性比较。", "fig": "fig_network.svg", "figCaption": "图：35 种螨的共现网络。节点大小表示连接度，绿色边为正相关、红色为负相关；孤立节点表示与其他种无强关联。", "packages": ["SpiecEasi"], "report": "报告网络构建方法、阈值或惩罚参数、零模型与稳定性分析；避免把共现解释为互作。", "pitfalls": ["共现当互作", "阈值主观", "无零模型", "样本量不足仍建网"], "assumptions": ["采样完整性：网络指标对样本量高度敏感", "组成数据需校正（SparCC/SpiecEasi），否则相关虚假", "必须与零模型比较，并报告稳定性"], "steps": ["构建关联矩阵并选择推断方法", "阈值化/稀疏化，生成网络", "与零模型比较，做稳定性与模块分析"], "figNotes": ["节点大小 = 连接度，孤立点表示无强关联", "绿边正相关、红边负相关，粗细表示强度", "共现不等于互作，需零模型与稳定性分析"], "what": "用物种在多站点间的共现关系构建网络。", "why": "把群落从“物种列表”变成“关系结构”，用于发现模块、枢纽种与候选互作；但共现不等于互作。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "70 个样方 × 35 种螨类（多度 0—723，56.8% 为零）", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "70 个样方 × 35 种，共现关系足够构建网络；样本量也允许做稳定性分析。"}, {"id": "15.2", "title": "15.2 网络零模型", "lit": [{"text": "Gotelli & Graves (1996). *Null Models in Ecology*", "url": "https://search.crossref.org/?q=Gotelli%20%26%20Graves%20%281996%29.%20%2ANull%20Models%20in%20Ecology%2A"}, {"text": "Connor & Simberloff (1979). The assembly of species communities: chance or competition? *Ecology* 60: 1132–1140.", "url": "https://search.crossref.org/?q=Connor%20%26%20Simberloff%20%281979%29.%20The%20assembly%20of%20species%20communities%3A%20chance%20or%20compe"}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "library(vegan)\nnull <- nullmodel(t(mite > 0), \"curveball\")\nsim <- simulate(null, nsim = 99)", "resultKind": "实算", "resultText": "随机化后的连接度/嵌套性分布，与观测值比较得到 z 分数与 p。", "interpret": "零模型回答\"观测到的网络结构是否超出随机期望\"。关键选择是\"固定什么、随机什么\"（行和、列和、度序列），不同选择会给出相反结论，必须在方法中明确说明。", "fig": "fig_null.svg", "figCaption": "图：零模型的连接度分布。观测值落在分布中部，说明连接度并不异常。", "packages": ["vegan"], "report": "报告网络构建方法、阈值或惩罚参数、零模型与稳定性分析；避免把共现解释为互作。", "pitfalls": ["共现当互作", "阈值主观", "无零模型", "样本量不足仍建网"], "assumptions": ["采样完整性：网络指标对样本量高度敏感", "组成数据需校正（SparCC/SpiecEasi），否则相关虚假", "必须与零模型比较，并报告稳定性"], "steps": ["构建关联矩阵并选择推断方法", "阈值化/稀疏化，生成网络", "与零模型比较，做稳定性与模块分析"], "figNotes": ["观测落在分布中部，说明连接度不异常", "落在尾部才需要生态学解释"], "what": "用随机化生成“只有随机性”的网络作为基准。", "why": "任何网络指标（连接度、模块度、嵌套度）都必须与零模型比较，否则无法判断是否异常。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "35 种螨的共现网络，300 次随机网络。", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "任何网络指标都必须与随机网络比较，否则无法判断观测结构是否异常。"}, {"id": "15.3", "title": "15.3 模块度与社区发现", "lit": [{"text": "Newman & Girvan (2004). Finding and evaluating community structure in networks. *Physical Review E* 69: 026113", "url": "https://search.crossref.org/?q=Finding%20and%20evaluating%20community%20structure%20in%20networks"}, {"text": "Blondel et al. (2008). Fast unfolding of communities in large networks. *Journal of Statistical Mechanics*.", "url": "https://search.crossref.org/?q=Fast%20unfolding%20of%20communities%20in%20large%20networks"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(igraph)\ncomm <- cluster_louvain(net)\nmodularity(comm)\nmembership(comm)", "resultKind": "实算", "resultText": "模块度 Q（通常 0.3—0.7）与各节点所属模块。", "interpret": "模块度衡量\"网络是否分成紧密子群\"。Q > 0.3 通常认为有模块结构，但必须与同规模随机网络比较。模块的生态学解释（如功能群、生境偏好）需要外部数据验证。", "fig": "fig_modularity.svg", "figCaption": "图：按物种组成相似性分组的模块结构。同色节点为同一模块，Q 值见标题。", "packages": ["igraph"], "report": "报告网络构建方法、阈值或惩罚参数、零模型与稳定性分析；避免把共现解释为互作。", "pitfalls": ["共现当互作", "阈值主观", "无零模型", "样本量不足仍建网"], "assumptions": ["采样完整性：网络指标对样本量高度敏感", "组成数据需校正（SparCC/SpiecEasi），否则相关虚假", "必须与零模型比较，并报告稳定性"], "steps": ["构建关联矩阵并选择推断方法", "阈值化/稀疏化，生成网络", "与零模型比较，做稳定性与模块分析"], "figNotes": ["同色节点属于同一模块", "Q 越高，模块结构越清晰"], "what": "用模块度衡量网络是否分成紧密的子群。", "why": "模块对应生态位分化或共同进化单元；Q 值必须与同规模随机网络比较才有意义。", "dataProfile": {"name": "模拟数据", "shape": "35 个节点、75 条边，按物种相似性分 4 模块。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "网络规模适中、模块结构明显，适合展示模块度与模块划分。"}, {"id": "15.4", "title": "15.4 嵌套性（NODF）", "lit": [{"text": "Almeida-Neto et al. (2008). A consistent metric for nestedness analysis in ecological systems: reconciling concept and measurement. *Oikos* 117: 1227–1239", "url": "https://search.crossref.org/?q=A%20consistent%20metric%20for%20nestedness%20analysis%20in%20ecological%20systems%3A%20reconciling%20concept%20and%20measurement"}, {"text": "Bascompte et al. (2003). The nested assembly of plant–animal mutualistic networks. *PNAS* 100: 9383–9387.", "url": "https://search.crossref.org/?q=The%20nested%20assembly%20of%20plant%E2%80%93animal%20mutualistic%20networks"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(bipartite)\nnested(temp_mat, method = \"NODF\")\n# 与零模型比较\nnullmodel(temp_mat, \"r2d\", nsim = 99)", "resultKind": "实算", "resultText": "NODF 值（0—100）与零模型 z 分数。", "interpret": "嵌套性表示\"特化种的互作是泛化种互作的子集\"。它是互惠网络的普遍特征，但同样依赖零模型。报告要给出矩阵大小、填充度与零模型类型。", "fig": "fig_nested.svg", "figCaption": "图：嵌套性矩阵。按出现频率排序后，若非零格集中在左上角，说明存在嵌套结构。", "packages": ["bipartite"], "report": "报告网络构建方法、阈值或惩罚参数、零模型与稳定性分析；避免把共现解释为互作。", "pitfalls": ["共现当互作", "阈值主观", "无零模型", "样本量不足仍建网"], "assumptions": ["采样完整性：网络指标对样本量高度敏感", "组成数据需校正（SparCC/SpiecEasi），否则相关虚假", "必须与零模型比较，并报告稳定性"], "steps": ["构建关联矩阵并选择推断方法", "阈值化/稀疏化，生成网络", "与零模型比较，做稳定性与模块分析"], "figNotes": ["非零格集中在左上角，说明存在嵌套", "分散则没有明显嵌套"], "what": "度量特化种的互作是否为泛化种互作的子集。", "why": "嵌套性是互惠网络的普遍结构，反映物种对“核心泛化种”的依赖；同样需要零模型。", "dataProfile": {"name": "模拟数据", "shape": "70 个样方 × 35 种的填充矩阵。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "样方 × 物种矩阵有明确的填充结构，才能计算嵌套性。"}, {"id": "15.5", "title": "15.5 网络稳健性与关键种", "lit": [{"text": "Dunne, Williams & Martinez (2002). Network structure and biodiversity loss in food webs: robustness increases with connectance. *Ecology Letters* 5: 558–567.", "url": "https://search.crossref.org/?q=Network%20structure%20and%20biodiversity%20loss%20in%20food%20webs%3A%20robustness%20increases%20with%20connectance"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(igraph)\nrobustness <- function(g, order) {\n  g2 <- g; remain <- c()\n  for (v in order) {\n    g2 <- delete_vertices(g2, v)\n    remain <- c(remain, vcount(g2) / vcount(g))\n  }\n  remain\n}\n# 分别按度、随机、聚类系数移除", "resultKind": "实算", "resultText": "节点移除后剩余节点比例曲线；曲线下面积即稳健性。", "interpret": "稳健性依赖\"移除顺序\"：随机移除 vs 优先移除高度节点，结果完全不同。顶刊要求同时报告两种情景，并说明\"关键种\"的定义（度、介数、模块内中心性）。", "fig": "fig_robust.svg", "figCaption": "图：网络稳健性。优先移除高连接度节点时，网络崩塌得更快。", "packages": ["igraph"], "report": "报告网络构建方法、阈值或惩罚参数、零模型与稳定性分析；避免把共现解释为互作。", "pitfalls": ["共现当互作", "阈值主观", "无零模型", "样本量不足仍建网"], "assumptions": ["采样完整性：网络指标对样本量高度敏感", "组成数据需校正（SparCC/SpiecEasi），否则相关虚假", "必须与零模型比较，并报告稳定性"], "steps": ["构建关联矩阵并选择推断方法", "阈值化/稀疏化，生成网络", "与零模型比较，做稳定性与模块分析"], "figNotes": ["优先移除高连接节点时，网络崩塌更快", "两种移除顺序都要报告"], "what": "模拟移除节点后网络的崩塌速度。", "why": "把“关键种”从概念变成可比较的曲线；结果高度依赖移除顺序，两种情景都要报告。", "dataProfile": {"name": "模拟数据", "shape": "35 个节点，随机 vs 优先移除高度节点。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "35 个节点足以模拟移除过程，比较随机与定向移除的差异。"}, {"id": "15.6", "title": "15.6 指数随机图模型（ERGM）", "lit": [{"text": "Robins et al. (2007). An introduction to exponential random graph (p*) models for social networks. *Social Networks* 29: 173–191", "url": "https://search.crossref.org/?q=An%20introduction%20to%20exponential%20random%20graph%20%28p%2A%29%20models%20for%20social%20networks"}, {"text": "Cranmer & Desmarais (2011). Inferential network analysis with exponential random graph models. *Political Analysis*.", "url": "https://search.crossref.org/?q=Inferential%20network%20analysis%20with%20exponential%20random%20graph%20models"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(ergm)\nm <- ergm(net ~ edges + nodecov(\"abundance\") + gwesp(0.5, fixed = TRUE))\nsummary(m)", "resultKind": "实算", "resultText": "各结构项（边、度分布、三角形）的系数与显著性。", "interpret": "ERGM 把\"网络结构\"当作因变量，检验\"哪些局部过程（如传递性、属性匹配）能生成观测网络\"。它比零模型更进一步，但估计易退化（degeneracy），需要谨慎设定项与 MCMC 诊断。", "fig": "fig_ergm.svg", "figCaption": "图：ERGM 思路示意。加入传递性（三角形）项后，度分布向右移动。", "packages": ["ergm"], "report": "报告网络构建方法、阈值或惩罚参数、零模型与稳定性分析；避免把共现解释为互作。", "pitfalls": ["共现当互作", "阈值主观", "无零模型", "样本量不足仍建网"], "assumptions": ["采样完整性：网络指标对样本量高度敏感", "组成数据需校正（SparCC/SpiecEasi），否则相关虚假", "必须与零模型比较，并报告稳定性"], "steps": ["构建关联矩阵并选择推断方法", "阈值化/稀疏化，生成网络", "与零模型比较，做稳定性与模块分析"], "figNotes": ["三角形项让度分布右移", "ERGM 检验的是结构生成机制"], "what": "用指数族模型检验“哪些局部结构过程能生成观测网络”。", "why": "比零模型更进一步：不仅问“是否随机”，还问“是哪种结构机制（传递性、属性匹配）在起作用”。", "dataProfile": {"name": "模拟数据", "shape": "35 节点随机图 vs 加入三角形结构的图。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "网络结构有传递性迹象，ERGM 才能检验“三角形”是否超出随机期望。"}]}, {"title": "第 16 章　贝叶斯方法", "intro": "", "entries": [{"id": "16.1", "title": "16.1 贝叶斯广义线性模型", "lit": [{"text": "McElreath (2020). *Statistical Rethinking*, 2nd ed.", "url": "https://search.crossref.org/?q=McElreath%20%282020%29.%20%2AStatistical%20Rethinking%2A%2C%202nd%20ed."}, {"text": "Bürkner (2017). brms: an R package for Bayesian multilevel models using Stan. *Journal of Statistical Software* 80: 1–28.", "url": "https://search.crossref.org/?q=brms%3A%20an%20R%20package%20for%20Bayesian%20multilevel%20models%20using%20Stan"}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "library(brms)\nm <- brm(rich ~ WatrCont + SubsDens, family = poisson(),\n         data = mite.env, chains = 4, iter = 2000, cores = 4)\nsummary(m)\nposterior_interval(m, prob = 0.95)", "resultKind": "实算", "resultText": "后验均值、95% 可信区间、Rhat 与 ESS。", "interpret": "贝叶斯 GLM 与频率派 GLM 的点估计通常相近，但输出是完整的后验分布，可直接回答\"效应为负的概率是多少\"。适合小样本与需要纳入先验知识的场景。", "fig": "fig_post.svg", "figCaption": "图：斜率的后验分布与 95% 区间。区间不跨 0 表示效应方向明确。", "packages": ["brms"], "report": "报告先验及其依据、MCMC 诊断（Rhat、ESS）、后验预测检验与敏感性分析。", "pitfalls": ["先验不可辩护", "不做收敛诊断", "不做后验预测检验", "只报点估计"], "assumptions": ["先验可辩护：弱信息为默认，强先验需依据", "收敛诊断通过（Rhat<1.01，ESS>400）", "后验预测检验通过，且做先验敏感性分析"], "steps": ["写模型并设定先验", "运行 MCMC/INLA，检查收敛", "做后验预测检验与模型比较，报告后验区间"], "figNotes": ["区间不跨 0，说明方向明确", "后验形状反映不确定性"], "what": "用贝叶斯方法估计广义线性模型的参数，得到完整后验分布。", "why": "小样本、需要纳入先验、或想直接回答“效应为负的概率”时，贝叶斯比频率派更自然。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "70 个样方，MCMC 6000 次迭代（前 1500 预热）。", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "70 个样方、样本不大，贝叶斯后验能直接给出区间与“效应为负的概率”。"}, {"id": "16.2", "title": "16.2 贝叶斯层次模型", "lit": [{"text": "Kéry & Royle (2016). *Applied Hierarchical Modeling in Ecology*", "url": "https://search.crossref.org/?q=K%C3%A9ry%20%26%20Royle%20%282016%29.%20%2AApplied%20Hierarchical%20Modeling%20in%20Ecology%2A"}, {"text": "Gelman & Hill (2007). *Data Analysis Using Regression and Multilevel/Hierarchical Models*.", "url": "https://search.crossref.org/?q=Gelman%20%26%20Hill%20%282007%29.%20%2AData%20Analysis%20Using%20Regression%20and%20Multilevel/Hierarchica"}], "data": [{"text": "mite / mite.env / mite.xy：70 样方 × 35 种，苔藓螨", "url": "https://rdrr.io/cran/vegan/man/mite.html"}], "code": "m <- brm(rich ~ WatrCont + (1 | Topo), family = poisson(),\n         data = mite.env, prior = c(prior(normal(0, 5), class = \"b\"),\n                                    prior(exponential(1), class = \"sd\")))\nsummary(m)\nranef(m)", "resultKind": "实算", "resultText": "固定效应后验、组间标准差、各组的收缩估计。", "interpret": "层次模型的\"部分汇聚\"让小组估计向总体均值收缩，既保留差异又抑制噪声。这是稀有物种、小样地、短序列分析的优势所在。报告要给出组数与收缩程度。", "fig": "fig_hier.svg", "figCaption": "图：层次模型的收缩。样本少的组被更强地拉向总体均值。", "packages": [], "report": "报告先验及其依据、MCMC 诊断（Rhat、ESS）、后验预测检验与敏感性分析。", "pitfalls": ["先验不可辩护", "不做收敛诊断", "不做后验预测检验", "只报点估计"], "assumptions": ["先验可辩护：弱信息为默认，强先验需依据", "收敛诊断通过（Rhat<1.01，ESS>400）", "后验预测检验通过，且做先验敏感性分析"], "steps": ["写模型并设定先验", "运行 MCMC/INLA，检查收敛", "做后验预测检验与模型比较，报告后验区间"], "figNotes": ["× 向总体均值收缩", "小组收缩更强，这是部分汇聚的体现"], "what": "让参数本身服从分布，实现组间信息共享（部分汇聚）。", "why": "多组数据里，小组估计会被拉向总体均值，既保留差异又抑制噪声；这是层次模型的核心价值。", "dataProfile": {"name": "mite + mite.env + mite.xy", "shape": "按地形分 2 组，比较原始均值与收缩估计。", "vars": ["WatrCont：土壤含水量，连续，134—827", "SubsDens：基质密度，连续，21.2—80.6", "Substrate：基质类型，7 类（27/25/11/2/2/1，极不平衡）", "Shrub：灌木盖度，3 类（Few 26、Many 25、None 19）", "Topo：地形，2 类（Blanket 44、Hummock 26）", "mite.xy：70 个样方的空间坐标，规则网格、间距约 1—2.5 m"], "quirks": "零多、多度右偏、协变量混合类型（连续+分类），且带空间坐标——这正是空间分析与混合模型的理想素材。"}, "fitReason": "分组样本量差异大，部分汇聚可以稳定小组估计。"}, {"id": "16.3", "title": "16.3 先验设定与敏感性分析", "lit": [{"text": "Gelman et al. (2017). Prior distributions for variance parameters in hierarchical models", "url": "https://search.crossref.org/?q=Gelman%20et%20al.%20%282017%29.%20Prior%20distributions%20for%20variance%20parameters%20in%20hierarchica"}, {"text": "Depaoli & van de Schoot (2017). Improving transparency and replication in Bayesian statistics. *Psychological Methods*.", "url": "https://search.crossref.org/?q=Improving%20transparency%20and%20replication%20in%20Bayesian%20statistics"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "m_weak <- brm(rich ~ WatrCont + (1 | Topo), family = poisson(),\n              prior = prior(normal(0, 10), class = \"b\"), data = mite.env)\nm_strong <- update(m_weak, prior = prior(normal(0, 1), class = \"b\"))\nloo_compare(loo(m_weak), loo(m_strong))", "resultKind": "实算", "resultText": "输出：不同先验下的后验均值与区间；差异大说明结论对先验敏感。", "interpret": "先验必须\"可辩护\"：弱信息先验是默认，强先验需要依据。方差参数（随机效应标准差）对先验尤其敏感，推荐 Half-Normal/Half-Cauchy 或指数先验。敏感性分析应作为常规报告内容。", "fig": "fig_prior.svg", "figCaption": "图：先验敏感性。弱先验与强先验下的后验位置不同，差异大说明结论依赖先验。", "packages": [], "report": "报告先验及其依据、MCMC 诊断（Rhat、ESS）、后验预测检验与敏感性分析。", "pitfalls": ["先验不可辩护", "不做收敛诊断", "不做后验预测检验", "只报点估计"], "assumptions": ["先验可辩护：弱信息为默认，强先验需依据", "收敛诊断通过（Rhat<1.01，ESS>400）", "后验预测检验通过，且做先验敏感性分析"], "steps": ["写模型并设定先验", "运行 MCMC/INLA，检查收敛", "做后验预测检验与模型比较，报告后验区间"], "figNotes": ["两条曲线分离，说明结论对先验敏感", "重叠则说明数据主导后验"], "what": "为参数设定先验，并检验结论对先验的敏感程度。", "why": "先验不是“作弊”，而是把已有知识写进模型；但必须可辩护，并证明结论不依赖先验。", "dataProfile": {"name": "模拟数据", "shape": "同一数据，弱先验（SD=20）与强先验（SD=0.5）。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "先验选择会改变结论，必须做敏感性分析。"}, {"id": "16.4", "title": "16.4 MCMC 诊断", "lit": [{"text": "Vehtari et al. (2021). Rank-normalization, folding, and localization: an improved Rhat for assessing convergence of MCMC. *Bayesian Analysis* 16: 667–718.", "url": "https://search.crossref.org/?q=Rank-normalization%2C%20folding%2C%20and%20localization%3A%20an%20improved%20Rhat%20for%20assessing%20convergence%20of%20MCMC"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "summary(m)          # Rhat, Bulk_ESS, Tail_ESS\nplot(m)             # 迹图\nmcmc_plot(m, type = \"trace\")", "resultKind": "实算", "resultText": "判据：Rhat < 1.01、ESS > 400、迹图充分混合、无 divergent transitions。", "interpret": "收敛诊断不过关，后验不可信。常见原因：模型不可识别、先验过弱、参数化不佳（如中心化 vs 非中心化）。发现 divergent transitions 应优先检查层次结构与先验，而不是简单增加迭代次数。", "fig": "fig_trace.svg", "figCaption": "图：两条 MCMC 链的迹图。链充分混合、彼此缠绕，才可计算 Rhat。", "packages": [], "report": "报告先验及其依据、MCMC 诊断（Rhat、ESS）、后验预测检验与敏感性分析。", "pitfalls": ["先验不可辩护", "不做收敛诊断", "不做后验预测检验", "只报点估计"], "assumptions": ["先验可辩护：弱信息为默认，强先验需依据", "收敛诊断通过（Rhat<1.01，ESS>400）", "后验预测检验通过，且做先验敏感性分析"], "steps": ["写模型并设定先验", "运行 MCMC/INLA，检查收敛", "做后验预测检验与模型比较，报告后验区间"], "figNotes": ["两条链相互缠绕，说明混合良好", "Rhat 接近 1 才可信"], "what": "用 Rhat、ESS、迹图等诊断 MCMC 是否收敛。", "why": "后验再漂亮，不收敛就毫无意义。诊断不过关时，应先改参数化或先验，而不是加迭代。", "dataProfile": {"name": "模拟数据", "shape": "两条独立链，各 6000 次迭代。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "MCMC 结果只有在收敛后才可信，Rhat 与迹图是必查项。"}, {"id": "16.5", "title": "16.5 后验预测检验", "lit": [{"text": "Gabry et al. (2019). Visualization in Bayesian workflow. *JRSS A* 182: 389–402.", "url": "https://search.crossref.org/?q=Visualization%20in%20Bayesian%20workflow"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "pp_check(m, ndraws = 100)\npp_check(m, type = \"stat\", stat = \"mean\")", "resultKind": "实算", "resultText": "输出：观测数据与 100 组模拟数据的分布对比；贝叶斯 p 接近 0.5 表示拟合良好。", "interpret": "后验预测检验用拟合模型模拟数据，与观测数据比较分布特征（均值、零比例、极值）。它能发现\"模型整体拟合尚可但结构不对\"的问题，是贝叶斯工作流中不可跳过的一步。", "fig": "fig_ppc.svg", "figCaption": "图：后验预测检验。观测分布与模型模拟分布若系统性偏离，说明模型结构不对。", "packages": [], "report": "报告先验及其依据、MCMC 诊断（Rhat、ESS）、后验预测检验与敏感性分析。", "pitfalls": ["先验不可辩护", "不做收敛诊断", "不做后验预测检验", "只报点估计"], "assumptions": ["先验可辩护：弱信息为默认，强先验需依据", "收敛诊断通过（Rhat<1.01，ESS>400）", "后验预测检验通过，且做先验敏感性分析"], "steps": ["写模型并设定先验", "运行 MCMC/INLA，检查收敛", "做后验预测检验与模型比较，报告后验区间"], "figNotes": ["观测分布与模拟分布应接近", "系统性偏离说明模型结构不对"], "what": "用拟合模型模拟数据，与观测数据比较分布特征。", "why": "检查“模型整体像不像数据”，能发现系数显著但结构错误的问题。", "dataProfile": {"name": "模拟数据", "shape": "70 个观测 + 100 组后验模拟。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "模型能否重现数据的分布特征，是贝叶斯工作流不可跳过的一步。"}, {"id": "16.6", "title": "16.6 模型比较（LOO / WAIC）", "lit": [{"text": "Vehtari, Gelman & Gabry (2017). Practical Bayesian model evaluation using leave-one-out cross-validation and WAIC. *Statistics and Computing* 27: 1413–1432.", "url": "https://search.crossref.org/?q=Practical%20Bayesian%20model%20evaluation%20using%20leave-one-out%20cross-validation%20and%20WAIC"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "loo1 <- loo(m1); loo2 <- loo(m2)\nloo_compare(loo1, loo2)", "resultKind": "实算", "resultText": "输出：ΔELPD 与标准误、Pareto k 诊断；k > 0.7 需检查异常观测。", "interpret": "LOO 比 WAIC 更稳健，推荐优先。若 Pareto k 过大，说明该观测影响过大，需检查异常值或改用更稳健的模型。模型比较的结果应结合生态学可解释性，而不是唯数值论。", "fig": "fig_waic.svg", "figCaption": "图：WAIC 比较。差值越大，模型预测新数据的能力差距越大。", "packages": [], "report": "报告先验及其依据、MCMC 诊断（Rhat、ESS）、后验预测检验与敏感性分析。", "pitfalls": ["先验不可辩护", "不做收敛诊断", "不做后验预测检验", "只报点估计"], "assumptions": ["先验可辩护：弱信息为默认，强先验需依据", "收敛诊断通过（Rhat<1.01，ESS>400）", "后验预测检验通过，且做先验敏感性分析"], "steps": ["写模型并设定先验", "运行 MCMC/INLA，检查收敛", "做后验预测检验与模型比较，报告后验区间"], "figNotes": ["WAIC 差值越大，预测能力差距越大", "需结合权重与诊断一起报告"], "what": "用 LOO/WAIC 比较贝叶斯模型的预测表现。", "why": "贝叶斯模型不能只用 AIC；LOO 更稳健，且能诊断异常观测（Pareto k）。", "dataProfile": {"name": "模拟数据", "shape": "两个模型的 WAIC。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "两个模型预测能力接近时，LOO 比 AIC 更适合贝叶斯模型比较。"}]}, {"title": "第 17 章　机器学习与因果推断", "intro": "", "entries": [{"id": "17.1", "title": "17.1 随机森林", "lit": [{"text": "Breiman (2001). Random forests. *Machine Learning* 45: 5–32", "url": "https://search.crossref.org/?q=Random%20forests"}, {"text": "Cutler et al. (2007). Random forests for classification in ecology. *Ecology* 88: 2783–2792.", "url": "https://search.crossref.org/?q=Random%20forests%20for%20classification%20in%20ecology"}], "data": [{"text": "BCI / BCI.env：50 样方 × 225 种，巴拿马森林", "url": "https://rdrr.io/cran/vegan/man/BCI.html"}], "code": "library(ranger)\nset.seed(1)\nrf <- ranger(rich ~ ., data = df, num.trees = 500,\n             importance = \"permutation\", mtry = 3)\nrf$r.squared", "resultKind": "实算", "resultText": "OOB 预测误差、R²、变量重要性。", "interpret": "随机森林对高维、非线性、交互稳健，是生态学最常用的机器学习方法。报告必须给 OOB 误差与交叉验证误差（两者可能差很多），并说明树数、mtry 与最小节点大小。它不提供 p 值，不能直接做推断。", "fig": "fig_rf.svg", "figCaption": "图：随机森林的 OOB 误差随树数变化。曲线趋于平稳后即可停止增加树。", "packages": ["ranger"], "report": "报告特征工程、交叉验证方案、性能指标、可解释性方法与因果识别假设。", "pitfalls": ["随机 CV 用于空间数据", "把变量重要性当因果", "数据泄漏", "无外部验证"], "assumptions": ["无数据泄漏：特征选择在训练折内完成", "交叉验证匹配数据结构（空间/时间/分组）", "因果结论依赖识别假设（无未观测混杂、排他性等）"], "steps": ["划分训练/测试（按空间或时间分块）", "拟合模型并调参（嵌套 CV）", "评估性能并用 PDP/ALE/SHAP 解释，检验稳健性"], "figNotes": ["OOB 误差趋稳后即可停止加树", "继续增加收益递减"], "what": "用大量决策树的自助聚合做预测，并给出 OOB 误差。", "why": "高维、非线性、交互强时，随机森林几乎不需要调参就能给出稳健预测，是生态学最常用的机器学习方法。", "dataProfile": {"name": "BCI + BCI.env", "shape": "240 个样本 × 5 个预测变量，60 棵树。", "vars": ["225 个物种列，大量稀有种（约 98% 的样方-物种组合为 0）", "UTM.EW / UTM.NS：样方坐标", "Precipitation：常数 2530（无变异）", "Elevation：常数 120（无变异）", "Age.cat：2 类（c3 49、c2 1）", "Geology：单一类型 Tb（无变异）", "Habitat / Stream / EnvHet：生境、溪流、异质性"], "quirks": "多个环境变量是常数或近常数（降水、海拔、地质），所以只能做空间或生境分析；225 个物种中大量稀有种，使 Chao1 与稀疏化特别有意义。"}, "fitReason": "5 个预测变量、非线性与交互，随机森林无需指定函数形式即可拟合。"}, {"id": "17.2", "title": "17.2 变量重要性", "lit": [{"text": "Strobl et al. (2007). Bias in random forest variable importance measures. *BMC Bioinformatics* 8: 25", "url": "https://search.crossref.org/?q=Bias%20in%20random%20forest%20variable%20importance%20measures"}, {"text": "Genuer, Poggi & Tuleau-Malot (2010). Variable selection using random forests. *Pattern Recognition Letters*.", "url": "https://search.crossref.org/?q=Variable%20selection%20using%20random%20forests"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(vip)\nvi(rf)\nlibrary(Boruta)\nBoruta(rich ~ ., data = df)", "resultKind": "实算", "resultText": "置换重要性排序；Boruta 的\"确认/暂定/拒绝\"三类变量。", "interpret": "不纯度重要性会偏向连续变量与高基数变量；置换重要性更可靠。变量重要性排序不稳定（尤其 n < p），应报告 bootstrap 下的入选频率，而不是单次排序。", "fig": "fig_importance.svg", "figCaption": "图：置换重要性。X1 与 X2 最重要，与模拟设定一致。", "packages": [], "report": "报告特征工程、交叉验证方案、性能指标、可解释性方法与因果识别假设。", "pitfalls": ["随机 CV 用于空间数据", "把变量重要性当因果", "数据泄漏", "无外部验证"], "assumptions": ["无数据泄漏：特征选择在训练折内完成", "交叉验证匹配数据结构（空间/时间/分组）", "因果结论依赖识别假设（无未观测混杂、排他性等）"], "steps": ["划分训练/测试（按空间或时间分块）", "拟合模型并调参（嵌套 CV）", "评估性能并用 PDP/ALE/SHAP 解释，检验稳健性"], "figNotes": ["置换后误差增加越多，变量越重要", "共线变量会互相分摊重要性"], "what": "用置换或分裂准则衡量各变量对预测的贡献。", "why": "高维模型里“哪个变量重要”是核心问题；置换重要性比不纯度更可靠，但仍不是因果效应。", "dataProfile": {"name": "模拟数据", "shape": "5 个变量的置换重要性。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "高维模型中“谁重要”无法靠系数回答，置换重要性提供了可行替代。"}, {"id": "17.3", "title": "17.3 部分依赖与 SHAP", "lit": [{"text": "Lundberg & Lee (2017). A unified approach to interpreting model predictions. *NeurIPS*", "url": "https://search.crossref.org/?q=A%20unified%20approach%20to%20interpreting%20model%20predictions"}, {"text": "Apley & Zhu (2020). Visualizing the effects of predictor variables in black box supervised learning models. *JRSS B*.", "url": "https://search.crossref.org/?q=Visualizing%20the%20effects%20of%20predictor%20variables%20in%20black%20box%20supervised%20learning%20models"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(pdp); library(shapviz)\npd <- partial(rf, pred.var = \"Elevation\", train = df)\nplot(pd)\nshv <- shapviz(rf, X = df[, -1])\nsv_importance(shv); sv_dependence(shv, \"Elevation\")", "resultKind": "实算", "resultText": "输出：PDP/ALE 曲线、SHAP 重要性排序与依赖图。", "interpret": "PDP 展示\"平均边际效应\"，但在变量相关时会外推到不存在的组合；ALE 更稳健。SHAP 给出每个预测的变量贡献，可汇总为全局重要性并展示交互。三者结合，才能把\"黑箱\"翻译成\"响应曲线\"。", "fig": "fig_pdp.svg", "figCaption": "图：X1 的部分依赖曲线。线性上升说明模型学到了真实的线性效应。", "packages": [], "report": "报告特征工程、交叉验证方案、性能指标、可解释性方法与因果识别假设。", "pitfalls": ["随机 CV 用于空间数据", "把变量重要性当因果", "数据泄漏", "无外部验证"], "assumptions": ["无数据泄漏：特征选择在训练折内完成", "交叉验证匹配数据结构（空间/时间/分组）", "因果结论依赖识别假设（无未观测混杂、排他性等）"], "steps": ["划分训练/测试（按空间或时间分块）", "拟合模型并调参（嵌套 CV）", "评估性能并用 PDP/ALE/SHAP 解释，检验稳健性"], "figNotes": ["曲线形状就是边际效应", "变量相关时 PDP 可能外推到不存在组合"], "what": "用 PDP/ALE/SHAP 把黑箱模型的预测拆解成可解释的曲线与贡献。", "why": "顶刊不接受“随机森林显示温度最重要”。必须给出响应形状与交互，才能变成生态学发现。", "dataProfile": {"name": "模拟数据", "shape": "X1 的 25 点网格上的平均预测。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "黑箱模型必须翻译成响应曲线，才能与生态学机理对照。"}, {"id": "17.4", "title": "17.4 结构方程模型（SEM）", "lit": [{"text": "Wright (1921). Correlation and causation. *Journal of Agricultural Research* 20: 557–585", "url": "https://search.crossref.org/?q=Correlation%20and%20causation"}, {"text": "Grace (2006). *Structural Equation Modeling and Natural Systems*", "url": "https://search.crossref.org/?q=Grace%20%282006%29.%20%2AStructural%20Equation%20Modeling%20and%20Natural%20Systems%2A"}, {"text": "Lefcheck (2016). piecewiseSEM. *Methods in Ecology and Evolution* 7: 573–579.", "url": "https://search.crossref.org/?q=piecewiseSEM"}], "data": [{"text": "dune / dune.env：20 样方 × 30 种，荷兰草甸", "url": "https://rdrr.io/cran/vegan/man/dune.html"}], "code": "library(piecewiseSEM)\nm1 <- lmer(A1 ~ Management + (1 | Use), data = dune.env)\nm2 <- lmer(Moisture ~ A1 + Management + (1 | Use), data = dune.env)\nm3 <- lm(rich ~ Moisture + A1, data = cbind(dune.env, rich = rowSums(dune > 0)))\nsem <- psem(m1, m2, m3)\nsummary(sem, .progressBar = FALSE)", "resultKind": "实算", "resultText": "路径系数、p、Fisher's C 与 d-separation 检验。", "interpret": "SEM 把\"假设的因果结构\"写成联立方程。piecewiseSEM 用局部模型拟合 + d-separation 检验整体拟合，适合生态学的复杂数据结构。关键是：因果方向由研究者指定，数据本身不能证明方向；必须讨论等效模型。", "fig": "fig_sem.svg", "figCaption": "图：SEM 路径图。箭头上的数字为标准化路径系数，直接与间接效应可分解。", "packages": ["piecewiseSEM"], "report": "报告特征工程、交叉验证方案、性能指标、可解释性方法与因果识别假设。", "pitfalls": ["随机 CV 用于空间数据", "把变量重要性当因果", "数据泄漏", "无外部验证"], "assumptions": ["无数据泄漏：特征选择在训练折内完成", "交叉验证匹配数据结构（空间/时间/分组）", "因果结论依赖识别假设（无未观测混杂、排他性等）"], "steps": ["划分训练/测试（按空间或时间分块）", "拟合模型并调参（嵌套 CV）", "评估性能并用 PDP/ALE/SHAP 解释，检验稳健性"], "figNotes": ["箭头上的数字是路径系数", "直接效应加间接效应等于总效应"], "what": "把一组假设的因果路径写成联立方程并估计路径系数。", "why": "同时处理直接与间接效应，比较竞争性因果假设；但因果方向由研究者指定，数据不能证明方向。", "dataProfile": {"name": "dune + dune.env", "shape": "200 个样本的三变量路径模型（模拟）。", "vars": ["A1：土层厚度，连续，2.8—11.5 cm", "Moisture：水分等级，有序 1/2/4/5（7/4/2/7 个样方）", "Management：管理方式，4 类 SF/BF/HF/NM（6/3/5/6，严重不平衡）", "Use：利用类型，3 类（Hayfield 7、Haypastu 8、Pasture 5）", "Manure：施肥等级，有序 0—4"], "quirks": "67.2% 的物种-样方组合为 0，是典型稀疏矩阵；样方只有 20 个，能容纳的预测变量很少；管理组样本量 3—6 不等，渐近检验不可靠。"}, "fitReason": "有明确的因果假设（X→M→Y），SEM 才能估计直接与间接效应。"}, {"id": "17.5", "title": "17.5 双重差分（DID）", "lit": [{"text": "Card & Krueger (1994). Minimum wages and employment. *American Economic Review*", "url": "https://search.crossref.org/?q=Minimum%20wages%20and%20employment"}, {"text": "Ferraro & Hanauer (2014). Advances in measuring the environmental and social impacts of environmental programs. *Annual Review of Environment and Resources* 39: 495–517.", "url": "https://search.crossref.org/?q=Advances%20in%20measuring%20the%20environmental%20and%20social%20impacts%20of%20environmental%20programs"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(fixest)\nm <- feols(outcome ~ treated * post | unit + year, data = panel)\nsummary(m)\n# 平行趋势检验：事件研究\nfeols(outcome ~ i(year, treated, ref = -1) | unit + year, data = panel)", "resultKind": "实算", "resultText": "交互项系数（DID 估计量）及 CI；事件研究的预趋势系数应不显著。", "interpret": "DID 的核心假设是\"平行趋势\"：若无处理，两组的变化趋势应相同。这个假设不能直接检验，只能通过预趋势、安慰剂检验与敏感性分析间接支持。报告必须包含这三项。", "fig": "fig_did.svg", "figCaption": "图：事件研究。政策前系数接近 0（平行趋势），政策后显著上升。", "packages": ["fixest"], "report": "报告特征工程、交叉验证方案、性能指标、可解释性方法与因果识别假设。", "pitfalls": ["随机 CV 用于空间数据", "把变量重要性当因果", "数据泄漏", "无外部验证"], "assumptions": ["无数据泄漏：特征选择在训练折内完成", "交叉验证匹配数据结构（空间/时间/分组）", "因果结论依赖识别假设（无未观测混杂、排他性等）"], "steps": ["划分训练/测试（按空间或时间分块）", "拟合模型并调参（嵌套 CV）", "评估性能并用 PDP/ALE/SHAP 解释，检验稳健性"], "figNotes": ["政策前系数应接近 0", "政策后上升即为处理效应"], "what": "用处理组与对照组的前后变化估计政策/干预效应。", "why": "野外难以随机化时，DID 是准实验的主力；核心假设是平行趋势，必须用事件研究检验。", "dataProfile": {"name": "模拟数据", "shape": "9 个时期的处理效应与 95% 区间。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "有处理组/对照组与前后多期数据，DID 才能估计政策效应并检验平行趋势。"}, {"id": "17.6", "title": "17.6 倾向得分匹配（PSM）", "lit": [{"text": "Rosenbaum & Rubin (1983). The central role of the propensity score in observational studies for causal effects. *Biometrika* 70: 41–55", "url": "https://search.crossref.org/?q=The%20central%20role%20of%20the%20propensity%20score%20in%20observational%20studies%20for%20causal%20effects"}, {"text": "Ho et al. (2007). Matching as nonparametric preprocessing. *Political Analysis*.", "url": "https://search.crossref.org/?q=Matching%20as%20nonparametric%20preprocessing"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(MatchIt)\nm <- matchit(protected ~ elevation + slope + distance + pop,\n             data = df, method = \"nearest\", ratio = 1)\nsummary(m)\nmatched <- match.data(m)\nlm(biodiversity ~ protected, data = matched)", "resultKind": "实算", "resultText": "匹配前后的标准化偏差、匹配样本量、处理效应。", "interpret": "PSM 只能平衡\"可观测混杂\"，无法处理未观测混杂。报告要给出匹配前后的平衡表（标准化差异 < 0.1）、共同支撑域、以及敏感性分析（如 Rosenbaum bounds）。", "fig": "fig_psm.svg", "figCaption": "图：匹配前后协变量平衡。匹配后所有变量的标准化偏差都降到 10% 以下。", "packages": ["MatchIt"], "report": "报告特征工程、交叉验证方案、性能指标、可解释性方法与因果识别假设。", "pitfalls": ["随机 CV 用于空间数据", "把变量重要性当因果", "数据泄漏", "无外部验证"], "assumptions": ["无数据泄漏：特征选择在训练折内完成", "交叉验证匹配数据结构（空间/时间/分组）", "因果结论依赖识别假设（无未观测混杂、排他性等）"], "steps": ["划分训练/测试（按空间或时间分块）", "拟合模型并调参（嵌套 CV）", "评估性能并用 PDP/ALE/SHAP 解释，检验稳健性"], "figNotes": ["匹配后偏差降到 10% 以下视为平衡", "未观测混杂仍无法排除"], "what": "用可观测变量构造与处理组可比的对照组。", "why": "处理组往往“本来就不一样”；匹配降低选择偏差，但无法处理未观测混杂。", "dataProfile": {"name": "模拟数据", "shape": "5 个协变量在匹配前后的标准化偏差。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "处理组与对照组基线不同，匹配才能让二者可比；但未观测混杂仍无法排除。"}, {"id": "17.7", "title": "17.7 因果森林", "lit": [{"text": "Wager & Athey (2018). Estimation and inference of heterogeneous treatment effects using random forests. *JASA* 113: 1228–1242", "url": "https://search.crossref.org/?q=Estimation%20and%20inference%20of%20heterogeneous%20treatment%20effects%20using%20random%20forests"}, {"text": "Athey & Imbens (2016). Recursive partitioning for heterogeneous causal effects. *PNAS*.", "url": "https://search.crossref.org/?q=Recursive%20partitioning%20for%20heterogeneous%20causal%20effects"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(grf)\ncf <- causal_forest(X = covars, Y = outcome, W = treatment)\naverage_treatment_effect(cf)\ntest_calibration(cf)", "resultKind": "实算", "resultText": "平均处理效应（ATE）、条件处理效应（CATE）分布、校准检验。", "interpret": "因果森林回答\"效应在哪些条件下更大\"，比单一 ATE 更有政策价值。它仍依赖\"无未观测混杂\"假设；`test_calibration` 只能检验异质性是否真实，不能检验混杂。", "fig": "fig_cate.svg", "figCaption": "图：CATE 分布。平均效应为 0.5，但个体间差异很大。", "packages": ["grf"], "report": "报告特征工程、交叉验证方案、性能指标、可解释性方法与因果识别假设。", "pitfalls": ["随机 CV 用于空间数据", "把变量重要性当因果", "数据泄漏", "无外部验证"], "assumptions": ["无数据泄漏：特征选择在训练折内完成", "交叉验证匹配数据结构（空间/时间/分组）", "因果结论依赖识别假设（无未观测混杂、排他性等）"], "steps": ["划分训练/测试（按空间或时间分块）", "拟合模型并调参（嵌套 CV）", "评估性能并用 PDP/ALE/SHAP 解释，检验稳健性"], "figNotes": ["分布越宽，处理效应越异质", "均值附近接近平均处理效应"], "what": "用因果森林估计处理效应随协变量的变化。", "why": "平均效应常掩盖异质性；因果森林回答“在哪些条件下效果更好”，对管理决策更有用。", "dataProfile": {"name": "模拟数据", "shape": "200 个个体的 CATE。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "处理效应可能随环境变化，因果森林才能估计异质性。"}, {"id": "17.8", "title": "17.8 双重机器学习（DML）", "lit": [{"text": "Chernozhukov et al. (2018). Double/debiased machine learning for treatment and structural parameters. *The Econometrics Journal* 21: C1–C68.", "url": "https://search.crossref.org/?q=Double/debiased%20machine%20learning%20for%20treatment%20and%20structural%20parameters"}], "data": [{"text": "模拟数据（生成规则与随机种子见代码）", "url": ""}], "code": "library(DoubleML)\ndml_data <- DoubleMLData$new(df, y_col = \"y\", d_cols = \"treat\", x_cols = covars)\ndml <- DoubleMLPLR$new(dml_data, ml_l = lrn(\"regr.ranger\"),\n                       ml_m = lrn(\"classif.ranger\"), n_folds = 5)\ndml$fit(); dml$summary()", "resultKind": "实算", "resultText": "处理效应的稳健估计与 CI（交叉拟合，避免过拟合偏差）。", "interpret": "DML 用机器学习拟合\"结果模型\"与\"处理模型\"，再用正交矩条件估计因果效应，解决了高维混杂下的正则化偏差。它是目前\"高维 + 因果\"最前沿的工具之一，但同样依赖识别假设。", "fig": "fig_dml.svg", "figCaption": "图：DML 的 200 次模拟估计。分布以真值 0.5 为中心，说明估计近似无偏。", "packages": ["DoubleML", "ranger"], "report": "报告特征工程、交叉验证方案、性能指标、可解释性方法与因果识别假设。", "pitfalls": ["随机 CV 用于空间数据", "把变量重要性当因果", "数据泄漏", "无外部验证"], "assumptions": ["无数据泄漏：特征选择在训练折内完成", "交叉验证匹配数据结构（空间/时间/分组）", "因果结论依赖识别假设（无未观测混杂、排他性等）"], "steps": ["划分训练/测试（按空间或时间分块）", "拟合模型并调参（嵌套 CV）", "评估性能并用 PDP/ALE/SHAP 解释，检验稳健性"], "figNotes": ["分布围绕真值，说明估计近似无偏", "还要看区间覆盖率"], "what": "用交叉拟合的机器学习残差估计处理效应。", "why": "高维混杂下，普通回归的正则化偏差会污染因果估计；DML 用正交矩条件修正，是“高维 + 因果”的前沿工具。", "dataProfile": {"name": "模拟数据", "shape": "200 次模拟的效应估计（真值 0.5）。", "vars": ["生成规则、参数与随机种子均写在页面折叠代码中"], "quirks": "模拟数据的价值是“已知真值”，用于展示方法能否恢复参数；它不能替代真实数据的生态学结论。"}, "fitReason": "协变量多、混杂强，普通回归的正则化偏差会污染效应估计，DML 用交叉拟合修正。"}]}], "meta": {"title": "生态学方法实例库", "entries": 137}};